static BOOTSTRAP_EXPORTS: OnceLock<Arc<tokio::sync::Semaphore>> = OnceLock::new();
static EXACT_SOURCE_ARCHIVE_EXPORTS: OnceLock<Arc<tokio::sync::Semaphore>> = OnceLock::new();

fn exact_source_archive_exports() -> Arc<tokio::sync::Semaphore> {
    Arc::clone(
        EXACT_SOURCE_ARCHIVE_EXPORTS.get_or_init(|| Arc::new(tokio::sync::Semaphore::new(1))),
    )
}

/// Coherent repository-v6 authority for the daemon's primary workspace.
///
/// Opening one reads the durable publication in full and then holds one
/// immutable lease while resolving refs, workspace tree state, and source
/// identities. The raw checkout and Git object database are never consulted.
///
/// The manager is shared rather than owned so a caller that has already paid
/// for one open can hand the same coherent authority to another reader; see
/// [`ProjectionAuthorityCache`].
#[derive(Clone)]
struct ActiveApiRepositoryAuthority {
    manager: Arc<RepositoryAuthorityManager<LocalFileBackend>>,
    repository_id: RepositoryId,
    workspace_id: WorkspaceId,
}

impl ActiveApiRepositoryAuthority {
    fn open(state: &DaemonState) -> Result<Self, (StatusCode, String)> {
        let binding = state
            .local_repository_authority_binding()
            .map_err(repository_authority_error)?;
        let manager = binding.open_manager().map_err(repository_authority_error)?;
        state.projection_authority.record_load();
        Ok(Self {
            manager: Arc::new(manager),
            repository_id: binding.repository_id().clone(),
            workspace_id: binding.workspace_id(),
        })
    }

    #[cfg(test)]
    fn open_layout_for_test(layout: &kin_core::KinLayout) -> Result<Self, (StatusCode, String)> {
        let binding = kin_core::LocalRepositoryAuthorityBinding::from_layout(layout)
            .map_err(repository_authority_error)?;
        let manager = binding.open_manager().map_err(repository_authority_error)?;
        Ok(Self {
            manager: Arc::new(manager),
            repository_id: binding.repository_id().clone(),
            workspace_id: binding.workspace_id(),
        })
    }

    fn workspace_tree_snapshot(&self) -> Result<WorkspaceTreeSnapshot, (StatusCode, String)> {
        self.manager
            .workspace_tree_snapshot(&self.repository_id, &self.workspace_id)
            .map_err(repository_authority_error)?
            .ok_or_else(|| {
                (
                    StatusCode::FAILED_DEPENDENCY,
                    format!(
                        "this repository's authority has no workspace {}",
                        self.workspace_id
                    ),
                )
            })
    }
}

fn repository_authority_error(error: impl std::fmt::Display) -> (StatusCode, String) {
    (
        StatusCode::FAILED_DEPENDENCY,
        format!("this repository's authority could not be opened: {error}"),
    )
}

/// KinDB's commit record for one local repository's durable publication.
///
/// KinDB stages snapshot and delta bodies, fsyncs them, and then atomically
/// replaces this one record; that rename is the commit point. The record
/// content-binds the snapshot digest and every acknowledged delta digest under
/// deterministic serialization, so identical record bytes mean identical
/// durable state by construction, and a record that reads identically twice
/// cannot have moved and returned in between. The converse does not hold: a
/// rewrite is not always a new publication, because opening a legacy store can
/// re-mint this record once while binding validation state. With the label read
/// before the load it describes, that costs one spurious reload and never a
/// stale serve.
const AUTHORITY_PUBLICATION_RECORD: &str = "authority.json";

/// KinDB reads its own record under a 1 MiB bound. A larger file at that path
/// is not a record it wrote, and is reported rather than loaded.
const MAX_AUTHORITY_PUBLICATION_RECORD_BYTES: u64 = 1024 * 1024;

/// Which durable publication a repository's local storage currently holds.
///
/// This is storage-commit metadata, never a semantic answer: it decides only
/// whether an already-loaded authority may be reused, and every answer served
/// still comes from repository-v6 graph truth.
#[derive(Clone, PartialEq, Eq)]
enum LocalPublicationIdentity {
    /// The repository has persisted no authority yet, so its authority is the
    /// unpublished generation-zero state.
    Unpublished,
    Published([u8; 32]),
}

/// Read which publication local storage holds, without loading it.
///
/// The full load this labels reads, hashes, and deserializes the entire graph
/// snapshot. This reads one small record, so a reader can revalidate on every
/// request and pay the full load only when the publication has actually moved
/// — including when it moved under a separate process such as a CLI ingest or
/// commit running beside the daemon.
fn read_local_publication_identity(
    backend: &LocalFileBackend,
    repository_id: &RepositoryId,
) -> Result<LocalPublicationIdentity, (StatusCode, String)> {
    use std::io::Read as _;

    let record = backend
        .base_path()
        .join(repository_id.as_str())
        .join(AUTHORITY_PUBLICATION_RECORD);
    let record_error = |error: std::io::Error| {
        repository_authority_error(format!(
            "cannot read local publication record {}: {error}",
            record.display()
        ))
    };
    // One handle answers both the bound and the contents, so a commit landing
    // mid-check cannot bound one record and return the bytes of another. The
    // bound is enforced by reading a single byte past it rather than by a
    // separate size probe, so nothing measures a record it did not then read,
    // and rejecting an oversized file costs one byte beyond the limit.
    let file = match std::fs::File::open(&record) {
        Ok(file) => file,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            return Ok(LocalPublicationIdentity::Unpublished);
        }
        Err(error) => return Err(record_error(error)),
    };
    let mut bytes = Vec::new();
    file.take(MAX_AUTHORITY_PUBLICATION_RECORD_BYTES + 1)
        .read_to_end(&mut bytes)
        .map_err(record_error)?;
    if bytes.len() as u64 > MAX_AUTHORITY_PUBLICATION_RECORD_BYTES {
        return Err(repository_authority_error(format!(
            "local publication record {} is past the {MAX_AUTHORITY_PUBLICATION_RECORD_BYTES}-byte bound",
            record.display()
        )));
    }
    Ok(LocalPublicationIdentity::Published(
        Sha256::digest(&bytes).into(),
    ))
}

/// One repository-v6 authority per durable publication, shared across the
/// daemon's readers.
///
/// Opening authority is a full snapshot read, SHA-256, and deserialize under an
/// exclusive repository lock, and it re-verifies every persisted body against
/// its content address. Paying that per request makes every request
/// proportional to whole-repository size. Holding one open authority and
/// revalidating it against the durable publication record keeps the answer
/// exactly as fresh while making the common request a small metadata read.
///
/// Three readers hold slots here, because they read through three different
/// crates' authority wrappers: the projection routes
/// (`ActiveApiRepositoryAuthority`, for workspace tree state), the MCP query
/// tools (kin-mcp's `ActiveRepositoryAuthority`, for source projection), and the
/// tools served by kin-cli command helpers (kin-cli's
/// `ActiveRepositoryAuthority`, for entity source and trace bodies). All three
/// slots key on the same [`LocalPublicationIdentity`] under the same load gate
/// and count into the same [`Self::loads`], so the contract is one contract;
/// only the wrapper differs. The name predates the other two readers and is kept
/// because the field it fills is declared elsewhere.
///
/// Three wrappers over one durable state is migration debt, not the design.
/// Collapsing them onto one shared `RepositoryAuthorityManager` would reshape
/// the projection path, so each keeps its own slot and the cost stays
/// O(publications) rather than O(requests) on all three.
#[derive(Default)]
pub(crate) struct ProjectionAuthorityCache {
    held: std::sync::Mutex<Option<HeldProjectionAuthority>>,
    query: std::sync::Mutex<Option<HeldQueryAuthority>>,
    command: std::sync::Mutex<Option<HeldCommandAuthority>>,
    /// The admission values every reconcile task needs, plus the small
    /// open-merge summary a commit gate needs. This is not a fourth wrapper
    /// over the authority, only values read out of one.
    ///
    /// `current_authority_admission` wants a root bundle and a compiled
    /// admission matcher, and neither can differ between tasks inside one
    /// publication: the matcher's own type is documented as "a compiled,
    /// immutable admission-policy generation". Before this slot each
    /// concurrent task opened the whole store for its own copy, and on a
    /// converted psf/requests store six tokio workers were measured inside
    /// that function at one instant, serialized at 2.2 seconds per open
    /// because an open is O(store).
    admission: std::sync::Mutex<Option<HeldAdmission>>,
    /// The refs routes' envelope, keyed on the same publication identity as
    /// every slot above it.
    ref_metadata: std::sync::Mutex<Option<HeldRefMetadata>>,
    /// Serializes misses so a burst of concurrent cold requests pays for one
    /// full load rather than one per request.
    load_gate: std::sync::Mutex<()>,
    loads: std::sync::atomic::AtomicU64,
}

#[derive(Clone)]
struct HeldProjectionAuthority {
    /// The publication this authority is known to be at least as new as.
    ///
    /// Read strictly before the authority it labels was loaded, never after.
    /// A label taken afterwards could name a publication that landed during
    /// the load, which would mark older bytes as current and serve them past
    /// the commit that replaced them.
    published: LocalPublicationIdentity,
    authority: ActiveApiRepositoryAuthority,
}

#[derive(Clone)]
struct HeldQueryAuthority {
    /// Read strictly before the authority it labels was loaded, exactly as for
    /// [`HeldProjectionAuthority::published`] and for the same reason.
    published: LocalPublicationIdentity,
    authority: Arc<kin_mcp::handlers::ActiveRepositoryAuthority>,
}

#[derive(Clone)]
struct HeldCommandAuthority {
    /// Read strictly before the authority it labels was loaded, exactly as for
    /// [`HeldProjectionAuthority::published`] and for the same reason.
    published: LocalPublicationIdentity,
    authority: Arc<kin_cli::commands::repository_authority::ActiveRepositoryAuthority>,
}

/// The repository authority envelope a refs read answers from.
///
/// Held as an `Arc` rather than rebuilt, because the envelope carries an
/// operation log and a receipt per change, so cloning it is O(history) and
/// paying that per request is the same defect one layer down from the open it
/// replaces. The hosted arm already hands out `Arc<PersistedRepositoryAuthority>`
/// out of its generation-bound cache entry; this is the local arm's equivalent.
#[derive(Clone)]
struct HeldRefMetadata {
    /// Read strictly before the authority it came out of was loaded, exactly as
    /// for [`HeldProjectionAuthority::published`] and for the same reason.
    published: LocalPublicationIdentity,
    metadata: Arc<kin_db::PersistedRepositoryAuthority>,
}

#[derive(Clone)]
struct HeldAdmission {
    /// Read strictly before the authority these values came out of was loaded,
    /// exactly as for [`HeldProjectionAuthority::published`] and for the same
    /// reason.
    published: LocalPublicationIdentity,
    roots: kin_model::RootBundle,
    policy: Option<kin_index::ResolvedAdmissionMatcher>,
    open_merge: Option<crate::repository_merge_state::OpenMergeSummary>,
}

impl ProjectionAuthorityCache {
    /// Complete durable-authority loads this daemon state has paid for.
    ///
    /// Every full open counts, whichever route asked for it and whichever
    /// wrapper it produced. One load per publication rather than one per
    /// request is the property this cache exists to make true, and this counter
    /// is how a test states it: it climbs with publications, never with request
    /// volume, and a path that reverted to opening per request climbs with
    /// volume again.
    pub(crate) fn loads(&self) -> u64 {
        self.loads.load(std::sync::atomic::Ordering::Relaxed)
    }

    fn record_load(&self) {
        self.loads
            .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    }

    fn reuse(&self, published: &LocalPublicationIdentity) -> Option<ActiveApiRepositoryAuthority> {
        lock_recover(&self.held)
            .as_ref()
            .filter(|held| &held.published == published)
            .map(|held| held.authority.clone())
    }

    fn install(
        &self,
        published: LocalPublicationIdentity,
        authority: ActiveApiRepositoryAuthority,
    ) {
        *lock_recover(&self.held) = Some(HeldProjectionAuthority {
            published,
            authority,
        });
    }

    fn reuse_query(
        &self,
        published: &LocalPublicationIdentity,
    ) -> Option<Arc<kin_mcp::handlers::ActiveRepositoryAuthority>> {
        lock_recover(&self.query)
            .as_ref()
            .filter(|held| &held.published == published)
            .map(|held| Arc::clone(&held.authority))
    }

    fn install_query(
        &self,
        published: LocalPublicationIdentity,
        authority: Arc<kin_mcp::handlers::ActiveRepositoryAuthority>,
    ) {
        *lock_recover(&self.query) = Some(HeldQueryAuthority {
            published,
            authority,
        });
    }

    fn reuse_admission(&self, published: &LocalPublicationIdentity) -> Option<HeldAdmission> {
        lock_recover(&self.admission)
            .as_ref()
            .filter(|held| &held.published == published)
            .cloned()
    }

    fn install_admission(&self, admission: HeldAdmission) {
        *lock_recover(&self.admission) = Some(admission);
    }

    fn reuse_command(
        &self,
        published: &LocalPublicationIdentity,
    ) -> Option<Arc<kin_cli::commands::repository_authority::ActiveRepositoryAuthority>> {
        lock_recover(&self.command)
            .as_ref()
            .filter(|held| &held.published == published)
            .map(|held| Arc::clone(&held.authority))
    }

    fn install_command(
        &self,
        published: LocalPublicationIdentity,
        authority: Arc<kin_cli::commands::repository_authority::ActiveRepositoryAuthority>,
    ) {
        *lock_recover(&self.command) = Some(HeldCommandAuthority {
            published,
            authority,
        });
    }

    fn reuse_ref_metadata(
        &self,
        published: &LocalPublicationIdentity,
    ) -> Option<Arc<kin_db::PersistedRepositoryAuthority>> {
        lock_recover(&self.ref_metadata)
            .as_ref()
            .filter(|held| &held.published == published)
            .map(|held| Arc::clone(&held.metadata))
    }

    fn install_ref_metadata(
        &self,
        published: LocalPublicationIdentity,
        metadata: Arc<kin_db::PersistedRepositoryAuthority>,
    ) {
        *lock_recover(&self.ref_metadata) = Some(HeldRefMetadata {
            published,
            metadata,
        });
    }

    fn invalidate(&self) {
        *lock_recover(&self.held) = None;
        *lock_recover(&self.query) = None;
        *lock_recover(&self.command) = None;
        *lock_recover(&self.ref_metadata) = None;
    }
}

/// Refuse a storage namespace that is no longer the one this daemon pinned.
///
/// Opening authority performs this check itself, so reusing a held authority
/// has to perform it too; otherwise a `.kin/kindb` namespace replaced under the
/// daemon would keep being answered from the authority of the store it
/// replaced. The probe decodes no snapshot and takes no repository lock.
fn confirm_pinned_projection_namespace(
    backend: &LocalFileBackend,
    repository_id: &RepositoryId,
) -> Result<(), (StatusCode, String)> {
    match backend.probe_pinned_repository_namespace(repository_id.as_str()) {
        kin_db::LocalNamespaceProbe::Retained => Ok(()),
        kin_db::LocalNamespaceProbe::Absent => Err(repository_authority_error(format!(
            "local storage authority does not hold repository namespace {repository_id}"
        ))),
        kin_db::LocalNamespaceProbe::IdentityLost(fault) => Err(repository_authority_error(fault)),
        kin_db::LocalNamespaceProbe::Unavailable(error) => Err(repository_authority_error(error)),
    }
}

/// Resolve the repository-v6 authority the projection routes answer from.
///
/// Blocking: reads storage metadata and, on a publication change, loads the
/// complete durable authority. Callers run it on a blocking thread.
fn projection_repository_authority(
    state: &DaemonState,
) -> Result<ActiveApiRepositoryAuthority, (StatusCode, String)> {
    let backend = state.local_repository_backend().ok_or_else(|| {
        repository_authority_error("local daemon is missing its startup storage capability")
    })?;
    let repository_id = state
        .local_repository_authority_binding()
        .map_err(repository_authority_error)?
        .repository_id()
        .clone();

    if let Err(error) = confirm_pinned_projection_namespace(&backend, &repository_id) {
        state.projection_authority.invalidate();
        return Err(error);
    }

    let published = read_local_publication_identity(&backend, &repository_id)?;
    if let Some(authority) = state.projection_authority.reuse(&published) {
        return Ok(authority);
    }

    let _load = lock_recover(&state.projection_authority.load_gate);
    // Re-read under the gate: the publication may have moved while this
    // request waited, and the label installed below must be the one taken
    // before the load it describes.
    let published = read_local_publication_identity(&backend, &repository_id)?;
    if let Some(authority) = state.projection_authority.reuse(&published) {
        return Ok(authority);
    }
    let authority = ActiveApiRepositoryAuthority::open(state)?;
    state
        .projection_authority
        .install(published, authority.clone());
    // Whether reuse is actually holding is not visible from request latency
    // alone, and a count that climbs with request volume rather than with
    // publications is the signal that it is not.
    tracing::debug!(
        repository = %authority.repository_id,
        loads = state.projection_authority.loads(),
        "projection repository authority loaded"
    );
    Ok(authority)
}

/// The repository authority envelope a local daemon's refs routes answer from.
///
/// Blocking: reads storage metadata and, on a publication change, loads the
/// complete durable authority. Callers run it on a blocking thread.
///
/// This exists because `/repos/{repo_id}/refs` used to reach
/// [`ActiveApiRepositoryAuthority::open`] directly on every request, and an
/// open reads the durable publication in full, so the read was proportional to
/// whole-repository size rather than to the ref set it returns. Measured on
/// 2026-09-04 against a `kin init` store of firelock-ai/kin itself (2864
/// changes, 111 refs, a 21685-byte response): ten cold reads had a median of
/// 39.33 s and ten warm reads on the same daemon a median of 44.63 s, which is
/// the same distribution because there was nothing to warm into. The hosted
/// route in front of it refuses at 12 s.
///
/// The envelope is cached per durable publication rather than per request, in
/// the same [`ProjectionAuthorityCache`] and against the same publication
/// identity as the three authority wrappers beside it, so it inherits their
/// invalidation contract instead of adding a second one. The label is read
/// before the load it describes, which at worst costs one spurious reload and
/// never serves a publication that has moved.
fn local_repository_ref_metadata(
    state: &DaemonState,
) -> Result<Arc<kin_db::PersistedRepositoryAuthority>, (StatusCode, String)> {
    let backend = state.local_repository_backend().ok_or_else(|| {
        repository_authority_error("local daemon is missing its startup storage capability")
    })?;
    let repository_id = state
        .local_repository_authority_binding()
        .map_err(repository_authority_error)?
        .repository_id()
        .clone();
    // The pinned-namespace probe runs before the reuse check, exactly as the
    // three sibling resolvers run it, so a `.kin/kindb` replaced under the
    // daemon cannot keep being answered from the envelope of the store it
    // replaced. It decodes no snapshot and takes no repository lock.
    if let Err(error) = confirm_pinned_projection_namespace(&backend, &repository_id) {
        state.projection_authority.invalidate();
        return Err(error);
    }

    let published = read_local_publication_identity(&backend, &repository_id)?;
    if let Some(metadata) = state.projection_authority.reuse_ref_metadata(&published) {
        return Ok(metadata);
    }

    // The authority open itself is already cached and gated one layer down, so
    // this reaches a full open only when that slot misses too.
    let authority = projection_repository_authority(state)?;
    // Re-check after that open. A burst of concurrent cold requests is
    // serialized by the gate inside `projection_repository_authority` and then
    // released one at a time into the clone below, and the clone is O(history);
    // whoever loses the race takes the envelope the winner installed instead of
    // cloning a second copy of it.
    if let Some(metadata) = state.projection_authority.reuse_ref_metadata(&published) {
        return Ok(metadata);
    }
    let metadata = {
        let lease = authority.manager.read_authority();
        lease
            .snapshot()
            .repository_authority
            .as_ref()
            .ok_or_else(|| {
                (
                    StatusCode::FAILED_DEPENDENCY,
                    "snapshot has no repository-v6 authority envelope".to_string(),
                )
            })?
            .clone()
    };
    let metadata = Arc::new(metadata);
    state
        .projection_authority
        .install_ref_metadata(published, Arc::clone(&metadata));
    Ok(metadata)
}

/// Resolve the repository-v6 authority the MCP query tools read source from.
///
/// The same contract as [`projection_repository_authority`], for the other
/// wrapper: probe the pinned namespace, read which publication local storage
/// holds, reuse the authority already loaded at that publication, and otherwise
/// perform one full validating open behind the shared load gate.
///
/// STALENESS, EXACTLY. A query served from a reused authority answers from the
/// durable publication whose record this function read just before handing the
/// authority over. That is the publication a fresh open at that same instant
/// would have loaded, and both would decode the same content-addressed bytes
/// under the same validation, so the reused answer IS the fresh answer -- a
/// reused open is not an approximation of one. What such a query cannot observe
/// is a commit that lands after its publication read; neither can a fresh open,
/// which also samples storage once and then answers from what it sampled. Every
/// call reads the record again, so a publication that lands between two calls
/// is observed by the second, including one committed by a separate process
/// such as a CLI ingest running beside the daemon. The record digest errs in
/// the safe direction: identical record bytes mean identical durable state, and
/// a rewrite that is not a new publication costs one extra full load rather
/// than a stale serve.
///
/// Reuse never weakens what an open proves. KinDB re-verifies every persisted
/// body against its content address on every open, and this function cannot
/// reach past that: it either hands back the result of one that already ran for
/// these exact durable bytes, or it performs one.
///
/// Blocking: reads storage metadata and, on a publication change, loads the
/// complete durable authority.
fn query_repository_authority(
    state: &DaemonState,
) -> Result<Arc<kin_mcp::handlers::ActiveRepositoryAuthority>, (StatusCode, String)> {
    let backend = state.local_repository_backend().ok_or_else(|| {
        repository_authority_error("local daemon is missing its startup storage capability")
    })?;
    let binding = state
        .local_repository_authority_binding()
        .map_err(repository_authority_error)?;
    let repository_id = binding.repository_id().clone();

    if let Err(error) = confirm_pinned_projection_namespace(&backend, &repository_id) {
        state.projection_authority.invalidate();
        return Err(error);
    }

    let published = read_local_publication_identity(&backend, &repository_id)?;
    if let Some(authority) = state.projection_authority.reuse_query(&published) {
        return Ok(authority);
    }

    let _load = lock_recover(&state.projection_authority.load_gate);
    // Re-read under the gate: the publication may have moved while this request
    // waited, and the label installed below must be the one taken before the
    // load it describes.
    let published = read_local_publication_identity(&backend, &repository_id)?;
    if let Some(authority) = state.projection_authority.reuse_query(&published) {
        return Ok(authority);
    }
    let authority = Arc::new(
        kin_mcp::handlers::ActiveRepositoryAuthority::open(&binding)
            .map_err(repository_authority_error)?,
    );
    state.projection_authority.record_load();
    state
        .projection_authority
        .install_query(published, Arc::clone(&authority));
    tracing::debug!(
        repository = %repository_id,
        loads = state.projection_authority.loads(),
        "query repository authority loaded"
    );
    Ok(authority)
}

/// Resolve the repository-v6 authority the kin-cli-backed query tools read
/// source from: `get_entity_source`, `get_entity_sources`, `trace_data_flow`.
///
/// The same contract as [`query_repository_authority`], for the third wrapper.
/// Those three tools resolve source through kin-cli command helpers, whose own
/// `ActiveRepositoryAuthority` is a different type over the same durable state,
/// so sharing the query slot's authority with them is not possible without
/// reshaping how they read. Sharing the CONTRACT is: same publication key, same
/// load gate, same counter, and the full staleness argument stated at
/// [`query_repository_authority`] applies here unchanged.
///
/// What this removes is worse than one open per request. `get_entity_sources`
/// resolves source per entity, and each resolution opened its own authority, so
/// a batch of N entities paid N whole-store verifications. Every batch now reads
/// at one publication through one open, which also makes the batch coherent:
/// per-entity opens could straddle a publication and return rows from two
/// different generations.
///
/// Blocking: reads storage metadata and, on a publication change, loads the
/// complete durable authority.
fn command_repository_authority(
    state: &DaemonState,
) -> Result<
    Arc<kin_cli::commands::repository_authority::ActiveRepositoryAuthority>,
    (StatusCode, String),
> {
    let backend = state.local_repository_backend().ok_or_else(|| {
        repository_authority_error("local daemon is missing its startup storage capability")
    })?;
    let binding = state
        .local_repository_authority_binding()
        .map_err(repository_authority_error)?;
    let repository_id = binding.repository_id().clone();

    if let Err(error) = confirm_pinned_projection_namespace(&backend, &repository_id) {
        state.projection_authority.invalidate();
        return Err(error);
    }

    let published = read_local_publication_identity(&backend, &repository_id)?;
    if let Some(authority) = state.projection_authority.reuse_command(&published) {
        return Ok(authority);
    }

    let _load = lock_recover(&state.projection_authority.load_gate);
    // Re-read under the gate: the publication may have moved while this request
    // waited, and the label installed below must be the one taken before the
    // load it describes.
    let published = read_local_publication_identity(&backend, &repository_id)?;
    if let Some(authority) = state.projection_authority.reuse_command(&published) {
        return Ok(authority);
    }
    let authority = Arc::new(
        kin_cli::commands::repository_authority::ActiveRepositoryAuthority::open(&binding)
            .map_err(repository_authority_error)?,
    );
    state.projection_authority.record_load();
    state
        .projection_authority
        .install_command(published, Arc::clone(&authority));
    tracing::debug!(
        repository = %repository_id,
        loads = state.projection_authority.loads(),
        "command repository authority loaded"
    );
    Ok(authority)
}

/// The admission pair for the current publication, from one open per
/// publication rather than one per task.
///
/// Same shape as [`command_repository_authority`] above and deliberately so: a
/// reviewer should be able to diff the two. Read the publication, try the slot,
/// take the load gate, re-read under it because the publication may have moved
/// while this request waited, try again, and only then pay for the open.
///
/// What this replaces: `loop_runner::current_authority_admission` opened the
/// whole store on every call, and its three callers reach it independently from
/// concurrent tasks. Measured on a converted psf/requests store, six tokio
/// workers sat inside it at one instant, each in a whole-store open serialized
/// at 2.205 seconds, which is what one open costs warm there. Neither value it
/// reads can differ between tasks inside one publication, so the cost was paid
/// per arrival for an answer that could not vary.
fn cached_authority_admission_entry(
    state: &DaemonState,
) -> Result<HeldAdmission, (StatusCode, String)> {
    let backend = state.local_repository_backend().ok_or_else(|| {
        repository_authority_error("local daemon is missing its startup storage capability")
    })?;
    let binding = state
        .local_repository_authority_binding()
        .map_err(repository_authority_error)?;
    let repository_id = binding.repository_id().clone();

    let published = read_local_publication_identity(&backend, &repository_id)?;
    if let Some(admission) = state.projection_authority.reuse_admission(&published) {
        return Ok(admission);
    }

    let _load = lock_recover(&state.projection_authority.load_gate);
    // Re-read under the gate: the publication may have moved while this request
    // waited, and the label installed below must be the one taken before the
    // open it describes.
    let published = read_local_publication_identity(&backend, &repository_id)?;
    if let Some(admission) = state.projection_authority.reuse_admission(&published) {
        return Ok(admission);
    }

    let context =
        crate::local_repository_authority::LocalRepositoryAuthorityContext::from_state(state)
            .map_err(|error| repository_authority_error(error.to_string()))?;
    let authority = context
        .open()
        .map_err(|error| repository_authority_error(error.to_string()))?;
    state.projection_authority.record_load();
    let lease = authority.read_authority();
    let roots = lease.roots().clone();
    let open_merge =
        crate::repository_merge_state::open_merge_summary(&lease, context.workspace_id());
    drop(lease);
    let policy = authority
        .workspace_admission_snapshot(context.repository_id(), &context.workspace_id())
        .map_err(|error| repository_authority_error(error.to_string()))?
        .map(|snapshot| snapshot.matcher);
    let admission = HeldAdmission {
        published,
        roots,
        policy,
        open_merge,
    };
    state
        .projection_authority
        .install_admission(admission.clone());
    tracing::debug!(
        repository = %repository_id,
        loads = state.projection_authority.loads(),
        "admission pair loaded"
    );
    Ok(admission)
}

pub(crate) fn cached_authority_admission(
    state: &DaemonState,
) -> Result<
    (
        kin_model::RootBundle,
        Option<kin_index::ResolvedAdmissionMatcher>,
    ),
    (StatusCode, String),
> {
    let admission = cached_authority_admission_entry(state)?;
    Ok((admission.roots, admission.policy))
}

pub(crate) fn cached_authority_has_open_merge(
    state: &DaemonState,
) -> Result<bool, (StatusCode, String)> {
    Ok(cached_authority_admission_entry(state)?
        .open_merge
        .is_some())
}

fn refuse_commit_during_open_merge(state: &DaemonState) -> Result<(), (StatusCode, String)> {
    let admission = cached_authority_admission_entry(state)?;
    let Some(open_merge) = admission.open_merge else {
        return Ok(());
    };
    let resolved_count = open_merge.conflict_count - open_merge.unresolved_count;
    let completion = if open_merge.unresolved_count == 0 {
        "publish it with `kin resolve --do-continue`".to_string()
    } else {
        format!(
            "settle its remaining {} conflict(s) with `kin resolve`, then publish it with `kin \
             resolve --do-continue`",
            open_merge.unresolved_count
        )
    };
    Err((
        StatusCode::CONFLICT,
        format!(
            "commit refused: merge transaction {} for {} into {} is still open ({} of {} \
             conflict(s) settled); {completion}, or abandon it with `kin resolve --abort` before \
             committing",
            open_merge.transaction,
            open_merge.source_ref,
            open_merge.target_ref,
            resolved_count,
            open_merge.conflict_count,
        ),
    ))
}

/// Hand a command helper an authority this daemon already resolved.
///
/// The eager form: every caller reaches it only after deciding the request
/// projects bodies, so there is no publication it might not consult and nothing
/// to defer. The freshness obligation the shared arm states is discharged by
/// [`command_repository_authority`], which read the publication record before
/// the load it labels.
fn shared_command_authority(
    binding: kin_core::LocalRepositoryAuthorityBinding,
    authority: Arc<kin_cli::commands::repository_authority::ActiveRepositoryAuthority>,
) -> kin_cli::commands::repository_authority::RequestRepositoryAuthority {
    kin_cli::commands::repository_authority::RequestRepositoryAuthority::shared(
        binding,
        Arc::new(move || Ok(Arc::clone(&authority))),
    )
}

/// The authority source for an MCP route that resolves source through a kin-cli
/// command helper.
fn require_mcp_command_repository_authority(
    state: &DaemonState,
) -> kin_mcp::Result<kin_cli::commands::repository_authority::RequestRepositoryAuthority> {
    let binding = require_mcp_local_repository_binding(state)?;
    let authority =
        command_repository_authority(state).map_err(|(_, message)| mcp_authority_gap(message))?;
    Ok(shared_command_authority(binding, authority))
}

/// Fail closed when an explicit filesystem-admission command is unavailable.
///
/// Filesystem reads are permitted only at this named ingestion boundary. They
/// never become query/history/VFS authority and cannot silently repair a
/// repository-v6 gap.
fn filesystem_ingest_disabled_response(endpoint: &str, path: &str) -> (StatusCode, String) {
    (
        StatusCode::CONFLICT,
        json!({
            "error": "filesystem_admission_disabled",
            "endpoint": endpoint,
            "path": path,
            "mutation_applied": false,
            "authority": "repository_v6",
            "configuration": crate::loop_runner::DISABLE_FILESYSTEM_RECONCILE_ENV,
        })
        .to_string(),
    )
}

fn hold_exact_source_archive_permit<T, E>(
    permit: tokio::sync::OwnedSemaphorePermit,
    work: impl FnOnce() -> Result<T, E>,
) -> Result<(T, tokio::sync::OwnedSemaphorePermit), E> {
    let output = work()?;
    Ok((output, permit))
}

/// Own the archive bytes and their memory-admission permit together. `Bytes`
/// retains this owner across response-body and hyper socket-buffer clones, so
/// admission cannot reopen while any copy still keeps the allocation alive.
struct ExactSourceArchiveAllocation {
    archive: Vec<u8>,
    _permit: tokio::sync::OwnedSemaphorePermit,
}

impl ExactSourceArchiveAllocation {
    fn new(archive: Vec<u8>, permit: tokio::sync::OwnedSemaphorePermit) -> Self {
        Self {
            archive,
            _permit: permit,
        }
    }
}

impl AsRef<[u8]> for ExactSourceArchiveAllocation {
    fn as_ref(&self) -> &[u8] {
        &self.archive
    }
}

fn exact_source_archive_body(
    archive: Vec<u8>,
    permit: tokio::sync::OwnedSemaphorePermit,
) -> axum::body::Body {
    axum::body::Body::from(axum::body::Bytes::from_owner(
        ExactSourceArchiveAllocation::new(archive, permit),
    ))
}

/// Acquire a `std::sync::Mutex`, recovering the guard if the lock was poisoned
/// by a panic in a prior holder.
///
/// The daemon's request-path locks guard simple in-memory map operations
/// (`insert`/`get`/`remove`/`clone`) that leave the data structurally
/// consistent even if a holder unwound mid-way. Propagating the poison would
/// turn one transient panic into a permanent `500` on every later request that
/// touches the lock (poison is sticky until restart). Recovering keeps the
/// path serving instead, which is the correct treatment here and never panics.
fn lock_recover<T>(mutex: &std::sync::Mutex<T>) -> std::sync::MutexGuard<'_, T> {
    mutex
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
}

/// Health check response.
#[derive(Debug, Serialize, serde::Deserialize)]
pub struct HealthResponse {
    pub status: String,
    /// Last hosted-reader admission verdict observed by this process. This is
    /// diagnostic only: `/ready` and `/readiness` re-read durable authority and
    /// are the fail-closed admission gates. `/health` remains process liveness
    /// even when this is false.
    #[serde(default)]
    pub reader_admitted: bool,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub reader_admission_error: Option<String>,
    pub version: String,
    pub uptime_seconds: u64,
    pub graph_entity_count: Option<usize>,
    /// Entities durable repository authority carried when this daemon last
    /// levelled its query graph with authority (FIR-2421).
    ///
    /// `graph_entity_count` above is the LIVE count, and the daemon admits host
    /// content into that graph continuously without recording any of it, so the
    /// two differ by exactly the work a daemon exit would lose. Absent, never
    /// zero, when this daemon has never levelled: an unknown durable count and
    /// an empty durable authority are different answers, and only one of them
    /// means the live graph is entirely uncommitted.
    #[serde(default)]
    pub durable_entity_count: Option<u64>,
    /// Relations in the live query graph.
    ///
    /// The half the entity pair above could not answer. A store whose entity
    /// counts were level published an all-clear over 3,438 relations a
    /// language-server sweep had written into the live graph and no commit
    /// carried, because nothing on this endpoint counted them (FIR-3202).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub graph_relation_count: Option<usize>,
    /// Relations durable repository authority carried at the same levelling as
    /// `durable_entity_count`. Absent, never zero, when this daemon has never
    /// levelled.
    #[serde(default)]
    pub durable_relation_count: Option<u64>,
    pub graph_loaded: bool,
    pub reconciliation_status: String,
    pub repo_id: String,
    /// Exact local workspace authority. Hosted snapshot daemons do not carry a
    /// local workspace and report `null`.
    #[serde(default)]
    pub workspace_id: Option<String>,
    pub repo_root: String,
    pub pid: u32,
    #[serde(default)]
    pub active_request_count: u64,
    #[serde(default)]
    pub event_subscriber_count: u64,
    #[serde(default)]
    pub external_session_count: u64,
    #[serde(default)]
    pub idle_seconds: u64,
    /// Whether the daemon has loaded a snapshot or completed its first
    /// reconciliation cycle (graph-trust signal for clients/operators).
    #[serde(default)]
    pub initialized: bool,
    /// Whether the most recent filesystem-sync tick refused a suspected
    /// mass-deletion wipe. When true, the graph is intact but in-flight bulk
    /// removals are being withheld pending operator confirmation
    /// (`KIN_ALLOW_MASS_DELETION=1`).
    #[serde(default)]
    pub mass_deletion_blocked: bool,
    /// Whether the background embedding worker has permanently stopped after
    /// exhausting its panic budget. The daemon keeps serving graph/locate/
    /// reconcile (embeddings are a derived index); the vector index is frozen
    /// until restart. A true value drives `status: "attention"`.
    #[serde(default)]
    pub embed_worker_failed: bool,
    /// Whether this daemon lacks a safe durable checkpoint for embedding/vector
    /// progress. A backend may lack the capability entirely, or a corrupt or
    /// indeterminate artifact may leave no trustworthy compare-and-swap cursor.
    /// This is distinct from a worker crash: the worker is intentionally
    /// disabled and `/embed` fails closed. A true value drives
    /// `status: "attention"`.
    #[serde(default)]
    pub embed_persistence_unavailable: bool,
    /// Exact hosted vector publication state. Absent for local repositories.
    /// The boolean above remains the compatibility gate; this record explains
    /// whether a hosted store is empty, backfilling, ready, repairable, in
    /// conflict recovery, or indeterminate and carries bounded cursor/digest
    /// evidence for operators and acceptance checks.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub hosted_vector_persistence: Option<crate::state::HostedVectorPersistenceHealth>,
    /// Why a persisted local or hosted vector artifact was not installed when
    /// this daemon opened. The graph is intact and every query is still served;
    /// the index is being re-derived from zero, which is worth stating because
    /// the only other evidence is a coverage counter that restarted without
    /// explanation. A value drives `status: "attention"`.
    ///
    /// This describes one daemon's open and so holds for that process's life,
    /// the same way `embed_worker_failed` does, rather than clearing when the
    /// rebuild catches up. `kin health` is the surface that tracks the rebuild
    /// and goes quiet once coverage is whole.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub vector_index_discarded: Option<String>,
    /// What a per-key salvage retired when this daemon opened, when one
    /// happened. A value drives `status: "attention"`, exactly as a discard
    /// does, because both mean this store is serving off less coverage than it
    /// had.
    ///
    /// The field above cannot carry this. A salvage INSTALLS an index, so
    /// nothing is discarded and the counters read measured and short, which is
    /// byte-identical to a store filling for the first time. That is what let a
    /// store publish `1770/2112 indexed (342 pending)` three minutes after
    /// retiring 342 vectors, with every surface reporting `ok` (FIR-2562).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub vector_index_salvage: Option<kin_cli::commands::resources::VectorSalvage>,
    /// Effective filesystem-to-graph admission policy. This reports the frozen
    /// daemon state, including intrinsic storage-backend graph authority, not
    /// merely whether the opt-in environment variable was present.
    #[serde(default)]
    pub filesystem_reconcile_disabled: bool,
    /// Whether an operator turned the automatic background embedding pass off
    /// (`KIN_DAEMON_AUTO_EMBED` falsy). Distinct from
    /// `embed_persistence_unavailable`, which is the daemon refusing because it
    /// cannot durably persist a sidecar. Deferred, not disabled: an explicit
    /// embed request still runs. Does not drive `status: "attention"`, because
    /// it is a chosen configuration rather than a fault.
    #[serde(default)]
    pub background_embed_deferred: bool,
    /// Monotonic authority-head marker (`.kin/kindb/head-generation`), bumped
    /// when the daemon commits a newer graph snapshot. A freshness token that
    /// lets clients and the MCP envelope express `graph_as_of` and detect stale
    /// reads. Additive; `0` before the first snapshot is committed.
    #[serde(default)]
    pub graph_generation: u64,
    /// Behavior-relevant environment the daemon worker captured at process
    /// start (variable name → value, or `null` when unset). A repo daemon
    /// inherits its environment from whichever command first started it and does
    /// not pick up a later command's per-invocation overrides; a client compares
    /// this against its own environment to surface a silently-ignored knob. See
    /// `kin_core::behavior_env`.
    #[serde(default)]
    pub behavior_env: kin_core::behavior_env::BehaviorEnv,
    /// Effective coordination mode and exact surface/capability coverage for
    /// operator and benchmark attestation.
    #[serde(default)]
    pub coordination: Option<kin_cli::commands::bench_meta::CoordinationMeta>,
    /// Must remain zero for a coordination-event stream to be eligible as a
    /// complete citable measurement source during this daemon lifetime.
    #[serde(default)]
    pub coordination_event_persist_failures: Option<u64>,
    /// A cross-repo spine warm-up is loading sibling repository graphs right
    /// now. The daemon is alive and serving its own repo throughout; this is
    /// the signal that distinguishes "busy" from "dead".
    #[serde(default)]
    pub spine_warming: bool,
    /// Cumulative CPU seconds this daemon process has consumed. The answer to
    /// "why is my fan on" belongs in the product rather than in Activity
    /// Monitor. Absent before the background-work supervisor's first sample,
    /// which is not the same as zero.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub daemon_cpu_seconds: Option<f64>,
    /// Every background pass this daemon has actually started, with how long
    /// each has been working and how long since it last recorded persisted
    /// progress. A pass carrying a `stopped_reason` was stopped for spending the
    /// machine without advancing, and drives `status: "attention"`.
    #[serde(default)]
    pub background_passes: Vec<kin_cli::commands::resources::BackgroundPassReport>,
    /// What the filesystem reconciliation loop has admitted, dropped, and last
    /// failed at. A degraded reconcile state drives `status: "attention"`.
    ///
    /// Distinct from `reconciliation_status`, which reports whether a pass is
    /// running right now and is satisfied by a loop that runs constantly and
    /// admits nothing. These are the outcomes.
    #[serde(default)]
    pub reconcile: kin_cli::commands::resources::ReconcileHealth,
    /// Consecutive `kin_graph_status` calls that could not sample this daemon
    /// live, reset by the first that does. Past
    /// [`GRAPH_STATUS_UNANSWERABLE_STREAK`] it drives `status: "attention"`.
    ///
    /// FIR-2136: a daemon can stop being able to answer a live question about
    /// itself while every other term here stays healthy, and the surface that
    /// exists to report ill health was the one that could not see it. Additive
    /// and defaulted, so a client on either side of this change still parses.
    #[serde(default)]
    pub status_live_sample_failures: u64,
    pub build: BuildResponse,
}

