#[derive(Debug, Serialize, Deserialize)]
pub struct RepoHealthResponse {
    pub repo_id: String,
    pub entity_count: usize,
    pub graph_loaded: bool,
    #[serde(default)]
    pub initialized: bool,
    #[serde(default)]
    pub mass_deletion_blocked: bool,
    #[serde(default)]
    pub embed_worker_failed: bool,
    #[serde(default)]
    pub embed_persistence_unavailable: bool,
    #[serde(default)]
    pub filesystem_reconcile_disabled: bool,
    /// Why views derived from repository authority are behind it, when they
    /// are. Set by a transfer whose authority became durable and whose derived
    /// refresh then failed; absent means they match.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub derived_views_stale: Option<String>,
    /// Consecutive status calls that could not sample this repo's graph live.
    /// FIR-2136; the same tally `/health` grades, carried here because this is
    /// the repo-scoped surface the ticket names.
    #[serde(default)]
    pub status_live_sample_failures: u64,
    /// Whether this daemon can still answer a live question about itself.
    /// False is the wedged reading, and it is the one a supervisor acts on.
    #[serde(default = "default_true")]
    pub status_answerable: bool,
    /// Hosted semantic tool contracts available for this addressed repository.
    #[serde(default)]
    pub semantic_capabilities: Vec<String>,
    /// What this daemon's generation-bound repository read cache has done
    /// since the process started (FIR-2924).
    #[serde(default)]
    pub repository_read_cache: RepositoryReadCacheHealth,
}

/// How often repository reads reused a generation's already-resolved tree.
///
/// Reported rather than logged, because a cache whose hits and misses are
/// invisible cannot be told apart from one that is not running at all. Both
/// counts at zero on a daemon that has served repository reads means the cache
/// is not being reached, which is a different fault from a cache that is
/// missing every time.
#[derive(Debug, Clone, Copy, Default, Serialize, Deserialize)]
pub struct RepositoryReadCacheHealth {
    /// Reads answered from the tree this generation had already resolved.
    pub hits: u64,
    /// Reads that had to resolve a tree, including every read addressed at a
    /// change that is not this generation's default-ref head.
    pub misses: u64,
}

/// Serde default for a boolean whose healthy value is `true`, so a payload from
