/// POST /commands/stash: seal, list, or restore exact workspace state.
async fn command_stash(
    headers: axum::http::HeaderMap,
    State(state): State<Arc<DaemonState>>,
    Json(request): Json<kin_cli::commands::stash::StashRequest>,
) -> Result<impl IntoResponse, (StatusCode, String)> {
    if !state
        .is_initialized
        .load(std::sync::atomic::Ordering::Relaxed)
    {
        return Err((
            StatusCode::SERVICE_UNAVAILABLE,
            "daemon not fully initialized".to_string(),
        ));
    }
    if state.storage_backend.is_some() {
        return Err((
            StatusCode::CONFLICT,
            "local repository stash authority is unavailable for hosted snapshot authority"
                .to_string(),
        ));
    }
    if extract_session_id_from_headers(&headers)?.is_some() {
        return Err((
            StatusCode::CONFLICT,
            "stash commands do not accept X-Kin-Session because they seal and restore the primary \
             repository workspace"
                .to_string(),
        ));
    }

    if !request.is_mutation() {
        return Ok(Json(crate::repository_stash::execute(&state, &request)?));
    }
    if state.filesystem_reconcile_disabled() {
        return Err(filesystem_ingest_disabled_response(
            "/commands/stash",
            &state.layout.working_dir().display().to_string(),
        ));
    }

    // Seal and restore both decide against the exact workspace the host
    // actually holds, so the complete-scan admission runs first under the same
    // uninterrupted coordination gate. Without it a stash would seal whatever
    // authority happened to hold, and a restore would judge "is this workspace
    // clean" against a stale answer.
    let _coordination = state.coordination_gate.lock().await;
    crate::loop_runner::sync_filesystem_with_graph_under_coordination(&state)
        .await
        .map_err(internal_error)?;
    // That sync is a complete exact-tree admission publishing its tree standalone,
    // so the admission is durable the moment it returns and is recorded here, on
    // the same probes and in the same durable marker the ambient reconcile tick,
    // `kin admit` and a commit write. Without it a user who sealed or restored a
    // stash had just had their whole working copy admitted and `kin graph status`
    // still answered that no complete admission was recorded for the store.
    //
    // Before the stash executes rather than after, and counted here, because this
    // is the tree the admission published. The seal that follows returns the
    // workspace to its base and writes that move as its own authority, which is
    // the stash operating rather than a second admission; counting after it would
    // record a tree no admission had passed over.
    state
        .background_work
        .reconcile()
        .record_admission_success(std::time::Instant::now());
    crate::background_work::record_durable_admission(
        &state.layout,
        state.graph.resolved_tree().len() as u64,
    );
    let response = crate::repository_stash::execute(&state, &request)?;
    Ok(Json(response))
}

