/// POST /reconcile — admit one twice-verified disposable-session observation.
///
/// Filesystem reads occur only in `observe_session_workspace`. Repository
/// authority and the primary graph-derived projection then move together
/// through the repository-v6 projection WAL. Semantic parsing is derived,
/// optional follow-up work and never controls exact membership.
async fn reconcile_session_workspace(
    State(state): State<Arc<DaemonState>>,
    Json(request): Json<kin_cli::commands::reconcile::ReconcileRequest>,
) -> Result<impl IntoResponse, (StatusCode, String)> {
    if !state
        .is_initialized
        .load(std::sync::atomic::Ordering::Relaxed)
    {
        return Err((
            StatusCode::SERVICE_UNAVAILABLE,
            "daemon not fully initialized".to_string(),
        ));
    }
    if state.storage_backend.is_some() {
        return Err((
            StatusCode::CONFLICT,
            "exact local session reconciliation is unavailable for hosted snapshot authority"
                .to_string(),
        ));
    }

    let _coordination = state.coordination_gate.lock().await;
    let graph_mutation = state.begin_graph_authority_mutation();
    let repository_authority = state
        .local_repository_authority_binding()
        .map_err(repository_authority_error)?;
    let observation = kin_cli::commands::reconcile::observe_session_workspace(
        &state.layout,
        &repository_authority,
        &request.session_dir,
        state.blobs.as_ref(),
        request.confirm_mass_deletion,
    )
    .map_err(session_reconcile_error)?;

    let previous_tree_hash = observation.base().source_workspace.tree_hash;
    let desired_tree_hash = kin_model::compute_resolved_tree_hash(observation.desired_tree())
        .map_err(repository_authority_error)?;
    let changes = observation.changes();
    let added = changes
        .iter()
        .filter(|change| change.kind == kin_cli::commands::reconcile::ReconcileChangeKind::Added)
        .count();
    let modified = changes
        .iter()
        .filter(|change| change.kind == kin_cli::commands::reconcile::ReconcileChangeKind::Modified)
        .count();
    let removed = changes
        .iter()
        .filter(|change| change.kind == kin_cli::commands::reconcile::ReconcileChangeKind::Removed)
        .count();

    if state.graph.resolved_tree() != observation.base().source_workspace.tree
        && state.graph.resolved_tree() != *observation.desired_tree()
    {
        return Err((
            StatusCode::CONFLICT,
            "daemon query tree is not bound to the session base or its exact recovered target; \
             reopen the daemon from repository authority"
                .to_string(),
        ));
    }

    let (
        authority_generation,
        workspace_generation,
        idempotent_replay,
        semantic_enriched,
        semantic_failures,
    ) = if observation.deltas().is_empty() {
        (
            observation.base().authority_roots.generation,
            observation.base().source_workspace.generation,
            false,
            0,
            Vec::new(),
        )
    } else {
        let authority_context =
            crate::local_repository_authority::LocalRepositoryAuthorityContext::from_state(&state)
                .map_err(repository_commit_error)?;
        let plan = crate::repository_commit::plan_session_workspace_admission(
            &state.layout,
            state.blobs.as_ref(),
            &authority_context,
            &observation,
        )
        .map_err(repository_commit_error)?;
        let vacated = plan.vacated.clone();
        let committed = crate::repository_commit::commit_session_workspace_admission(
            &state.layout,
            state.blobs.as_ref(),
            &authority_context,
            plan,
        )
        .map_err(repository_commit_error)?;

        let live_generation = state
            .snapshot_generation
            .load(std::sync::atomic::Ordering::SeqCst);
        if committed.receipt.generation > live_generation {
            state
                .record_repository_authority_commit(committed.receipt.generation)
                .map_err(repository_commit_error)?;
        } else if committed.receipt.generation < live_generation {
            return Err((
                StatusCode::CONFLICT,
                format!(
                    "daemon generation {live_generation} is newer than recovered session \
                         receipt {}",
                    committed.receipt.generation
                ),
            ));
        }

        let graph_tree = state.graph.resolved_tree();
        if graph_tree == observation.base().source_workspace.tree {
            // Entities retire with the paths that owned them, in the same
            // step as the tree moves, so the live graph never holds an entity
            // authority just refused to carry. Read from the LIVE graph with
            // the plan's vacated set, never copied from the plan: the plan's
            // delta was diffed against authority, and the live graph can
            // already hold newer payloads for these entities from an earlier
            // session's readmission. kin-db checks a removal's old payload
            // against the graph it lands on, so authority's payload applied
            // here was refused after authority had already moved, leaving the
            // two graphs holding different trees. Targeted reads rather than a
            // snapshot of the whole store, which this path cannot afford.
            let (retired_entity_deltas, retired_relation_deltas) =
                crate::repository_commit::retire_live_semantics_on_vacated(
                    state.graph.as_ref(),
                    &vacated,
                )
                .map_err(repository_commit_error)?;
            state
                .graph
                .apply_transaction_delta(&TransactionDelta {
                    tree_deltas: observation.deltas().to_vec(),
                    entity_deltas: retired_entity_deltas.clone(),
                    relation_deltas: retired_relation_deltas,
                    ..TransactionDelta::default()
                })
                .map_err(internal_error)?;
            for delta in &retired_entity_deltas {
                let kin_model::EntityDelta::Removed { old } = delta else {
                    continue;
                };
                if let Some(file_id) = &old.file_origin {
                    if let Err(error) = crate::loop_runner::clear_incompatible_facets_in(
                        state.graph.as_ref(),
                        file_id,
                        crate::loop_runner::EnrichmentFacet::None,
                    ) {
                        warn!(
                            file = %file_id,
                            error = %error,
                            "retired a vacated path's entities but could not clear every facet"
                        );
                    }
                }
                state.emit_event(DaemonEvent::EntityChanged {
                    entity_id: old.id,
                    node: None,
                    change_type: crate::state::ChangeType::Deleted,
                    file_path: old.file_origin.as_ref().map(|file| file.0.clone()),
                    session_id: None,
                });
            }
        } else if graph_tree != *observation.desired_tree() {
            return Err((
                StatusCode::CONFLICT,
                "repository receipt is durable but the daemon query tree cannot be advanced \
                     from the retained session base; restart to reload exact authority"
                    .to_string(),
            ));
        }

        state.mark_dirty();
        state.bump_version();
        state.emit_event(DaemonEvent::GraphRootChanged {
            old_root_hash: Some(previous_tree_hash.to_string()),
            new_root_hash: desired_tree_hash.to_string(),
        });
        // The exact tree is published and nothing has parsed it. Re-derive the
        // semantic layer for the paths this publication moved, here, under the
        // gate that published them.
        //
        // Leaving it to the next commit does not work, and that is the whole
        // defect. A commit forces one complete admission, and that admission
        // plans its transition from the working copy this publication has
        // already made current, so the transition is empty and it returns before
        // its own enrichment half ever runs. The bytes moved, the parse never
        // happened, and every read surface kept answering at the positions the
        // previous parse recorded. On a converted `psf/requests` an edit that
        // prepended seventeen lines left the whole file answering seventeen
        // lines short, under an envelope with nothing to report.
        // Record what this publication owes a parser before parsing any of it,
        // and leave the record standing after. Re-deriving here fixes the live
        // daemon and nothing more: entities reach durable authority only inside
        // a semantic change, this publication deliberately writes no history,
        // and a derived-graph mutation no change carries is gone when the next
        // daemon replays that history. Measured, not assumed. A daemon reopened
        // between this publication and its commit read the pre-edit span back,
        // and a synchronous snapshot immediately after the re-derivation did not
        // change that. The commit that publishes is what settles the record.
        crate::semantic_debt::record(&state, &crate::semantic_debt::owed_by(observation.deltas()));
        let readmitted =
            crate::loop_runner::readmit_semantics_for_paths(&state, &published_paths(&observation))
                .await;
        (
            committed.receipt.generation,
            observation
                .base()
                .source_workspace
                .generation
                .saturating_add(1),
            committed.idempotent_replay,
            readmitted.enriched,
            readmitted.failed,
        )
    };

    drop(graph_mutation);
    let summary = kin_cli::commands::reconcile::ReconcileSummary {
        schema: kin_cli::commands::reconcile::RECONCILE_SUMMARY_SCHEMA.to_string(),
        operation_id: observation.base().reconcile_operation_id,
        repository_id: observation.base().repository_id.clone(),
        authority_generation,
        workspace_generation,
        previous_tree_hash,
        desired_tree_hash,
        idempotent_replay,
        changed: !observation.deltas().is_empty(),
        added,
        modified,
        removed,
        observed_materialized_artifacts: observation.observed_materialized_artifacts(),
        preserved_graph_only_artifacts: observation.preserved_graph_only_artifacts(),
        observed_body_bytes: observation.observed_body_bytes(),
        semantic_files_enriched: semantic_enriched,
        semantic_enrichment_failures: semantic_failures.len(),
        changes,
    };
    if !semantic_failures.is_empty() {
        let named = semantic_failures
            .iter()
            .map(|failure| failure.path.clone())
            .collect::<Vec<_>>();
        return Err(semantic_readmission_refused(&summary, &named));
    }
    Ok(Json(summary))
}

/// Every repository path one session publication moved.
///
/// Both sides of every delta. A rename's old path leaves the tree and its new
/// path enters it, and the readmission skips whatever the tree no longer
/// carries, so naming both sides costs nothing and misses nothing.
fn published_paths(
    observation: &kin_cli::commands::reconcile::SessionReconcileObservation,
) -> std::collections::BTreeSet<RepoPath> {
    let mut paths = std::collections::BTreeSet::new();
    for delta in observation.deltas() {
        if let Some(old) = delta.old_state() {
            paths.insert(old.path.clone());
        }
        if let Some(new) = delta.new_state() {
            paths.insert(new.path.clone());
        }
    }
    paths
}

/// Refuse a reconcile whose exact tree published but whose semantics did not.
///
/// The bytes are durable before this is reached and a parser may not retract
/// them, so this is not a rollback and the body says so outright: the tree
/// moved, and the graph cannot answer about these files at the positions their
/// new bytes hold. Returning it as a refusal rather than as a degradation block
/// inside a 200 is what makes `kin reconcile` exit non-zero, because the CLI
/// treats any non-success status as an error and prints the body; a caller that
/// reads a clean summary and a zero has no way to learn that the file it just
/// edited still answers at its old spans, which is the failure this whole change
/// exists to end.
///
/// The complete summary travels inside the refusal, so nothing a success would
/// have reported is lost by refusing.
fn semantic_readmission_refused(
    summary: &kin_cli::commands::reconcile::ReconcileSummary,
    failed: &[String],
) -> (StatusCode, String) {
    let body = serde_json::json!({
        "error": "semantic_readmission_failed",
        "message": format!(
            "the exact tree published as {} but {} of the files it moved could not be \
             re-parsed, so the graph still answers about them at the positions their previous \
             bytes held: {}",
            summary.desired_tree_hash,
            failed.len(),
            failed.join(", ")
        ),
        "files": failed,
        "summary": summary,
    });
    (StatusCode::CONFLICT, body.to_string())
}

fn session_reconcile_error(error: impl std::fmt::Display) -> (StatusCode, String) {
    let message = error.to_string();
    let status = if [
        "stale",
        "tampered",
        "changed",
        "mass-deletion",
        "no longer match",
    ]
    .iter()
    .any(|needle| message.contains(needle))
    {
        StatusCode::CONFLICT
    } else {
        StatusCode::BAD_REQUEST
    };
    (status, message)
}

// ── Thin-Client Commands ─────────────────────────────────────────────────

/// POST /commands/commit — Thin-client commit endpoint.
///
/// The daemon first admits pending filesystem input into graph state, then
/// publishes one repository-v6 transaction containing the semantic change,
/// exact tree, workspace base, and named-ref compare-and-swap.
///
/// `author` is required and carries no default. The daemon runs with every
/// `GIT_*` variable scrubbed and does not share the caller's working directory,
/// so it cannot resolve who is committing, and a defaulted field here is exactly
/// how the placeholder author this endpoint used to stamp reached permanent
/// history. A request that names nobody is refused by deserialization rather
/// than completed by the daemon.
#[derive(Debug, Clone, Deserialize)]
#[serde(deny_unknown_fields)]
struct CommandCommitRequest {
    operation_id: kin_model::OperationId,
    timestamp: kin_model::Timestamp,
    #[serde(default)]
    message: Option<String>,
    #[serde(default)]
    amend: bool,
    #[serde(default)]
    expected_head: Option<kin_model::SemanticChangeId>,
    author: kin_model::AuthorId,
    #[serde(default)]
    session_id: Option<String>,
}

/// Why one attempt at publishing a commit did not produce a change.
///
/// Two answers rather than one, because they ask for different next steps. A
/// refusal is already worded for the caller and travels out as it is. Semantics
/// that have not caught up with their bytes is not a refusal yet: the parse that
/// settles it is one bounded pass away, and this route takes that pass before it
/// decides. Recovering the difference from the worded refusal afterwards would
/// mean matching on message text, and a classification inferred from a failure
/// string stops holding the first time the wording moves.
enum CommitAttempt {
    Refused((StatusCode, String)),
    SemanticsBehindTree(Vec<RepoPath>),
}

impl From<(StatusCode, String)> for CommitAttempt {
    fn from(refusal: (StatusCode, String)) -> Self {
        Self::Refused(refusal)
    }
}

#[derive(Debug, Serialize)]
struct CommandCommitResponse {
    change_id: String,
    /// The branch this change was published onto, or `null` when the workspace
    /// head is detached and the head itself advanced instead.
    branch: Option<String>,
    entity_count: usize,
    relation_count: usize,
    file_count: usize,
}

async fn command_commit(
    State(state): State<Arc<DaemonState>>,
    Json(request): Json<CommandCommitRequest>,
) -> Result<impl IntoResponse, (StatusCode, String)> {
    if state.filesystem_reconcile_disabled() {
        return Err(filesystem_ingest_disabled_response(
            "/commands/commit",
            &state.layout.working_dir().display().to_string(),
        ));
    }

    if request.amend != request.expected_head.is_some() {
        return Err((
            StatusCode::BAD_REQUEST,
            "amend requires the exact expected_head; ordinary commit must not supply one"
                .to_string(),
        ));
    }
    if request
        .message
        .as_ref()
        .is_some_and(|message| message.trim().is_empty())
        || (!request.amend && request.message.is_none())
    {
        return Err((
            StatusCode::BAD_REQUEST,
            "native commit message must not be empty".to_string(),
        ));
    }

    // Announce this commit before anything else, and keep announcing it until
    // the handler returns. The ambient reconcile tick reads this and stands its
    // own publication down, because the admission below sweeps the whole working
    // copy and the transaction after it carries the resulting tree: a tick that
    // publishes first pays a complete O(store) publication for a tree this
    // commit is about to publish anyway.
    //
    // Before the gate, not after it. A tick that already holds the gate is still
    // deciding whether to publish, and it decides by reading this.
    let _pending_commit = state.pending_commits.announce();

    // Publish that this daemon has a write transaction open, on a path that
    // survives the runtime having no worker free to answer anything. The commit
    // below is synchronous work on a runtime worker, so `/health` — the only
    // question the supervisor's reaper asks before killing a daemon — can go
    // unanswered for the whole commit while the reaper's other signal, growth in
    // `daemon.log`, also stalls behind a phase that logs only when it finishes.
    // The marker and its beat are what make a busy daemon distinguishable from a
    // wedged one.
    let _transaction =
        crate::commit_liveness::TransactionGuard::open(state.layout.root(), "commit");
    // Hold one uninterrupted graph-authority gate across forced filesystem
    // admission, change construction, and branch publication. The sync helper
    // deliberately does not re-lock this non-reentrant mutex.
    let _coordination = crate::mcp_commit::timed_commit_phase_async(
        "coordination_gate_wait",
        state.coordination_gate.lock(),
    )
    .await;
    // A merge record is bound to the workspace generation that opened it.
    // Refuse before forced admission can advance that generation and strand
    // resolutions already persisted on the transaction.
    refuse_commit_during_open_merge(&state)?;
    if let Some(expected_head) = request.expected_head {
        let context =
            crate::local_repository_authority::LocalRepositoryAuthorityContext::from_state(&state)
                .map_err(repository_commit_error)?;
        crate::repository_commit::validate_native_amend_head(&context, expected_head)
            .map_err(repository_commit_error)?;
    }
    // The admission derives the exact tree from the working copy but does not
    // publish it. This commit's own transaction carries that tree transition
    // beside the semantic change, so one repository-authority successor is
    // prepared and one store snapshot persisted for the whole commit instead
    // of two. Nothing observes the interval: the coordination gate above spans
    // the admission and the publication, and a commit that does not reach
    // authority publishes the deferred tree on its way out, leaving exactly
    // the state a failed commit leaves today.
    //
    // The phase keeps its name. What the span measures is unchanged, one
    // complete host walk and the graph work behind it, and the proof parser
    // reads that name off the phase table.
    let deferred_tree = crate::mcp_commit::timed_commit_phase_async(
        "forced_filesystem_admission",
        crate::loop_runner::sync_filesystem_with_graph_deferring_tree_publication(&state),
    )
    .await
    .map_err(commit_admission_error)?;

    // A commit plans its tree half and its entity half out of one live graph,
    // and that graph is allowed to be behind itself: an exact-tree admission
    // moves a path's bytes into authority on its own, and the parse that moves
    // that path's spans onto them runs afterwards and does not survive the daemon
    // that ran it. The drain above repairs the paths a writer recorded as owed.
    // For anything it missed the planner refuses by name, and the answer is one
    // bounded re-derivation of exactly those paths through the seam the drain
    // uses, under the gate this commit already holds, before asking again.
    //
    // Once, not in a loop. The re-derivation is best effort and the planner is
    // the guarantee: a second refusal is the store saying the parse will not
    // settle from here, and asking again until it does would hold the gate for
    // as long as the caller waits.
    let attempt =
        match command_commit_after_admission(&state, request.clone(), deferred_tree.as_ref()) {
            Err(CommitAttempt::SemanticsBehindTree(paths)) => {
                let owed: std::collections::BTreeSet<RepoPath> = paths.into_iter().collect();
                let named = owed
                    .iter()
                    .map(ToString::to_string)
                    .collect::<Vec<_>>()
                    .join(", ");
                let waiting_since = Instant::now();
                // Its own commit phase, so what the wait cost is attributed on the
                // phase table beside the planning it precedes rather than hiding
                // inside it.
                let readmitted = crate::mcp_commit::timed_commit_phase_async(
                    "await_pending_reconcile",
                    crate::loop_runner::readmit_semantics_for_paths(&state, &owed),
                )
                .await;
                info!(
                    paths = %named,
                    enriched = readmitted.enriched,
                    unresolved = readmitted.failed.len(),
                    waited_ms = waiting_since.elapsed().as_millis(),
                    "these paths held entities their own admitted bytes do not reproduce, so this \
                     commit re-derived them before planning the change that seals those bytes"
                );
                command_commit_after_admission(&state, request, deferred_tree.as_ref())
            }
            attempted => attempted,
        };
    match attempt {
        Ok(response) => {
            // A transaction that reached authority carried the tree the graph
            // holds with it, which is the divergence an earlier unclosed
            // deferral left behind. The admission above plans out of the graph's
            // tree, so a still-wedged daemon could not have got this far.
            state
                .background_work
                .reconcile()
                .clear_deferred_tree_wedge();
            // The forced admission above is a complete exact-tree admission by
            // every measure the freshness surfaces use, so it is recorded on the
            // same probes and in the same durable marker the ambient reconcile
            // tick and `kin admit` write. Leaving it out made a commit the one
            // complete admission no surface could see.
            //
            // Recorded here rather than beside the admission because this is the
            // point the admitted tree is durable. The admission defers its
            // publication to this transaction, and a marker stamped before the
            // transaction reached authority would claim a complete admission for
            // a tree authority never accepted, on exactly the path where the
            // commit fails and the deferred publication fails behind it.
            //
            // Without this the marker had two writers, the ambient tick and
            // `kin admit`, and neither runs on a convert-then-commit session: the
            // tick stands its own round down for a commit inside the daemon. So a
            // store that had just been converted and committed to reported that
            // no complete admission was recorded for it, minutes after one had
            // completed, while a sibling store that happened to get an ambient
            // tick milliseconds before its commit reported a healthy timestamp.
            state
                .background_work
                .reconcile()
                .record_admission_success(std::time::Instant::now());
            crate::background_work::record_durable_admission(
                &state.layout,
                state.graph.resolved_tree().len() as u64,
            );
            // This transaction reached authority, and a commit derives its
            // change from the live graph, so every parse the admission above put
            // back into that graph is in history now. Nothing the record named
            // is still owed. Settled here rather than at the drain because a
            // crash between the two would otherwise clear the record for work no
            // change carried, which is the loss the record exists to prevent.
            crate::semantic_debt::settle_all(&state);
            Ok(response)
        }
        Err(CommitAttempt::SemanticsBehindTree(paths)) => {
            if let Some(admitted) = deferred_tree.as_ref() {
                crate::loop_runner::publish_deferred_tree_after_failure(&state, admitted);
            }
            Err(repository_commit_error(
                crate::error::DaemonError::SemanticsBehindTree {
                    paths: paths.iter().map(ToString::to_string).collect(),
                },
            ))
        }
        Err(CommitAttempt::Refused(refusal)) => {
            if let Some(admitted) = deferred_tree.as_ref() {
                crate::loop_runner::publish_deferred_tree_after_failure(&state, admitted);
            }
            Err(refusal)
        }
    }
}

/// Plan and publish the commit for a working copy this caller has already
/// admitted.
///
/// `observed` is present when the admission left its tree transition for this
/// transaction to carry. It is the completed walk's own proof rather than a
/// flag, so the collapsed path cannot be entered without one, and the tree it
/// proved is checked against the tree the plan publishes.
fn command_commit_after_admission(
    state: &Arc<DaemonState>,
    request: CommandCommitRequest,
    observed: Option<&crate::repository_commit::AdmittedWorkspaceTree>,
) -> Result<Json<CommandCommitResponse>, CommitAttempt> {
    let graph = &*state.graph;
    let authority_context =
        crate::local_repository_authority::LocalRepositoryAuthorityContext::from_state(state)
            .map_err(repository_commit_error)?;
    let planned = crate::mcp_commit::timed_commit_phase("plan_transaction", || {
        if let Some(expected_head) = request.expected_head {
            crate::repository_commit::plan_native_amend(
                graph,
                state.blobs.as_ref(),
                &authority_context,
                request.operation_id,
                request.timestamp,
                request.author,
                &crate::repository_commit::NativeAmend {
                    expected_head,
                    message: request.message,
                },
            )
        } else {
            crate::repository_commit::plan_native_commit(
                graph,
                state.blobs.as_ref(),
                &authority_context,
                request.operation_id,
                request.timestamp,
                request.author,
                request.message.ok_or_else(|| {
                    crate::error::DaemonError::IncompatibleRepo(
                        "native commit message must not be empty".to_string(),
                    )
                })?,
            )
        }
    });
    let plan = match planned {
        Ok(plan) => plan,
        // The one planning outcome this route can still do something about, so
        // it keeps its paths instead of being flattened into a worded refusal.
        Err(crate::error::DaemonError::SemanticsBehindTree { paths }) => {
            return Err(CommitAttempt::SemanticsBehindTree(
                paths
                    .into_iter()
                    .filter_map(|path| RepoPath::from_utf8(path).ok())
                    .collect(),
            ))
        }
        Err(error) => return Err(repository_commit_error(error).into()),
    };
    if !request.amend {
        if let Some(refusal) = refuse_a_successor_that_records_nothing(&plan) {
            return Err(refusal.into());
        }
    }
    let change_id = plan.change.id;
    let branch_name = plan.target.branch().map(|name| name.to_string());
    let entity_count = plan.entity_count;
    let relation_count = plan.relation_count;
    let file_count = plan.file_count;

    // --- Lease enforcement gate for native repository publication ---
    {
        use kin_model::session::IntentScope;

        let scopes: Vec<IntentScope> = plan
            .entity_scope_ids
            .iter()
            .copied()
            .map(IntentScope::Entity)
            .collect();

        if !scopes.is_empty() {
            let caller_session = request
                .session_id
                .as_ref()
                .and_then(|s| uuid::Uuid::parse_str(s).ok().map(kin_model::SessionId));
            let traffic = state
                .coordinator
                .check_traffic(&scopes)
                .map_err(internal_error)?;
            if traffic.has_hard_blocks {
                let foreign_blocks: Vec<_> = traffic
                    .reports
                    .iter()
                    .flat_map(|r| r.active_intents.iter())
                    .filter(|s| {
                        s.lock_type == kin_model::session::LockType::Hard
                            && caller_session.as_ref().is_none_or(|cs| &s.session_id != cs)
                    })
                    .collect();
                if !foreign_blocks.is_empty() {
                    let body = serde_json::json!({
                        "error": "lease_conflict",
                        "conflict_type": "HardCollision",
                        "blocking_intents": foreign_blocks.iter().map(|b| {
                            serde_json::json!({
                                "intent_id": b.intent_id.to_string(),
                                "session_id": b.session_id.to_string(),
                                "lock_type": format!("{:?}", b.lock_type),
                                "task_description": b.task_description,
                            })
                        }).collect::<Vec<_>>(),
                        "message": format!(
                            "commit blocked: {} entity scope(s) held by active hard lease(s)",
                            foreign_blocks.len()
                        ),
                    });
                    return Err(CommitAttempt::Refused((
                        StatusCode::CONFLICT,
                        body.to_string(),
                    )));
                }
            }
        }
    }

    let committed = if let Some(observed) = observed {
        crate::repository_commit::commit_native_plan_with_observed_target_tree(
            &state.layout,
            state.blobs.as_ref(),
            &authority_context,
            plan,
            observed,
        )
    } else {
        crate::repository_commit::commit_native_plan_with_projection(
            &state.layout,
            state.blobs.as_ref(),
            &authority_context,
            plan,
        )
    }
    .map_err(repository_commit_error)?;
    state
        .record_repository_authority_commit(committed.receipt.generation)
        .map_err(repository_commit_error)?;
    // The repository transaction is durable authority. The in-process graph is
    // a derived query view; install the exact immutable change only after the
    // authority CAS succeeds.
    crate::mcp_commit::timed_commit_phase("install_live_graph", || {
        graph.create_change(&committed.change)
    })
    .map_err(internal_error)?;
    // The plan above was derived from this live graph under the coordination
    // gate, and the transaction published it, so the two are level here and
    // this is the count durable authority now carries (FIR-2421). Read from the
    // live graph rather than from the plan, because a plan's `entity_count` is
    // the size of its delta and this is the size of the whole.
    state.record_durable_entity_count(graph.entity_count() as u64);
    // The relation half of the same levelling, from the same live graph at the
    // same instant. Recording one counter and not the other would publish a
    // difference no observation produced (FIR-3202).
    state.record_durable_relation_count(graph.relation_count() as u64);
    // The relation set just moved and the change is installed, so this is the
    // baseline the next `kin graph status` compares against. Recorded after the
    // install rather than from the plan, for the reason the entity count above
    // is: a plan carries the size of its delta and this is a census of the
    // whole graph.
    crate::background_work::record_relation_census(
        &state.layout,
        graph,
        kin_core::relation_census::CensusSource::Commit,
    );
    state.bump_version();
    state.emit_event(DaemonEvent::GraphRootChanged {
        old_root_hash: None,
        new_root_hash: change_id.to_string(),
    });

    Ok(Json(CommandCommitResponse {
        change_id: change_id.to_string(),
        branch: branch_name,
        entity_count,
        relation_count,
        file_count,
    }))
}

/// Refuse a commit whose successor would record nothing at all.
///
/// A `kin commit` on a tree Kin has already committed used to be accepted and
/// published as a change with `entities=0 relations=0 tree=0`. Nothing about
/// that change is recoverable information: it names no entity, no relation and
/// no file, and it exists only because a caller asked twice. The way callers
/// ask twice is the point. A commit whose reply the client never received looks
/// exactly like a commit that never happened, so the next thing a person does
/// is run it again, and the retry mints the empty change on top of the real
/// one. Refusing here rather than in the CLI is what makes the guarantee hold
/// for every caller of this endpoint, including the one that has already
/// decided the first attempt failed.
///
/// A policy-only change still commits: an admission policy delta is a recorded
/// transition even when no entity, relation or file moved.
fn refuse_a_successor_that_records_nothing(
    plan: &crate::repository_commit::NativeCommitPlan,
) -> Option<(StatusCode, String)> {
    let change = &plan.change;
    if !change.entity_deltas.is_empty()
        || !change.relation_deltas.is_empty()
        || !change.tree_deltas.is_empty()
        || change.admission_policy_delta.is_some()
    {
        return None;
    }
    let already = change.parents.first();
    let message = match already {
        Some(parent) => format!("nothing to commit: this tree is already committed as {parent}"),
        None => "nothing to commit: this workspace holds no entities, relations or files to \
                 record"
            .to_string(),
    };
    let body = serde_json::json!({
        "error": "nothing_to_commit",
        "change_id": already.map(|parent| parent.to_string()),
        "message": message,
    });
    Some((StatusCode::CONFLICT, body.to_string()))
}

/// The response for a commit's admission that could not open the working
/// projection.
///
/// A projection blocked on a file a person has to act on, such as the eject
/// journal a copied `.kin` carries in, is a refusal in words rather than a
/// daemon failure: the store is intact and the sentence names the file and the
/// remedy. It is answered as 409 with that sentence in the body, which the CLI
/// prints as its own line, so a reader is not sent to the daemon for a file
/// they can see. On 0.5.52 it reached them as `HTTP 500 Internal Server Error:
/// Core error: ...` (FIR-2664). Everything else stays an internal error.
fn commit_admission_error(error: crate::error::DaemonError) -> (StatusCode, String) {
    if let Some(refusal) = projection_blocked_refusal(&error) {
        return refusal;
    }
    // A parse this daemon could not perform over bytes that are already durable
    // authority. The store is intact and nothing needs repairing, so answering
    // it as an internal error would send a reader to the daemon for a file they
    // can see. It is a refusal in words, naming the files, exactly as the
    // reconcile that first owed the parse refuses.
    if let crate::error::DaemonError::SemanticReadmissionFailed(message) = &error {
        let body = serde_json::json!({
            "error": "semantic_readmission_failed",
            "message": message,
        });
        return (StatusCode::CONFLICT, body.to_string());
    }
    internal_error(error)
}

/// The worded refusal for a blocked projection, when `error` is one.
fn projection_blocked_refusal(error: &crate::error::DaemonError) -> Option<(StatusCode, String)> {
    let crate::error::DaemonError::Core(kin_core::KinError::ProjectionBlocked(message)) = error
    else {
        return None;
    };
    let body = serde_json::json!({
        "error": "projection_blocked",
        "message": message,
    });
    Some((StatusCode::CONFLICT, body.to_string()))
}

fn repository_commit_error(error: crate::error::DaemonError) -> (StatusCode, String) {
    if let Some(refusal) = projection_blocked_refusal(&error) {
        return refusal;
    }
    // Semantics that have not caught up with their bytes is a state of the store
    // a caller can act on, not a fault in it: the files are intact, the bytes are
    // authority, and one re-derivation settles it. Answering it as an internal
    // error would send a reader to the daemon for files they can see.
    if let crate::error::DaemonError::SemanticsBehindTree { paths } = &error {
        let body = serde_json::json!({
            "error": "semantics_behind_tree",
            "message": error.to_string(),
            "paths": paths,
        });
        return (StatusCode::CONFLICT, body.to_string());
    }
    let status = match &error {
        crate::error::DaemonError::Graph(kin_db::KinDbError::Model(
            kin_model::ModelError::Conflict(_),
        )) => StatusCode::CONFLICT,
        crate::error::DaemonError::Graph(kin_db::KinDbError::Model(
            kin_model::ModelError::InvalidOperation(_),
        ))
        | crate::error::DaemonError::Core(kin_core::KinError::Model(
            kin_model::ModelError::InvalidOperation(_),
        )) => StatusCode::BAD_REQUEST,
        _ => StatusCode::INTERNAL_SERVER_ERROR,
    };
    (status, error.to_string())
}

/// DELETE /session/{session_id} — end a session and release its intents.
async fn end_session(
    Path(session_id): Path<String>,
    State(state): State<Arc<DaemonState>>,
) -> Result<impl IntoResponse, (StatusCode, String)> {
    let _coordination = state.coordination_gate.lock().await;
    let session_id = parse_session_id(&session_id)?;
    let session = state
        .coordinator
        .get_session(&session_id)
        .map_err(internal_error)?
        .ok_or_else(|| {
            (
                StatusCode::NOT_FOUND,
                format!("session not found: {session_id}"),
            )
        })?;
    let intents = state
        .coordinator
        .list_intents(&session_id)
        .map_err(internal_error)?;
    let event_drafts: Vec<_> = intents
        .iter()
        .map(|intent| CoordinationEventDraft {
            event: "intent_release",
            outcome: "session_ended".to_string(),
            session_id: Some(session_id.to_string()),
            intent_id: Some(intent.intent_id.to_string()),
            intent_ids: vec![intent.intent_id.to_string()],
            transaction_id: None,
            scopes: intent.scopes.iter().map(format_scope).collect(),
            enforcement_mode: state.coordination_mode().as_str().to_string(),
            blocking_intent_ids: Vec::new(),
        })
        .collect();
    for draft in &event_drafts {
        persist_coordination_reservation(&state, draft.clone())?;
    }
    if let Err(error) = state.coordinator.deregister_session(&session_id) {
        state.mark_coordination_evidence_incomplete(format!(
            "session end failed after intent-release reservations: {error}"
        ));
        return Err(internal_error(error));
    }
    for draft in event_drafts {
        persist_coordination_event(&state, draft)?;
    }

    Ok(Json(SessionEndResponse {
        session_id: session.session_id.to_string(),
        vendor: session.vendor,
        status: "ended".to_string(),
        started_at: session.started_at,
        ended_at: kin_model::timestamp::Timestamp::now(),
    }))
}

/// GET /session/{session_id}/intents — list intents owned by a session.
async fn list_session_intents(
    Path(session_id): Path<String>,
    State(state): State<Arc<DaemonState>>,
) -> Result<impl IntoResponse, (StatusCode, String)> {
    let session_id = parse_session_id(&session_id)?;
    let intents = state
        .coordinator
        .list_intents(&session_id)
        .map_err(internal_error)?;
    Ok(Json(
        intents
            .into_iter()
            .map(IntentResponse::from)
            .collect::<Vec<_>>(),
    ))
}

/// DELETE /session/{session_id}/intents — clear all intents for a session.
async fn clear_session_intents(
    Path(session_id): Path<String>,
    State(state): State<Arc<DaemonState>>,
) -> Result<impl IntoResponse, (StatusCode, String)> {
    let _coordination = state.coordination_gate.lock().await;
    let session_id = parse_session_id(&session_id)?;
    let intents = state
        .coordinator
        .list_intents(&session_id)
        .map_err(internal_error)?;

    let event_drafts: Vec<_> = intents
        .iter()
        .map(|intent| CoordinationEventDraft {
            event: "intent_release",
            outcome: "cleared".to_string(),
            session_id: Some(session_id.to_string()),
            intent_id: Some(intent.intent_id.to_string()),
            intent_ids: vec![intent.intent_id.to_string()],
            transaction_id: None,
            scopes: intent.scopes.iter().map(format_scope).collect(),
            enforcement_mode: state.coordination_mode().as_str().to_string(),
            blocking_intent_ids: Vec::new(),
        })
        .collect();
    for draft in &event_drafts {
        persist_coordination_reservation(&state, draft.clone())?;
    }

    for intent in &intents {
        if let Err(error) = state
            .coordinator
            .release_intent(&session_id, &intent.intent_id)
        {
            state.mark_coordination_evidence_incomplete(format!(
                "intent clear failed after release reservations: {error}"
            ));
            return Err(internal_error(error));
        }
    }
    for draft in event_drafts {
        persist_coordination_event(&state, draft)?;
    }

    Ok(Json(ClearedIntentsResponse {
        cleared: intents.len(),
    }))
}

/// GET /intent — list all active intents.
async fn list_intents(
    State(state): State<Arc<DaemonState>>,
) -> Result<impl IntoResponse, (StatusCode, String)> {
    let now = kin_model::Timestamp::now();
    let mut intents: Vec<_> = state
        .graph
        .list_all_intents()
        .map_err(internal_error)?
        .into_iter()
        .filter(|intent| {
            intent
                .expires_at
                .as_ref()
                .is_none_or(|expires_at| expires_at >= &now)
        })
        .collect();
    intents.sort_by_key(|intent| intent.intent_id.to_string());
    Ok(Json(
        intents
            .into_iter()
            .map(IntentResponse::from)
            .collect::<Vec<_>>(),
    ))
}

/// POST /intent/register — register a new intent against the daemon-backed coordinator.
async fn register_intent(
    State(state): State<Arc<DaemonState>>,
    Json(request): Json<RegisterIntentRequest>,
) -> Result<impl IntoResponse, (StatusCode, String)> {
    // Serialize the full check+register decision with transaction preflight and
    // apply. This daemon gate complements the coordinator's own linearization
    // lock and closes the cross-surface HTTP race.
    let _coordination = state.coordination_gate.lock().await;
    let mut scope_values = request.scopes;
    if scope_values.is_empty() {
        if request.scope.trim().is_empty() {
            return Err((
                StatusCode::BAD_REQUEST,
                "missing required scope or scopes".to_string(),
            ));
        }
        scope_values.push(request.scope);
    }
    let scopes = scope_values
        .iter()
        .map(|scope| parse_scope(scope))
        .collect::<Result<Vec<_>, _>>()?;
    let scope_labels = scopes.iter().map(format_scope).collect::<Vec<_>>();
    let lock_type = parse_lock_type(&request.lock_type)?;
    let session_id = resolve_or_create_session(&state, request.session_id.as_deref())?;
    persist_coordination_reservation(
        &state,
        CoordinationEventDraft {
            event: "intent_registration",
            outcome: "registration".to_string(),
            session_id: Some(session_id.to_string()),
            intent_id: None,
            intent_ids: Vec::new(),
            transaction_id: None,
            scopes: scope_labels.clone(),
            enforcement_mode: state.coordination_mode().as_str().to_string(),
            blocking_intent_ids: Vec::new(),
        },
    )?;
    let result = match state.coordinator.register_intent_with_mode(
        &session_id,
        scopes,
        lock_type,
        &request.task_description,
        request
            .expires_at
            .as_deref()
            .map(parse_timestamp)
            .transpose()?,
        state.coordination_mode(),
    ) {
        Ok(result) => result,
        Err(error) => {
            state.mark_coordination_evidence_incomplete(format!(
                "intent registration failed after durable reservation: {error}"
            ));
            return Err(internal_error(error));
        }
    };

    let (response, outcome, blocking_intent_ids) = match result {
        crate::session_registry::IntentRegistrationResult::Registered {
            intent_id,
            downstream_warnings,
            policy_warnings,
        } => (
            RegisterIntentResponse {
                intent_id: intent_id.to_string(),
                session_id: session_id.to_string(),
                status: "registered".to_string(),
                conflicts: Vec::new(),
                downstream_warnings,
                coordination_warnings: policy_warnings,
                active_intents: None,
                max_concurrent_intents: None,
                required_capability: None,
            },
            "registered".to_string(),
            Vec::new(),
        ),
        crate::session_registry::IntentRegistrationResult::Blocked {
            intent_id,
            conflicts,
        } => {
            let blocking = conflicts
                .iter()
                .map(|conflict| conflict.intent_id.to_string())
                .collect();
            (
                RegisterIntentResponse {
                    intent_id: intent_id.to_string(),
                    session_id: session_id.to_string(),
                    status: "blocked".to_string(),
                    conflicts,
                    downstream_warnings: Vec::new(),
                    coordination_warnings: Vec::new(),
                    active_intents: None,
                    max_concurrent_intents: None,
                    required_capability: None,
                },
                "blocked".to_string(),
                blocking,
            )
        }
        crate::session_registry::IntentRegistrationResult::LimitExceeded {
            intent_id,
            active,
            limit,
        } => (
            RegisterIntentResponse {
                intent_id: intent_id.to_string(),
                session_id: session_id.to_string(),
                status: "limit_exceeded".to_string(),
                conflicts: Vec::new(),
                downstream_warnings: Vec::new(),
                coordination_warnings: Vec::new(),
                active_intents: Some(active),
                max_concurrent_intents: Some(limit),
                required_capability: None,
            },
            "limit_exceeded".to_string(),
            Vec::new(),
        ),
        crate::session_registry::IntentRegistrationResult::CapabilityDenied {
            intent_id,
            capability,
        } => (
            RegisterIntentResponse {
                intent_id: intent_id.to_string(),
                session_id: session_id.to_string(),
                status: "capability_denied".to_string(),
                conflicts: Vec::new(),
                downstream_warnings: Vec::new(),
                coordination_warnings: Vec::new(),
                active_intents: None,
                max_concurrent_intents: None,
                required_capability: Some(capability.to_string()),
            },
            "capability_denied".to_string(),
            Vec::new(),
        ),
    };

    let persisted_intent_id = (response.status == "registered").then(|| response.intent_id.clone());
    persist_coordination_event(
        &state,
        CoordinationEventDraft {
            event: "intent_registration",
            outcome,
            session_id: Some(session_id.to_string()),
            intent_id: persisted_intent_id.clone(),
            intent_ids: persisted_intent_id.into_iter().collect(),
            transaction_id: None,
            scopes: scope_labels,
            enforcement_mode: state.coordination_mode().as_str().to_string(),
            blocking_intent_ids,
        },
    )?;

    Ok(Json(response))
}

/// DELETE /intent/{intent_id} — release an active intent.
async fn release_intent(
    Path(intent_id): Path<String>,
    State(state): State<Arc<DaemonState>>,
) -> Result<impl IntoResponse, (StatusCode, String)> {
    let _coordination = state.coordination_gate.lock().await;
    let intent_id = parse_intent_id(&intent_id)?;
    let intent = state
        .graph
        .get_intent(&intent_id)
        .map_err(internal_error)?
        .ok_or_else(|| {
            (
                StatusCode::NOT_FOUND,
                format!("intent not found: {intent_id}"),
            )
        })?;

    let event_draft = CoordinationEventDraft {
        event: "intent_release",
        outcome: "released".to_string(),
        session_id: Some(intent.session_id.to_string()),
        intent_id: Some(intent_id.to_string()),
        intent_ids: vec![intent_id.to_string()],
        transaction_id: None,
        scopes: intent.scopes.iter().map(format_scope).collect(),
        enforcement_mode: state.coordination_mode().as_str().to_string(),
        blocking_intent_ids: Vec::new(),
    };
    persist_coordination_reservation(&state, event_draft.clone())?;
    if let Err(error) = state
        .coordinator
        .release_intent(&intent.session_id, &intent_id)
    {
        state.mark_coordination_evidence_incomplete(format!(
            "intent release failed after durable reservation: {error}"
        ));
        return Err(internal_error(error));
    }
    persist_coordination_event(&state, event_draft)?;
    Ok(StatusCode::NO_CONTENT)
}

/// GET /traffic/{scope} — summarize active locks and downstream warnings.
async fn traffic(
    Path(scope): Path<String>,
    State(state): State<Arc<DaemonState>>,
) -> Result<impl IntoResponse, (StatusCode, String)> {
    let scope = parse_scope(&scope)?;
    let mut reports = state
        .coordinator
        .check_traffic(&[scope])
        .map_err(internal_error)?
        .reports;
    let report = reports.pop().ok_or_else(|| {
        (
            StatusCode::INTERNAL_SERVER_ERROR,
            "traffic report missing for requested scope".to_string(),
        )
    })?;
    let hard_blocks = report
        .active_intents
        .iter()
        .filter(|intent| intent.lock_type == LockType::Hard)
        .count();
    let soft_locks = report.active_intents.len().saturating_sub(hard_blocks);
    let downstream_count = report.downstream_warnings.len();

    Ok(Json(TrafficResponse {
        active_intents: report.active_intents,
        downstream_warnings: report.downstream_warnings,
        hard_blocks,
        soft_locks,
        downstream_count,
    }))
}

/// GET /graph/bootstrap — export the daemon-authoritative primary graph snapshot.
/// If the request includes an `X-Kin-Session` header and the session has an
/// active temporal scope, exports the scoped historical graph instead.
fn bootstrap_export_semaphore() -> Arc<tokio::sync::Semaphore> {
    BOOTSTRAP_EXPORTS
        .get_or_init(|| {
            let limit = std::env::var("KIN_DAEMON_BOOTSTRAP_EXPORT_CONCURRENCY")
                .ok()
                .and_then(|value| value.parse::<usize>().ok())
                .unwrap_or(1)
                .max(1);
            Arc::new(tokio::sync::Semaphore::new(limit))
        })
        .clone()
}

async fn export_graph_snapshot_bytes(
    graph: Arc<kin_db::InMemoryGraph>,
) -> Result<Vec<u8>, (StatusCode, String)> {
    let permit = bootstrap_export_semaphore()
        .acquire_owned()
        .await
        .map_err(internal_error)?;
    tokio::task::spawn_blocking(move || {
        let _permit = permit;
        graph
            .serialize_snapshot_borrowed()
            .map(|(bytes, _)| bytes)
            .map_err(internal_error)
    })
    .await
    .map_err(internal_error)?
}

async fn graph_bootstrap(
    headers: axum::http::HeaderMap,
    State(state): State<Arc<DaemonState>>,
) -> Result<impl IntoResponse, (StatusCode, String)> {
    let session_id = extract_session_id_from_headers(&headers)?;
    let graph = resolve_session_graph(&state, session_id.as_ref()).await;
    let bytes = export_graph_snapshot_bytes(graph).await?;

    Ok(([(header::CONTENT_TYPE, "application/octet-stream")], bytes))
}

/// Query parameters for `GET /graph/export`.
#[derive(Debug, Deserialize)]
struct GraphExportParams {
    /// Node cap. `0` asks for the whole graph; absent uses the default cap.
    #[serde(default)]
    limit: Option<usize>,
    /// Comma-separated entity kinds to keep.
    #[serde(default)]
    kinds: Option<String>,
    /// Repository path prefix a node's file must start with.
    #[serde(default)]
    path: Option<String>,
    /// Comma-separated optional node fields: `signature`, `line`.
    #[serde(default)]
    include: Option<String>,
}

/// GET /graph/export: the drawable projection of the daemon's live graph.
///
/// `/graph/bootstrap` already exports this graph, but as the whole binary
/// snapshot: measured on a 730-entity repository it is 3.6 MiB against the
/// 271 KiB a renderer actually draws, and nothing in it is shaped for a
/// consumer. This is the same graph, projected to nodes and links, capped and
/// sampled server side so every consumer draws the same picture.
///
/// Same session-scope resolution as `graph_bootstrap`: a session holding a
/// temporal scope exports the graph that scope names.
async fn graph_export(
    headers: axum::http::HeaderMap,
    Query(params): Query<GraphExportParams>,
    State(state): State<Arc<DaemonState>>,
) -> Result<impl IntoResponse, (StatusCode, String)> {
    use kin_cli::commands::graph_export as export;

    let session_id = extract_session_id_from_headers(&headers)?;
    let graph = resolve_session_graph(&state, session_id.as_ref()).await;

    let options = export::ExportOptions {
        limit: match params.limit {
            // An explicit 0 is the request for every entity. Absent is a
            // request for a drawable default, which is a different question.
            Some(0) => None,
            Some(limit) => Some(limit),
            None => Some(export::DEFAULT_NODE_LIMIT),
        },
        kinds: params
            .kinds
            .as_deref()
            .map(export::parse_kinds)
            .unwrap_or_default(),
        path_prefix: params.path.filter(|prefix| !prefix.is_empty()),
        include: params
            .include
            .as_deref()
            .map(export::IncludeFields::parse)
            .unwrap_or_default(),
    };

    // Read BEFORE the payload is built. A client keeps every event above this
    // number, so reading first can only make it re-apply something the export
    // already contains, which for an upsert is a no-op. Reading after would let
    // an event emitted during the build fall into neither, and that one is lost.
    let seq = state.current_event_seq();

    // Off the request thread. Reading every entity and each one's relations is
    // real CPU work at repository scale, and doing it inline would stall every
    // other request this runtime is serving.
    tokio::task::spawn_blocking(move || {
        let root_hash = hex::encode(graph.compute_root_hash());
        let (node_meta, all_entity_ids, edges) = export::read_graph(graph.as_ref())?;
        Ok::<_, anyhow::Error>(export::assemble_payload(
            root_hash,
            seq,
            node_meta,
            &all_entity_ids,
            edges,
            &options,
        ))
    })
    .await
    .map_err(internal_error)?
    .map(Json)
    .map_err(internal_error)
}

/// Query parameters for `GET /graph/events`.
#[derive(Debug, Deserialize)]
struct GraphEventsParams {
    /// Comma-separated event type names to keep, e.g.
    /// `EntityChanged,RelationChanged`. Absent means every type.
    #[serde(default)]
    types: Option<String>,
}

/// GET /graph/events: the graph-facing view of the daemon event bus.
///
/// The same broadcast channel `/vfs/subscribe` serves, which is left exactly as
/// it was because the VFS daemon and the spine depend on its frames. What this
/// adds is the two things a graph consumer needs and that one does not carry: a
/// `types` filter, so a renderer is not woken by coordination traffic it will
/// throw away, and a first frame naming the current `root_hash`, so a client
/// reconnecting after a gap can tell whether its drawn graph is still the one
/// the daemon holds or has to be re-exported.
async fn graph_events(
    Query(params): Query<GraphEventsParams>,
    State(state): State<Arc<DaemonState>>,
) -> impl IntoResponse {
    let wanted: Option<std::collections::HashSet<String>> = params
        .types
        .as_deref()
        .map(|raw| {
            raw.split(',')
                .map(|name| name.trim().to_string())
                .filter(|name| !name.is_empty())
                .collect::<std::collections::HashSet<String>>()
        })
        .filter(|names| !names.is_empty());

    let mut rx = state.event_tx.subscribe();
    let root_hash = hex::encode(state.graph.compute_root_hash());
    let entity_count = state.graph.entity_count();
    let seq = state.current_event_seq();

    let stream = async_stream::stream! {
        // The resync anchor. `seq` is the one that works between commits: a
        // working-tree edit changes the graph without advancing the root, so a
        // client reconnecting mid-session cannot learn anything from the hash
        // alone. It exports, reads the export's `seq`, subscribes, and discards
        // every event at or below it.
        let connected = json!({
            "type": "connected",
            "entity_count": entity_count,
            "root_hash": root_hash,
            "seq": seq,
        });
        yield Ok::<_, std::convert::Infallible>(format!("data: {connected}\n\n"));

        let mut heartbeat = tokio::time::interval(std::time::Duration::from_secs(30));
        heartbeat.tick().await; // Skip first immediate tick

        loop {
            tokio::select! {
                event = rx.recv() => {
                    match event {
                        Ok(sequenced) => {
                            let keep = wanted
                                .as_ref()
                                .is_none_or(|names| names.contains(sequenced.event.type_name()));
                            if keep {
                                // The sequence is merged into the event object
                                // rather than wrapping it, so a consumer reads
                                // one flat frame and an older one that ignores
                                // the field still parses exactly what it did.
                                if let Ok(mut value) = serde_json::to_value(&sequenced.event) {
                                    if let Some(object) = value.as_object_mut() {
                                        object.insert("seq".to_string(), json!(sequenced.seq));
                                    }
                                    yield Ok(format!("data: {value}\n\n"));
                                }
                            }
                        }
                        Err(tokio::sync::broadcast::error::RecvError::Lagged(n)) => {
                            // Never filtered. A gap is not a graph event, it is
                            // the news that this client's view is now wrong,
                            // and a filter that swallowed it would leave a
                            // consumer patching a graph it has already lost.
                            yield Ok(format!("data: {{\"type\":\"lagged\",\"missed\":{n}}}\n\n"));
                        }
                        Err(tokio::sync::broadcast::error::RecvError::Closed) => {
                            break;
                        }
                    }
                }
                _ = heartbeat.tick() => {
                    yield Ok(": heartbeat\n\n".to_string());
                }
            }
        }
    };

    let mut response = (
        StatusCode::OK,
        [
            (header::CONTENT_TYPE, "text/event-stream"),
            (header::CACHE_CONTROL, "no-cache"),
            (header::CONNECTION, "keep-alive"),
        ],
        axum::body::Body::from_stream(stream),
    )
        .into_response();
    // Prevent nginx from buffering the SSE stream in GKE deployments.
    response.headers_mut().insert(
        axum::http::HeaderName::from_static("x-accel-buffering"),
        axum::http::HeaderValue::from_static("no"),
    );
    response
}

/// POST /locate — run locate against the daemon-resident graph and return the
/// same JSON payload as `kin locate --json`.
///
/// Session scope support: if an `X-Kin-Session` header is present and the
/// session has an active temporal scope, the scoped graph is used for queries
/// that don't specify an explicit `--ref`. Explicit `reference` always wins.
async fn locate(
    headers: axum::http::HeaderMap,
    State(state): State<Arc<DaemonState>>,
    Json(req): Json<kin_cli::daemon_client::LocateRequest>,
) -> Result<impl IntoResponse, (StatusCode, String)> {
    let session_id = extract_session_id_from_headers(&headers)?;
    if req.page_size == Some(0) {
        return Err((
            StatusCode::BAD_REQUEST,
            "locate page_size must be a positive integer".to_string(),
        ));
    }
    let requested_queries = req.queries.clone().unwrap_or_default();
    let include_tests = req.include_tests.unwrap_or(false);
    let explain = req.explain.unwrap_or(false);

    // Resolve the bounded-snippet projection for this request. Off by default
    // (CLI human path, legacy clients); the agent JSON surface sets it so each
    // located definition symbol carries inline code from graph-owned content.
    //
    // The middle case is the one that was missing: a structured caller that
    // declined bodies still wants the graph-native `entities[]` ranking. Falling
    // through to the default options switched the whole projection off, so
    // `kin locate --json --no-snippets` answered a request to spend fewer tokens
    // by returning no results -- the same defect `include_snippet: false` had on
    // the `semantic_locate` arm.
    let snippet_opts = if req.snippets {
        kin_cli::commands::locate::SnippetOptions::enabled(req.snippet_lines)
    } else if req.entity_surface {
        kin_cli::commands::locate::SnippetOptions::enabled(req.snippet_lines).without_bodies()
    } else {
        kin_cli::commands::locate::SnippetOptions::default()
    };

    // Graph version stamps the paging cursor: any mutation bumps `vfs_version`,
    // so a stale cursor can never page a ranking built against different truth.
    let graph_version = state.vfs_version.load(std::sync::atomic::Ordering::SeqCst);
    let requested_page_size = req.page_size;
    let page_size = requested_page_size.unwrap_or_else(kin_cli::commands::locate::entity_page_size);

    // Paging fast path: the cursor names the response projection it came from,
    // so a bare `kin locate --next` reuses that held mode instead of recomputing
    // one from the follow-up command's absent flags.
    if let Some(cursor_token) = req.cursor.as_deref() {
        // A malformed token proves neither its query nor an absolute position.
        // POST already identifies the fused arm, but that is not enough to
        // reinterpret arbitrary bytes as a request for fresh page zero. Only a
        // decoded, now-stale cursor may use the repeated query restart below.
        if kin_cli::commands::locate::LocateCursor::decode(cursor_token).is_none() {
            return Err((
                StatusCode::BAD_REQUEST,
                "locate cursor is invalid; re-run the original query without the cursor"
                    .to_string(),
            ));
        }
        if let Some(parsed) = kin_cli::commands::locate::LocateCursor::decode(cursor_token) {
            let cached = {
                let cache = state.locate_rankings.lock().unwrap();
                cache
                    .get(&parsed.key)
                    .filter(|entry| entry.graph_version == graph_version)
                    .map(|entry| {
                        (
                            entry.query.clone(),
                            entry.entities.clone(),
                            entry.files.clone(),
                            entry.debug.clone(),
                            entry.queries.clone(),
                            entry.requested_queries.clone(),
                            entry.include_tests,
                            entry.reference.clone(),
                            entry.max_files,
                            entry.explain,
                            entry.semantic_coverage.clone(),
                            entry.degradations.clone(),
                            entry.file_granularity,
                            entry.page_size,
                            entry.mode,
                        )
                    })
            };
            if let Some((
                cached_query,
                entities,
                files,
                debug,
                queries,
                cached_requested_queries,
                cached_include_tests,
                cached_reference,
                cached_max_files,
                cached_explain,
                semantic_coverage,
                degradations,
                file_granularity,
                cached_page_size,
                cached_mode,
            )) = cached
            {
                if file_granularity {
                    return Err((
                        StatusCode::BAD_REQUEST,
                        "locate cursor belongs to semantic_locate file granularity; continue it through semantic_locate"
                            .to_string(),
                    ));
                }
                if !req.text.trim().is_empty() && req.text != cached_query {
                    return Err((
                        StatusCode::BAD_REQUEST,
                        "locate cursor belongs to a different query; re-run the requested query"
                            .to_string(),
                    ));
                }
                if let Some(explicit_queries) = req.queries.as_ref() {
                    if explicit_queries != &cached_requested_queries {
                        return Err((
                            StatusCode::BAD_REQUEST,
                            "locate cursor preserves its original query variants; re-run the original query to change them"
                                .to_string(),
                        ));
                    }
                }
                if let Some(explicit_include_tests) = req.include_tests {
                    if explicit_include_tests != cached_include_tests {
                        return Err((
                            StatusCode::BAD_REQUEST,
                            "locate cursor preserves its original test-role scope; re-run the original query to change it"
                                .to_string(),
                        ));
                    }
                }
                if req.reference.is_some() && req.reference != cached_reference {
                    return Err((
                        StatusCode::BAD_REQUEST,
                        "locate cursor preserves its original reference scope; re-run the original query to change it"
                            .to_string(),
                    ));
                }
                if req.max_files_explicit && req.max_files != cached_max_files {
                    return Err((
                        StatusCode::BAD_REQUEST,
                        "locate cursor preserves its original retrieval breadth; use page_size to change only the continuation width"
                            .to_string(),
                    ));
                }
                if let Some(explicit_explain) = req.explain {
                    if explicit_explain && !cached_explain {
                        return Err((
                            StatusCode::BAD_REQUEST,
                            "locate cursor cannot expand a ranking whose explanation was not built; re-run the original query with --explain"
                                .to_string(),
                        ));
                    }
                }
                if let Some(requested_snippets) = req.snippet_override {
                    let cached_snippets =
                        cached_mode == kin_cli::commands::locate::projection_mode(true, true);
                    if requested_snippets != cached_snippets {
                        return Err((
                            StatusCode::BAD_REQUEST,
                            "locate cursor preserves its original snippet projection; re-run the original query to change it"
                                .to_string(),
                        ));
                    }
                }
                // The variant echo travels with the ranking, so a page reports the
                // same fan-out the first page did instead of dropping it.
                let mut result = kin_cli::commands::locate::LocateResult {
                    entities,
                    files,
                    debug,
                    queries,
                    semantic_coverage,
                    degradations,
                    ..Default::default()
                };
                if req.explain == Some(false) {
                    result.debug = None;
                }
                result.all_fallback =
                    kin_cli::commands::locate::locate_entities_are_all_fallback(&result.entities);
                if !file_granularity && result.all_fallback {
                    kin_cli::commands::locate::record_description_query_guidance(
                        &mut result.degradations,
                    );
                }
                let (page_size, start) = continuation_window(
                    requested_page_size,
                    parsed.page_size,
                    parsed.next_offset,
                    parsed.page,
                    cached_page_size,
                );
                if let Err(error) = validate_held_locate_offset(start, result.entities.len()) {
                    return Err((StatusCode::BAD_REQUEST, error));
                }
                kin_cli::commands::locate::apply_entity_page_at_offset(
                    &mut result,
                    &parsed.key,
                    parsed.page,
                    page_size,
                    start,
                );
                return Ok(Json(result));
            }
        }
        // Cache miss / stale decoded cursor: fall through to a fresh run only
        // when the caller repeated the query, so the replacement page is still
        // an answer to the same request. Re-running page zero under a cursor
        // the caller believed was a continuation is the behaviour this
        // replaced: it answers a different question and says nothing about
        // having done so.
        if req.text.trim().is_empty() {
            return Err((
                StatusCode::BAD_REQUEST,
                "locate cursor expired or is unavailable; re-run the original query".to_string(),
            ));
        }
    }

    // Scope token for the cursor key (explicit ref, else the session's temporal
    // scope) so cursors never collide across refs/scopes for the same query.
    let scope_token: Option<String> = if let Some(reference) = req.reference.as_ref() {
        Some(reference.clone())
    } else if let Some(sid) = session_id.as_ref() {
        state
            .get_session_scope(sid)
            .await
            .map(|(ref_str, _, _, _)| ref_str)
    } else {
        None
    };

    tracing::info!(
        ">>> LOCATE: state.graph.embedding_status().indexed={}, graph root hash={:?}",
        state.graph.embedding_status().indexed,
        state.graph.compute_root_hash()
    );

    // Multi-query fan-out: primary text plus any additional variants, deduped.
    // Two-or-more distinct variants trigger RRF fusion; otherwise the single
    // path runs exactly as before (byte-identical).
    let (variants, auto_fanout) =
        with_auto_sharp_variant(build_locate_variants(&req.text, &requested_queries));
    let multi_query = variants.len() >= 2;
    // The caller's role ask, resolved once so every arm below runs the same
    // scope. Absent on an older client, which is the documented default.
    let scope = kin_cli::commands::locate::LocateScope::with_tests(include_tests);

    let mut result = if let Some(reference) = req.reference.as_deref() {
        // Explicit --ref always takes precedence over session scope. Ref
        // resolution is a graph-only read; import and repair are explicit
        // repository transactions.
        let repository_authority = state
            .local_repository_authority_binding()
            .map_err(repository_authority_error)?;
        let head = kin_cli::commands::ref_lookup::resolve_ref(
            state.graph.as_ref(),
            &repository_authority,
            Some(reference),
        )
        .map_err(|err| (StatusCode::BAD_REQUEST, err.to_string()))?;
        if multi_query {
            run_multiquery_locate_at_ref(
                &state,
                &repository_authority,
                &head,
                reference,
                &variants,
                auto_fanout,
                explain,
                req.max_files,
                req.max_files_explicit,
                snippet_opts,
                scope,
            )
        } else {
            kin_cli::commands::locate::run_with_graph_capture_at_ref(
                &repository_authority,
                state.graph.as_ref(),
                state.blobs.as_ref(),
                &head,
                reference,
                &req.text,
                explain,
                req.max_files,
                req.max_files_explicit,
                snippet_opts,
                scope,
            )
            .map_err(|error| error.to_string())
        }
    } else {
        // Use scoped graph if session has a temporal scope, otherwise HEAD.
        let graph = resolve_session_graph(&state, session_id.as_ref()).await;
        if multi_query {
            run_multiquery_fused_locate(
                &state,
                session_id.as_ref(),
                graph.as_ref(),
                &variants,
                auto_fanout,
                explain,
                req.max_files,
                req.max_files_explicit,
                snippet_opts,
                scope,
            )
            .await
        } else {
            run_fused_locate_for_state(
                &state,
                session_id.as_ref(),
                graph.as_ref(),
                &req.text,
                explain,
                req.max_files,
                req.max_files_explicit,
                snippet_opts,
                scope,
            )
            .await
        }
    }
    .map_err(internal_error)?;

    // Cache the full entity ranking and window page 0 so a follow-up `--next`
    // pages it from cache without re-running retrieval. Keyed by
    // (query, ref/scope, graph-version, body-mode) so any edit invalidates the
    // page and a caller paging in one body mode never receives a ranking built in
    // the other. A multi-query ranking keys off the joined variants so it cannot
    // collide with any single-variant cursor.
    let key_text = if multi_query {
        multiquery_cursor_text(&variants)
    } else {
        req.text.clone()
    };
    let key = kin_cli::commands::locate::locate_cursor_key(
        &key_text,
        scope_token.as_deref(),
        graph_version,
        snippet_opts.projection_mode(),
    );
    // Only a request that actually projected `entities[]` has a ranking worth
    // holding. The no-projection path leaves it empty, issues no cursor, and never
    // reads this cache, so writing to it can only do harm: it would publish an
    // empty ranking under a key another mode's live cursor might present.
    if snippet_opts.enabled {
        cache_locate_ranking(
            &state,
            &key,
            &req.text,
            &result,
            CachedLocateShape {
                file_granularity: false,
                snippet_alias: false,
                requested_queries: requested_queries.clone(),
                include_tests,
                reference: req.reference.clone(),
                max_files: req.max_files,
                explain,
                page_size,
                graph_version,
                mode: snippet_opts.projection_mode(),
            },
        );
    }
    if snippet_opts.enabled && result.all_fallback {
        kin_cli::commands::locate::record_description_query_guidance(&mut result.degradations);
    }
    kin_cli::commands::locate::apply_entity_page(&mut result, &key, 0, page_size);
    Ok(Json(result))
}

/// Run the fused locate pipeline against daemon state for a non-ref query,
/// exactly as `POST /locate` serves it: session temporal scope honored,
/// historical test-artifact priority files discovered for scoped sessions,
/// and the HEAD graph passed as vector source. Shared by the `/locate`
/// endpoint and the fused `semantic_locate` MCP arm so the two agent-facing
/// retrieval surfaces cannot drift apart.
#[allow(clippy::too_many_arguments)]
async fn run_fused_locate_for_state(
    state: &Arc<DaemonState>,
    session_id: Option<&SessionId>,
    graph: &kin_db::InMemoryGraph,
    text: &str,
    explain: bool,
    max_files: usize,
    max_files_explicit: bool,
    snippet_opts: kin_cli::commands::locate::SnippetOptions,
    scope: kin_cli::commands::locate::LocateScope,
) -> Result<kin_cli::commands::locate::LocateResult, String> {
    // Bound to this daemon's shared per-publication load, and resolved only if
    // the page actually projects a body: a locate that returns no snippets
    // never opens authority at all.
    let repository_authority = shared_authority_source(
        state,
        state
            .local_repository_authority_binding()
            .map_err(|error| error.to_string())?,
    );
    // When a session scope is active, discover historical test artifact
    // priority files to match the ref-scoped path's behavior.
    let session_scope = if let Some(sid) = session_id {
        state.get_session_scope(sid).await
    } else {
        None
    };
    let scope_ref_string = session_scope
        .as_ref()
        .map(|(ref_str, _, _, _)| ref_str.clone());
    // The scoped graph is a historical view; its source projection must resolve
    // at the scoped head, not at the workspace head.
    let source_scope = match session_scope.as_ref() {
        Some((_, head, _, _)) => kin_mcp::handlers::common::EntitySourceScope::At(*head),
        None => kin_mcp::handlers::common::EntitySourceScope::WorkspaceHead,
    };
    let extra_priority_files = scope_ref_string
        .as_deref()
        .map(|ref_str| {
            // `graph` is the session's ref-scoped graph, so the historical
            // test-artifact signal is read from its graph-owned truth.
            kin_cli::commands::locate::discover_historical_test_artifact_priority_files(
                graph, ref_str, text,
            )
        })
        .unwrap_or_default();

    // Always pass the HEAD graph as vector source for embedding signals.
    // For scoped sessions, the scoped graph has no vector index — HEAD
    // vectors are queried and post-filtered to the scoped entity set.
    // For unscoped queries, the HEAD graph IS the primary graph, so
    // vector_source provides the same index — but extract_embedding_signals
    // only uses vector_source when the primary graph has no embeddings,
    // so there's no double-query.
    let vector_source = Some(state.graph.as_ref());
    kin_cli::commands::locate::run_with_graph_capture_with_priority_files_and_vector_source(
        graph,
        None,
        text,
        explain,
        max_files,
        max_files_explicit,
        extra_priority_files,
        vector_source,
        snippet_opts,
        Some(&repository_authority),
        source_scope,
        scope,
    )
    .map_err(|error| error.to_string())
}

#[allow(clippy::too_many_arguments)]
fn run_fused_locate_for_hosted_view(
    request: &HostedSemanticRequest,
    request_deadline: Instant,
    text: &str,
    explain: bool,
    max_files: usize,
    max_files_explicit: bool,
    snippet_opts: kin_cli::commands::locate::SnippetOptions,
    scope: kin_cli::commands::locate::LocateScope,
) -> Result<kin_cli::commands::locate::LocateResult, String> {
    let view = request.view();
    kin_cli::commands::locate::run_with_graph_capture_with_priority_files_and_vector_source_capped(
        view.graph.as_ref(),
        None,
        text,
        explain,
        max_files,
        max_files_explicit,
        Vec::new(),
        Some(view.graph.as_ref()),
        snippet_opts,
        Some(request.source_authority()),
        kin_mcp::handlers::common::EntitySourceScope::WorkspaceHead,
        scope,
        request_deadline.saturating_duration_since(Instant::now()),
    )
    .map_err(|error| error.to_string())
}

#[allow(clippy::too_many_arguments)]
fn run_multiquery_fused_locate_for_hosted_view(
    request: &HostedSemanticRequest,
    request_deadline: Instant,
    variants: &[String],
    auto_fanout: bool,
    explain: bool,
    max_files: usize,
    max_files_explicit: bool,
    snippet_opts: kin_cli::commands::locate::SnippetOptions,
    scope: kin_cli::commands::locate::LocateScope,
) -> Result<kin_cli::commands::locate::LocateResult, String> {
    let mut per_variant = Vec::with_capacity(variants.len());
    for (index, variant) in variants.iter().enumerate() {
        per_variant.push(run_fused_locate_for_hosted_view(
            request,
            request_deadline,
            variant,
            explain,
            max_files,
            max_files_explicit,
            snippet_opts,
            scope,
        )?);
        if index == 0
            && auto_fanout
            && !kin_cli::commands::locate::auto_fanout_should_fuse_for(&per_variant[0])
        {
            return Ok(per_variant.pop().expect("primary result present"));
        }
    }
    let primary_declared = per_variant
        .first()
        .map(|result| result.files.len())
        .unwrap_or(0);
    let mut fused = kin_cli::commands::locate::fuse_locate_results(
        variants.to_vec(),
        per_variant,
        kin_cli::commands::locate::locate_rrf_k(),
    );
    if auto_fanout {
        kin_cli::commands::locate::bound_fused_declaration_to_primary(
            &mut fused,
            primary_declared,
            !max_files_explicit,
        );
    }
    Ok(fused)
}

/// Build the ordered, deduped query-variant list for a multi-query locate: the
/// primary query first (when non-empty), then each extra variant, trimmed and
/// de-duplicated exactly so the same phrasing is never retrieved twice. A result
/// with fewer than two entries means a single-query locate (no fan-out).
/// Append the automatic identifier-distilled sharp variant when the caller
/// supplied a single query and the text carries identifier-shaped tokens.
/// The broad raw text and the concentrated identifier query then fuse through
/// the existing multi-query union instead of one regime displacing the other.
/// `KIN_LOCATE_AUTO_QUERY_FANOUT=0` restores single-query behavior.
fn with_auto_sharp_variant(mut variants: Vec<String>) -> (Vec<String>, bool) {
    if variants.len() != 1 {
        return (variants, false);
    }
    let enabled = std::env::var("KIN_LOCATE_AUTO_QUERY_FANOUT")
        .map(|value| {
            !matches!(
                value.trim().to_ascii_lowercase().as_str(),
                "0" | "false" | "no" | "off"
            )
        })
        .unwrap_or(true);
    if !enabled {
        return (variants, false);
    }
    let sharp = kin_cli::commands::locate::identifier_distilled_query(&variants[0]);
    if !sharp.is_empty() && sharp != variants[0] {
        variants.push(sharp);
        return (variants, true);
    }
    (variants, false)
}

fn build_locate_variants(primary: &str, extra: &[String]) -> Vec<String> {
    let mut variants: Vec<String> = Vec::new();
    let mut seen: HashSet<String> = HashSet::new();
    for candidate in std::iter::once(primary).chain(extra.iter().map(String::as_str)) {
        let trimmed = candidate.trim();
        if trimmed.is_empty() {
            continue;
        }
        if seen.insert(trimmed.to_string()) {
            variants.push(trimmed.to_string());
        }
    }
    variants
}

/// Canonical cursor-key text for a multi-query ranking: the variants joined by a
/// unit-separator control char so a fused ranking can never collide with any
/// single-variant ranking's cursor key.
fn multiquery_cursor_text(variants: &[String]) -> String {
    variants.join("\u{1f}")
}

/// Validate the request-shape fields the `semantic_locate` schema declares.
///
/// MCP clients normally validate against the advertised schema, but the daemon
/// endpoint is also callable directly. Presence must therefore survive here:
/// a present value of the wrong type cannot become indistinguishable from an
/// omitted field and silently select a different scope, body mode, ranking, or
/// response width.
fn validate_semantic_locate_argument_types(
    arguments: &HashMap<String, serde_json::Value>,
) -> Result<(), String> {
    for key in ["query", "cursor", "granularity", "pipeline"] {
        if arguments.get(key).is_some_and(|value| !value.is_string()) {
            return Err(format!("invalid {key}: expected a string"));
        }
    }

    for key in [
        "compact",
        "include_snippet",
        "snippet_alias",
        "include_tests",
        "explain",
    ] {
        if arguments.get(key).is_some_and(|value| !value.is_boolean()) {
            return Err(format!("invalid {key}: expected a boolean"));
        }
    }

    for key in ["limit", "page_size"] {
        if let Some(value) = arguments.get(key) {
            let Some(value) = value.as_u64() else {
                return Err(format!("invalid {key}: expected a positive integer"));
            };
            if value == 0 {
                return Err(format!("invalid {key}: expected a positive integer"));
            }
        }
    }

    for key in ["max_chars", "max_response_chars"] {
        if arguments
            .get(key)
            .is_some_and(|value| value.as_u64().is_none())
        {
            return Err(format!("invalid {key}: expected a non-negative integer"));
        }
    }

    if let Some(queries) = arguments.get("queries") {
        let Some(queries) = queries.as_array() else {
            return Err("invalid queries: expected an array of strings".to_string());
        };
        if queries.iter().any(|query| !query.is_string()) {
            return Err("invalid queries: expected every item to be a string".to_string());
        }
    }

    Ok(())
}

/// Read a validated JSON string-array MCP argument into an owned `Vec<String>`.
/// Absent means no additional variants.
fn arg_string_array(arguments: &HashMap<String, serde_json::Value>, key: &str) -> Vec<String> {
    arguments
        .get(key)
        .and_then(serde_json::Value::as_array)
        .map(|items| {
            items
                .iter()
                .filter_map(serde_json::Value::as_str)
                .map(str::to_string)
                .collect()
        })
        .unwrap_or_default()
}

/// Fan out a multi-query locate over daemon state: retrieve each variant through
/// the same fused pipeline `run_fused_locate_for_state` serves, then RRF-fuse the
/// per-variant rankings into one deduped result with per-hit variant attribution.
/// Variants are retrieved in order so the fusion is fully deterministic.
#[allow(clippy::too_many_arguments)]
async fn run_multiquery_fused_locate(
    state: &Arc<DaemonState>,
    session_id: Option<&SessionId>,
    graph: &kin_db::InMemoryGraph,
    variants: &[String],
    auto_fanout: bool,
    explain: bool,
    max_files: usize,
    max_files_explicit: bool,
    snippet_opts: kin_cli::commands::locate::SnippetOptions,
    scope: kin_cli::commands::locate::LocateScope,
) -> Result<kin_cli::commands::locate::LocateResult, String> {
    let mut per_variant = Vec::with_capacity(variants.len());
    for (index, variant) in variants.iter().enumerate() {
        per_variant.push(
            run_fused_locate_for_state(
                state,
                session_id,
                graph,
                variant,
                explain,
                max_files,
                max_files_explicit,
                snippet_opts,
                scope,
            )
            .await?,
        );
        // The automatic sharp variant fuses only when the primary is unsure.
        // Direct-entity-ordered rankings always fuse (their top1/top2 gap
        // measures lexical concentration, not confidence); RRF-composed
        // rankings skip fusion when confidently separated, and the second
        // retrieval never runs on a skip. Caller-supplied variants keep
        // unconditional fusion semantics.
        if index == 0 && auto_fanout {
            if !kin_cli::commands::locate::auto_fanout_should_fuse_for(&per_variant[0]) {
                return Ok(per_variant.pop().expect("primary result present"));
            }
        }
    }
    let primary_declared = per_variant
        .first()
        .map(|result| result.files.len())
        .unwrap_or(0);
    let mut fused = kin_cli::commands::locate::fuse_locate_results(
        variants.to_vec(),
        per_variant,
        kin_cli::commands::locate::locate_rrf_k(),
    );
    // The automatic sharp variant reorders within the declaration budget the
    // primary earned; it must not widen it. Caller-supplied fusion keeps its
    // union width.
    if auto_fanout {
        kin_cli::commands::locate::bound_fused_declaration_to_primary(
            &mut fused,
            primary_declared,
            !max_files_explicit,
        );
    }
    Ok(fused)
}

/// Fan out a multi-query locate at an explicit ref: retrieve each variant against
/// the resolved head graph, then RRF-fuse. Mirrors `run_multiquery_fused_locate`
/// for the `--ref` path so multi-query is honored there too rather than silently
/// dropping the extra variants.
#[allow(clippy::too_many_arguments)]
fn run_multiquery_locate_at_ref(
    state: &Arc<DaemonState>,
    repository_authority: &kin_core::LocalRepositoryAuthorityBinding,
    head: &kin_model::SemanticChangeId,
    reference: &str,
    variants: &[String],
    auto_fanout: bool,
    explain: bool,
    max_files: usize,
    max_files_explicit: bool,
    snippet_opts: kin_cli::commands::locate::SnippetOptions,
    scope: kin_cli::commands::locate::LocateScope,
) -> Result<kin_cli::commands::locate::LocateResult, String> {
    let mut per_variant = Vec::with_capacity(variants.len());
    for (index, variant) in variants.iter().enumerate() {
        per_variant.push(
            kin_cli::commands::locate::run_with_graph_capture_at_ref(
                repository_authority,
                state.graph.as_ref(),
                state.blobs.as_ref(),
                head,
                reference,
                variant,
                explain,
                max_files,
                max_files_explicit,
                snippet_opts,
                scope,
            )
            .map_err(|error| error.to_string())?,
        );
        // Same confidence gate as the daemon-state path: the automatic sharp
        // variant only fuses an unsure primary; caller-supplied variants keep
        // unconditional fusion semantics.
        if index == 0
            && auto_fanout
            && !kin_cli::commands::locate::auto_fanout_should_fuse_for(&per_variant[0])
        {
            return Ok(per_variant.pop().expect("primary result present"));
        }
    }
    let primary_declared = per_variant
        .first()
        .map(|result| result.files.len())
        .unwrap_or(0);
    let mut fused = kin_cli::commands::locate::fuse_locate_results(
        variants.to_vec(),
        per_variant,
        kin_cli::commands::locate::locate_rrf_k(),
    );
    // The automatic sharp variant reorders within the declaration budget the
    // primary earned; it must not widen it. Caller-supplied fusion keeps its
    // union width.
    if auto_fanout {
        kin_cli::commands::locate::bound_fused_declaration_to_primary(
            &mut fused,
            primary_declared,
            !max_files_explicit,
        );
    }
    Ok(fused)
}

/// Insert a full locate ranking into the paging cache, evicting the oldest entry
/// when the cache is at capacity (a fresh key past the cap). The cache is bounded
/// to [`LOCATE_RANKING_CACHE_CAP`], so the linear eviction scan stays cheap.
#[derive(Clone)]
struct CachedLocateShape {
    file_granularity: bool,
    snippet_alias: bool,
    requested_queries: Vec<String>,
    include_tests: bool,
    reference: Option<String>,
    max_files: usize,
    explain: bool,
    page_size: usize,
    graph_version: u64,
    mode: &'static str,
}

fn cache_locate_ranking(
    state: &DaemonState,
    key: &str,
    query: &str,
    result: &kin_cli::commands::locate::LocateResult,
    shape: CachedLocateShape,
) {
    cache_locate_ranking_in(&state.locate_rankings, None, key, query, result, shape);
}

/// Retain one full ranking in a NAMED cache.
///
/// The map is a parameter rather than `state.locate_rankings` because hosted
/// and local rankings must not share a namespace: a hosted cursor carries an
/// inner locate cursor, and if both arms addressed one map a forged inner
/// cursor could reach a ranking the caller's repository never produced.
fn cache_locate_ranking_in(
    rankings: &std::sync::Mutex<HashMap<String, CachedLocateRanking>>,
    repo_id: Option<&str>,
    key: &str,
    query: &str,
    result: &kin_cli::commands::locate::LocateResult,
    shape: CachedLocateShape,
) {
    let mut cache = rankings.lock().unwrap();
    if !cache.contains_key(key) {
        // Both halves filter, and that is the whole fix. Counting globally and
        // evicting per repository is worse than doing neither: the cap fires on
        // the global length, the filtered search finds none of this
        // repository's own entries to evict, nothing is removed, and the map
        // grows without bound while still reading as capped.
        let held_for_repo = cache
            .values()
            .filter(|entry| entry.repo_id.as_deref() == repo_id)
            .count();
        if held_for_repo >= LOCATE_RANKING_CACHE_CAP {
            if let Some(oldest) = cache
                .iter()
                .filter(|(_, entry)| entry.repo_id.as_deref() == repo_id)
                .min_by_key(|(_, entry)| entry.created)
                .map(|(k, _)| k.clone())
            {
                cache.remove(&oldest);
            }
            // The `None` arm is unreachable while the cap is positive, because
            // reaching it requires this repository to hold at least the cap and
            // therefore at least one entry. If a future cap of zero made it
            // reachable, skipping the eviction is the safe reading: the insert
            // below still lands and the global ceiling still bounds the map.
        }
        // The global ceiling, above the per-repo cap rather than instead of it.
        // Without it, per-repo fairness costs sixty-four full rankings per
        // repository with no bound on the repository count, and a ranking
        // clones its entities, files, debug payload and queries.
        while cache.len() >= LOCATE_RANKING_CACHE_GLOBAL_CAP {
            let Some(oldest) = cache
                .iter()
                .min_by_key(|(_, entry)| entry.created)
                .map(|(k, _)| k.clone())
            else {
                break;
            };
            cache.remove(&oldest);
        }
    }
    cache.insert(
        key.to_string(),
        CachedLocateRanking {
            repo_id: repo_id.map(ToOwned::to_owned),
            query: query.to_string(),
            entities: result.entities.clone(),
            files: result.files.clone(),
            debug: result.debug.clone(),
            queries: result.queries.clone(),
            requested_queries: shape.requested_queries,
            include_tests: shape.include_tests,
            reference: shape.reference,
            max_files: shape.max_files,
            explain: shape.explain,
            semantic_coverage: result.semantic_coverage.clone(),
            degradations: result.degradations.clone(),
            file_granularity: shape.file_granularity,
            snippet_alias: shape.snippet_alias,
            page_size: shape.page_size.max(1),
            graph_version: shape.graph_version,
            mode: shape.mode,
            created: std::time::Instant::now(),
        },
    );
}

/// POST /search — run CLI search against daemon-owned graph state.
async fn search(
    headers: axum::http::HeaderMap,
    State(state): State<Arc<DaemonState>>,
    Json(req): Json<kin_cli::commands::search::DaemonSearchRequest>,
) -> Result<impl IntoResponse, (StatusCode, String)> {
    if !state
        .is_initialized
        .load(std::sync::atomic::Ordering::Relaxed)
    {
        return Err((
            StatusCode::SERVICE_UNAVAILABLE,
            "daemon not fully initialized".to_string(),
        ));
    }

    let session_id = extract_session_id_from_headers(&headers)?;
    let graph = resolve_session_graph(&state, session_id.as_ref()).await;
    let mut result = kin_cli::commands::search::collect_daemon_search_response(
        graph.as_ref(),
        &req,
        // Same substrate reading the impact and trace routes supply, from the
        // same helper, so no CLI surface can be more confident than its MCP
        // counterpart about one daemon at one instant (FIR-2524).
        &kin_mcp::Envelope::daemon().with_health(&daemon_health_snapshot(&state).await),
    )
    .map_err(internal_error)?;
    if req.show_body {
        attach_search_bodies(&state, &mut result, req.body_limit.unwrap_or(10));
    }
    Ok(Json(result))
}

/// Turn a `get_context_pack` call's names and question into focal entities
/// before the pack builder sees it.
///
/// The identity resolver lives in kin-cli, which kin-mcp cannot reach, so this
/// is where a name becomes an entity. Names are resolved first and in the
/// caller's order, because a name is a stronger claim than a ranking's
/// suggestion, and each resolved entry carries how it was resolved so the
/// pack's method line can still say.
///
/// Leaves an argument in place when nothing resolved it, so the builder refuses
/// over it. That is deliberate: a name the graph does not carry and a name
/// nobody tried to resolve are different failures, and quietly dropping the
/// field would report the first as the second.
fn resolve_context_pack_focals(
    graph: &kin_db::InMemoryGraph,
    arguments: &HashMap<String, serde_json::Value>,
) -> HashMap<String, serde_json::Value> {
    let mut arguments = arguments.clone();
    let limit = arguments
        .get("max_focals")
        .and_then(serde_json::Value::as_u64)
        .unwrap_or(kin_cli::commands::context::QUESTION_FOCAL_MAX as u64)
        .clamp(1, 32) as usize;
    let mut focals: Vec<serde_json::Value> = Vec::new();
    let mut seen: Vec<String> = Vec::new();

    let named: Vec<String> = arguments
        .get("entities")
        .and_then(serde_json::Value::as_array)
        .map(|values| {
            values
                .iter()
                .filter_map(|value| value.as_str().map(str::to_string))
                .collect()
        })
        .unwrap_or_default();
    for token in &named {
        let Ok(Some(entry)) = kin_cli::commands::context::resolve_focal_for_mcp(graph, token)
        else {
            continue;
        };
        let id = entry
            .get("entity_id")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default()
            .to_string();
        if id.is_empty() || seen.contains(&id) {
            continue;
        }
        seen.push(id);
        focals.push(entry);
    }
    if !named.is_empty() && !focals.is_empty() {
        arguments.remove("entities");
    }

    let question = arguments
        .get("question")
        .and_then(serde_json::Value::as_str)
        .map(str::to_string);
    if let Some(question) = question {
        if let Ok((ranked, coverage)) =
            kin_cli::commands::context::question_focals(graph, &question, limit)
        {
            arguments.insert("coverage".to_string(), json!(coverage));
            for hit in ranked {
                if focals.len() >= limit || seen.contains(&hit.entity_id) {
                    continue;
                }
                seen.push(hit.entity_id.clone());
                focals.push(json!({
                    "entity_id": hit.entity_id,
                    "score": hit.score,
                    "route": "question",
                }));
            }
            if !focals.is_empty() {
                arguments.remove("question");
            }
        }
    }

    if !focals.is_empty() {
        focals.truncate(limit);
        arguments.insert("question_focals".to_string(), json!(focals));
    }
    arguments
}

