    #[test]
    fn semloc_rerank_priority_demotes_and_boosts() {
        use kin_model::EntityRole;
        let q = "raspbian package detection";
        // Equal cosine distance: a Source entity outranks (lower priority than) a
        // Test/Docs/Generated/Vendored entity when the query is not test-related.
        let src = semloc_rerank_priority(Some(EntityRole::Source), "Detector", q, false, 0.30);
        for role in [
            EntityRole::Test,
            EntityRole::Docs,
            EntityRole::Generated,
            EntityRole::Vendored,
        ] {
            let demoted = semloc_rerank_priority(Some(role), "Detector", q, false, 0.30);
            assert!(
                demoted > src,
                "{role:?} must be demoted below Source at equal cosine"
            );
        }
        // External / unknown role are NOT demoted.
        assert!(
            (semloc_rerank_priority(Some(EntityRole::External), "X", q, false, 0.30) - 0.30).abs()
                < 1e-6
        );
        assert!((semloc_rerank_priority(None, "X", q, false, 0.30) - 0.30).abs() < 1e-6);
    }

    #[test]
    fn semloc_name_match_classifies_exact_partial_none() {
        // A query token equal to the whole name is exact.
        assert_eq!(semloc_name_match("find the Detector", "Detector"), "exact");
        // A qualified name matches on its last dotted segment.
        assert_eq!(
            semloc_name_match("constant Raspbian", "constant.Raspbian"),
            "exact"
        );
        // Shared snake-case token, but no whole-name token match -> partial.
        assert_eq!(
            semloc_name_match("parse the request body", "parse_request"),
            "partial"
        );
        // No shared token -> none.
        assert_eq!(semloc_name_match("configure logging", "Detector"), "none");
        // Empty name is never a match.
        assert_eq!(semloc_name_match("anything", ""), "none");
        // Deterministic across repeated calls.
        for _ in 0..100 {
            assert_eq!(
                semloc_name_match("parse the request body", "parse_request"),
                "partial"
            );
        }
    }

    /// FIR-2199. The cosine arm, then the shipped default, emitted neither
    /// disclosure field.
    ///
    /// Measured on the shipped default profile, `match_kind` was absent from all
    /// 188 result rows across 40 queries and `all_fallback` never appeared once,
    /// while accuracy-v1 emitted both on the same battery. Those are the two
    /// signals `semantic_locate`'s own description names as the caller's defence
    /// against a full, confident-looking page for a symbol that does not exist,
    /// so every stock daemon was serving pages with the defence missing.
    #[test]
    fn the_cosine_arm_classifies_every_hit_and_agrees_with_its_own_evidence() {
        use kin_cli::commands::locate::LocateMatchKind;

        // A query token that IS the name: the query asked for this symbol.
        assert_eq!(
            cosine_match_kind("find Detector please", "Detector"),
            LocateMatchKind::Name
        );
        // A qualified name matches on its last dotted segment, the same way the
        // evidence object resolves it.
        assert_eq!(
            cosine_match_kind("constant Raspbian", "constant.Raspbian"),
            LocateMatchKind::Name
        );
        // Prose that never names the symbol: embedding similarity surfaced it.
        // `Semantic`, never `TextFallback` — this arm has no lexical pool to
        // attribute a hit to, and claiming one would be a fabricated provenance.
        assert_eq!(
            cosine_match_kind("where do we handle retries", "Detector"),
            LocateMatchKind::Semantic
        );
        // A partial token overlap is not a name hit. This is the case that makes
        // the field worth reading: the page looks responsive and is not.
        assert_eq!(
            cosine_match_kind("parse the request body", "parse_request"),
            LocateMatchKind::Semantic
        );

        // The anti-drift property: for one hit, `match_kind == Name` exactly when
        // the `match_evidence.name_match` printed beside it says `exact`. Two
        // fields on one row disagreeing is the defect class this lane exists to
        // remove.
        for (query, name) in [
            ("find Detector please", "Detector"),
            ("constant Raspbian", "constant.Raspbian"),
            ("where do we handle retries", "Detector"),
            ("parse the request body", "parse_request"),
            ("", "Detector"),
            ("Detector", ""),
        ] {
            let names_it = cosine_match_kind(query, name) == LocateMatchKind::Name;
            let evidence_says_exact =
                cosine_match_evidence(query, name, None, false, false)["name_match"] == "exact";
            assert_eq!(
                names_it, evidence_says_exact,
                "match_kind and match_evidence must agree for ({query:?}, {name:?})"
            );
        }
    }

    #[test]
    fn all_fallback_is_a_verdict_on_the_whole_ranking_and_can_be_absent() {
        use kin_cli::commands::locate::LocateMatchKind;
        let named = json!({ "match_kind": LocateMatchKind::Name });
        let similar = json!({ "match_kind": LocateMatchKind::Semantic });

        // Every row surfaced by similarity and none named: the page is a set of
        // neighbors, not the answer it looks like.
        assert!(locate_rows_are_all_fallback(&[
            similar.clone(),
            similar.clone()
        ]));

        // Positive control: ONE name hit anywhere in the retained ranking clears
        // the flag, so it distinguishes the two cases rather than always firing.
        assert!(!locate_rows_are_all_fallback(&[
            similar.clone(),
            named.clone()
        ]));
        // Including when the name hit is deep enough to sit on a later page. A
        // per-page verdict would call this a fallback while paging.
        let mut deep = vec![similar.clone(); 40];
        deep.push(named);
        assert!(!locate_rows_are_all_fallback(&deep));

        // An empty ranking is not all-fallback: nothing came back, so there is
        // nothing to mistake for an answer, and the negative envelope is what
        // speaks to an empty page.
        assert!(!locate_rows_are_all_fallback(&[]));

        // A row with no classification at all cannot clear the flag by accident,
        // and cannot set it either: it is not a name hit, so a ranking of such
        // rows reads as fallback, which is the weaker claim.
        assert!(locate_rows_are_all_fallback(&[json!({ "name": "x" })]));
    }

    #[test]
    fn saturated_cosine_candidate_window_is_a_real_degradation() {
        let mut degradations = Vec::new();
        record_cosine_candidate_cap(8, 7, &mut degradations);
        assert!(degradations.is_empty());

        record_cosine_candidate_cap(8, 8, &mut degradations);
        assert_eq!(degradations.len(), 1);
        assert_eq!(degradations[0].component, "ranking_window");
        assert_eq!(degradations[0].reason, "candidate_cap_reached");
        assert!(degradations[0]
            .detail
            .contains("considered the full fetched candidate window"));
        assert!(degradations[0]
            .detail
            .contains("retained every successfully projected unique row"));
    }

    #[test]
    fn cosine_projection_retains_and_pages_rows_beyond_five_pages() {
        let (rows, fetched) = search_and_project_all_cosine_candidates(
            "held query",
            8,
            |query, fetch_limit| {
                assert_eq!(query, "held query");
                assert_eq!(fetch_limit, 8);
                Ok::<_, ()>((0..7).collect())
            },
            |raw| raw,
            |index| Some(json!({ "name": format!("row_{index}") })),
        )
        .unwrap();
        assert_eq!(
            fetched, 7,
            "the whole mocked search window reaches retention"
        );
        assert_eq!(rows.len(), 7, "all successful projections must be held");

        let (page_five, total, more, next) = window_semantic_rows(&rows, 5, 1);
        assert_eq!(page_five[0]["name"], "row_5");
        assert_eq!(total, 7);
        assert!(more);
        assert_eq!(next, 6);

        let (page_six, total, more, next) = window_semantic_rows(&rows, next, 1);
        assert_eq!(page_six[0]["name"], "row_6");
        assert_eq!(total, 7);
        assert!(!more);
        assert_eq!(next, 7);
    }

    #[test]
    fn continuation_offsets_survive_repeated_budget_width_recovery() {
        // Ordinary width changes never move the absolute resume position.
        let (width, start) = continuation_window(Some(2), Some(6), Some(6), 1, 6);
        assert_eq!((width, start), (2, 6));

        // The response budget repairs the cursor itself. Page zero was six rows
        // wide and four were withheld, so the next absolute row becomes two.
        let mut first = kin_core::LocateCursor {
            key: "k".to_string(),
            page: 1,
            next_offset: Some(6),
            page_size: Some(6),
        };
        assert!(first.rebase_after_withheld(4, 2));
        let (width, start) =
            continuation_window(None, first.page_size, first.next_offset, first.page, 6);
        assert_eq!((width, start), (2, 2));

        // A later page cut is the same arithmetic over its absolute offset.
        let mut second = kin_core::LocateCursor {
            key: "k".to_string(),
            page: 2,
            next_offset: Some(4),
            page_size: Some(2),
        };
        assert!(second.rebase_after_withheld(1, 1));
        let (width, start) =
            continuation_window(None, second.page_size, second.next_offset, second.page, 6);
        assert_eq!((width, start), (1, 3));

        // With no cut, the absolute offset is authoritative and the width
        // encoded by the cursor persists on a bare continuation.
        let (width, start) = continuation_window(None, Some(1), Some(4), 3, 6);
        assert_eq!((width, start), (1, 4));

        // Released two-part cursors have no offset or width, so retain their old
        // page-times-effective-width fallback.
        let (width, start) = continuation_window(Some(5), None, None, 2, 20);
        assert_eq!((width, start), (5, 40));
    }

    #[test]
    fn fused_cursor_explanation_can_contract_but_cannot_expand() {
        let mut arguments = HashMap::new();
        assert!(validate_fused_cursor_shape(&arguments, &[], false, false).is_ok());

        arguments.insert("explain".to_string(), json!(true));
        assert!(validate_fused_cursor_shape(&arguments, &[], false, false).is_err());

        arguments.insert("explain".to_string(), json!(false));
        assert!(
            validate_fused_cursor_shape(&arguments, &[], false, true).is_ok(),
            "a page may omit explanation data its held ranking already carries"
        );

        arguments.remove("explain");
        arguments.insert("compact".to_string(), json!(false));
        assert!(
            validate_fused_cursor_shape(&arguments, &[], false, false).is_err(),
            "compact:false cannot synthesize explanation the held ranking never built"
        );
        assert!(validate_fused_cursor_shape(&arguments, &[], false, true).is_ok());

        // Clients commonly materialize the schema's `explain: false` default.
        // With `compact: false`, the fresh call normalized that exact pair to
        // an explanation-bearing ranking, so its cursor must accept the same
        // pair rather than comparing the raw false to the cached effective true.
        arguments.insert("explain".to_string(), json!(false));
        assert!(validate_fused_cursor_shape(&arguments, &[], false, true).is_ok());
        assert!(validate_fused_cursor_shape(&arguments, &[], false, false).is_err());

        arguments.insert("compact".to_string(), json!(true));
        assert!(validate_fused_cursor_shape(&arguments, &[], false, true).is_ok());
        assert!(validate_fused_cursor_shape(&arguments, &[], false, false).is_ok());

        arguments.insert("explain".to_string(), json!(true));
        assert!(
            !fused_explanation_requested(&arguments),
            "explicit compact:true wins over explain:true, matching ResponseBudget"
        );
        assert!(validate_fused_cursor_shape(&arguments, &[], false, false).is_ok());
    }

    #[test]
    fn cursor_projection_inherits_omissions_and_rejects_conflicts() {
        let omitted = HashMap::new();
        assert!(validate_cursor_projection(
            &omitted,
            "find parser",
            false,
            kin_cli::commands::locate::projection_mode(true, true),
            Some(false),
        )
        .is_ok());

        let matching = HashMap::from([
            ("query".to_string(), json!("find parser")),
            ("granularity".to_string(), json!("entity")),
            ("include_snippet".to_string(), json!(true)),
            ("snippet_alias".to_string(), json!(false)),
        ]);
        assert!(validate_cursor_projection(
            &matching,
            "find parser",
            false,
            kin_cli::commands::locate::projection_mode(true, true),
            Some(false),
        )
        .is_ok());

        for conflicting in [
            HashMap::from([("query".to_string(), json!("other query"))]),
            HashMap::from([("granularity".to_string(), json!("file"))]),
            HashMap::from([("include_snippet".to_string(), json!(false))]),
            HashMap::from([("snippet_alias".to_string(), json!(true))]),
        ] {
            assert!(
                validate_cursor_projection(
                    &conflicting,
                    "find parser",
                    false,
                    kin_cli::commands::locate::projection_mode(true, true),
                    Some(false),
                )
                .is_err(),
                "an explicit cursor-shape conflict must fail loud: {conflicting:?}"
            );
        }
    }

    /// The exact refusal each cursor-identity dimension owns.
    ///
    /// Asserting the MESSAGE rather than `is_err()` is the whole point of these
    /// tests. `cursor_projection_inherits_omissions_and_rejects_conflicts` and
    /// `fused_cursor_explanation_can_contract_but_cannot_expand` already prove
    /// that a conflict fails, but a validator that answered every conflict with
    /// one dimension's message would satisfy both of them: a mutation that
    /// merely redirects a refusal from one branch into another survives an
    /// `is_err()` assertion, because both branches still error. Naming the
    /// message per dimension is what makes the dimensions independently
    /// verifiable, which is what C4 asks for and what an `is_err()` cannot give.
    const CURSOR_REFUSAL_QUERY: &str =
        "semantic_locate cursor belongs to a different query; re-run the requested query";
    const CURSOR_REFUSAL_GRANULARITY: &str =
        "semantic_locate cursor preserves its original granularity; re-run the original query to change it";
    const CURSOR_REFUSAL_SNIPPET: &str =
        "semantic_locate cursor preserves its original snippet projection; re-run the original query to change it";
    const CURSOR_REFUSAL_ALIAS: &str =
        "semantic_locate cursor preserves its original snippet alias setting; re-run the original query to change it";
    const CURSOR_REFUSAL_VARIANTS: &str =
        "semantic_locate cursor preserves its original query variants; re-run the original query to change them";
    const CURSOR_REFUSAL_TEST_SCOPE: &str =
        "semantic_locate cursor preserves its original test-role scope; re-run the original query to change it";
    const CURSOR_REFUSAL_EXPLAIN: &str =
        "semantic_locate cursor cannot expand a ranking whose explanation was not built; re-run the original query with explain: true";

    /// Every refusal message a cursor validator can produce, so a test can
    /// require that the message it expected is the one that answered AND that no
    /// other dimension's message did. Without the second half, a redirected
    /// refusal reads exactly like the right one.
    fn assert_only_this_refusal(error: &str, expected: &str, dimension: &str) {
        assert_eq!(
            error, expected,
            "{dimension} must be refused by its own message"
        );
        for other in [
            CURSOR_REFUSAL_QUERY,
            CURSOR_REFUSAL_GRANULARITY,
            CURSOR_REFUSAL_SNIPPET,
            CURSOR_REFUSAL_ALIAS,
            CURSOR_REFUSAL_VARIANTS,
            CURSOR_REFUSAL_TEST_SCOPE,
            CURSOR_REFUSAL_EXPLAIN,
        ] {
            if other != expected {
                assert_ne!(
                    error, other,
                    "{dimension} must not be refused by another dimension's message"
                );
            }
        }
    }

    /// Query variants are their own cursor-identity dimension.
    ///
    /// No unit test reached this branch before: every existing call to
    /// `validate_fused_cursor_shape` passes an empty held variant list and sets
    /// no `queries` argument, so only the explanation branch was exercised.
    #[test]
    fn cursor_identity_binds_query_variants_independently() {
        let held = vec!["parse config".to_string(), "config loader".to_string()];

        // Control: an unchanged dimension reuses the held entry. Omitting the
        // field inherits, and repeating it exactly is not a conflict.
        assert!(
            validate_fused_cursor_shape(&HashMap::new(), &held, false, false).is_ok(),
            "an omitted variant list must inherit the held ranking"
        );
        let repeated = HashMap::from([(
            "queries".to_string(),
            json!(["parse config", "config loader"]),
        )]);
        assert!(
            validate_fused_cursor_shape(&repeated, &held, false, false).is_ok(),
            "repeating the held variant list exactly must reuse the held ranking"
        );

        // Only this dimension changes in each arm below.
        for (label, arguments) in [
            (
                "a reordered list",
                HashMap::from([(
                    "queries".to_string(),
                    json!(["config loader", "parse config"]),
                )]),
            ),
            (
                "a dropped variant",
                HashMap::from([("queries".to_string(), json!(["parse config"]))]),
            ),
            (
                "an added variant",
                HashMap::from([(
                    "queries".to_string(),
                    json!(["parse config", "config loader", "settings"]),
                )]),
            ),
            (
                "an explicitly emptied list",
                HashMap::from([("queries".to_string(), json!([]))]),
            ),
        ] {
            let error = validate_fused_cursor_shape(&arguments, &held, false, false)
                .expect_err(label)
                .to_string();
            assert_only_this_refusal(&error, CURSOR_REFUSAL_VARIANTS, label);
        }
    }

    /// Test-role scope is its own cursor-identity dimension. Also previously
    /// unreached at the unit level: no existing call sets `include_tests`.
    #[test]
    fn cursor_identity_binds_test_scope_independently() {
        // Control, in both directions, so the assertion cannot be satisfied by a
        // validator that simply refuses every explicit value.
        for held in [true, false] {
            assert!(
                validate_fused_cursor_shape(&HashMap::new(), &[], held, true).is_ok(),
                "an omitted test scope must inherit the held ranking"
            );
            let repeated = HashMap::from([("include_tests".to_string(), json!(held))]);
            assert!(
                validate_fused_cursor_shape(&repeated, &[], held, true).is_ok(),
                "repeating the held test scope must reuse the held ranking"
            );

            let flipped = HashMap::from([("include_tests".to_string(), json!(!held))]);
            let error = validate_fused_cursor_shape(&flipped, &[], held, true)
                .expect_err("a flipped test scope must be refused")
                .to_string();
            assert_only_this_refusal(&error, CURSOR_REFUSAL_TEST_SCOPE, "test scope");
        }
    }

    /// Explanation is one-directional identity: a page may shed held explanation
    /// but cannot expand a ranking that never built one. The existing test proves
    /// the direction; this one proves the refusal carries its own message and is
    /// not another dimension's refusal wearing the right shape.
    #[test]
    fn cursor_identity_binds_explanation_independently() {
        let expanding = HashMap::from([("explain".to_string(), json!(true))]);
        let error = validate_fused_cursor_shape(&expanding, &[], false, false)
            .expect_err("explain:true over a ranking with no explanation must be refused")
            .to_string();
        assert_only_this_refusal(&error, CURSOR_REFUSAL_EXPLAIN, "explanation");

        // Control: the same argument over a ranking that DID build explanation is
        // not a conflict, so the refusal above is about the held ranking rather
        // than about the argument being present.
        assert!(
            validate_fused_cursor_shape(&expanding, &[], false, true).is_ok(),
            "a held explanation must still serve an explaining continuation"
        );

        // `compact` reaches identity only through this branch: it decides whether
        // the page requests explanation, and owns no refusal of its own. A
        // continuation may flip it freely over a ranking that built explanation.
        let compact_off = HashMap::from([("compact".to_string(), json!(false))]);
        assert!(
            fused_explanation_requested(&compact_off),
            "compact:false is an effective request for explanation"
        );
        let error = validate_fused_cursor_shape(&compact_off, &[], false, false)
            .expect_err("compact:false cannot expand a ranking with no explanation")
            .to_string();
        assert_only_this_refusal(&error, CURSOR_REFUSAL_EXPLAIN, "compact as explanation");
        for compact in [true, false] {
            assert!(
                validate_fused_cursor_shape(
                    &HashMap::from([("compact".to_string(), json!(compact))]),
                    &[],
                    false,
                    true,
                )
                .is_ok(),
                "compact is per-page presentation over a ranking that built explanation"
            );
        }
    }

    /// Each projection dimension owns its own refusal.
    ///
    /// The existing projection test perturbs the same four dimensions but asserts
    /// only `is_err()`, so a validator that answered all four with one message
    /// would pass it. These arms name the message per dimension, and each control
    /// proves the matching value is accepted rather than refused for some other
    /// reason.
    #[test]
    fn cursor_identity_binds_each_projection_dimension_independently() {
        let held_query = "find parser";
        let held_mode = kin_cli::commands::locate::projection_mode(true, true);

        // Control: every dimension repeated at its held value reuses the entry.
        let matching = HashMap::from([
            ("query".to_string(), json!(held_query)),
            ("granularity".to_string(), json!("entity")),
            ("include_snippet".to_string(), json!(true)),
            ("snippet_alias".to_string(), json!(false)),
        ]);
        assert!(
            validate_cursor_projection(&matching, held_query, false, held_mode, Some(false))
                .is_ok(),
            "every dimension at its held value must reuse the held ranking"
        );

        for (dimension, expected, arguments) in [
            (
                "query",
                CURSOR_REFUSAL_QUERY,
                HashMap::from([("query".to_string(), json!("some other query"))]),
            ),
            (
                "granularity",
                CURSOR_REFUSAL_GRANULARITY,
                HashMap::from([("granularity".to_string(), json!("file"))]),
            ),
            (
                "snippet projection",
                CURSOR_REFUSAL_SNIPPET,
                HashMap::from([("include_snippet".to_string(), json!(false))]),
            ),
            (
                "snippet alias",
                CURSOR_REFUSAL_ALIAS,
                HashMap::from([("snippet_alias".to_string(), json!(true))]),
            ),
        ] {
            let error =
                validate_cursor_projection(&arguments, held_query, false, held_mode, Some(false))
                    .expect_err(dimension)
                    .to_string();
            assert_only_this_refusal(&error, expected, dimension);
        }

        // An invalid granularity is a different refusal from a conflicting one,
        // and folding the two together would let a typo read as a cursor
        // conflict and send a caller to re-run a query that was never the problem.
        let invalid = HashMap::from([("granularity".to_string(), json!("entities"))]);
        let error = validate_cursor_projection(&invalid, held_query, false, held_mode, Some(false))
            .expect_err("an unknown granularity must be refused")
            .to_string();
        assert!(
            error.contains("invalid granularity 'entities'"),
            "an unknown granularity must name itself, not the cursor: {error}"
        );
        assert_ne!(
            error, CURSOR_REFUSAL_GRANULARITY,
            "a malformed value and a conflicting value are different news"
        );
    }

    /// One cosine-arm ranked row, in the shape the serving loop builds.
    fn cosine_row(
        name: &str,
        file: Option<&str>,
        score: f32,
        span: Option<(u32, u32)>,
    ) -> serde_json::Value {
        let mut row = json!({
            "kind": "function",
            "name": name,
            "score": score,
            "provenance": { "file": file },
        });
        if file.is_some() {
            row["entity_id"] = json!("00000000-0000-0000-0000-0000000000aa");
        }
        if let Some((start, end)) = span {
            row["start_line"] = json!(start);
            row["end_line"] = json!(end);
        }
        row
    }

    /// Render a cosine-arm page the way the serving path does, so these assert
    /// against the real serializer rather than a hand-written payload.
    fn cosine_locate_body(
        rows: &[serde_json::Value],
        page: usize,
        page_size: usize,
    ) -> serde_json::Value {
        let coverage = kin_cli::commands::locate::SemanticCoverage {
            supported: true,
            indexed: 10,
            total: 10,
            pending: 0,
            complete: true,
            embedding_state: kin_cli::commands::locate::EmbeddingState::Present,
            limited_by: Vec::new(),
            read_at: None,
            note: None,
            graph_bodies: None,
        };
        let tool = semantic_locate_payload(
            "where does the daemon start",
            false,
            &coverage,
            "cursor-key",
            page,
            page.saturating_mul(page_size),
            page_size,
            rows,
            &[],
        );
        serde_json::from_str(
            tool_result_json(&tool)["content"][0]["text"]
                .as_str()
                .unwrap(),
        )
        .unwrap()
    }

    #[test]
    fn the_cosine_arm_rolls_its_ranking_up_into_the_shared_file_surface() {
        let rows = vec![
            cosine_row("start_daemon", Some("src/daemon.rs"), 0.9, Some((10, 20))),
            cosine_row("serve", Some("src/api.rs"), 0.7, Some((5, 9))),
            // A second, weaker hit in an already-seen file: it must fold into
            // that file rather than opening a duplicate entry.
            cosine_row("stop_daemon", Some("src/daemon.rs"), 0.4, Some((30, 40))),
        ];
        let files = cosine_file_surface(&rows);

        // Files rank by their best hit, and `rows` is rank-ordered, so the first
        // occurrence of a path both places and scores it.
        let paths: Vec<&str> = files.iter().map(|file| file.path.as_str()).collect();
        assert_eq!(paths, vec!["src/daemon.rs", "src/api.rs"]);
        assert_eq!(files[0].score, 0.9);
        assert_eq!(files[1].score, 0.7);

        // Every contributing row keeps its symbol under the file, in rank order,
        // so the rollup adds a view and drops nothing from the ranking.
        let symbols: Vec<&str> = files[0]
            .symbols
            .iter()
            .map(|symbol| symbol.name.as_str())
            .collect();
        assert_eq!(symbols, vec!["start_daemon", "stop_daemon"]);
        assert_eq!(files[0].spans, vec![[10, 20], [30, 40]]);
        assert_eq!(files[0].signals, vec!["embeddings".to_string()]);
        // Explain-only fields on the fused arm stay unset here, so the two arms'
        // plain file surfaces carry the same field set.
        assert!(files[0].symbols[0].origin.is_empty());
        assert!(files[0].symbols[0].cosine.is_none());

        // A pathless hit contributes no file rather than a placeholder path no
        // caller could open, and does not disturb the files around it.
        let pathless = vec![
            cosine_row("orphan", None, 0.8, None),
            cosine_row("serve", Some("src/api.rs"), 0.7, None),
        ];
        let files = cosine_file_surface(&pathless);
        assert_eq!(files.len(), 1);
        assert_eq!(files[0].path, "src/api.rs");

        // An empty ranking rolls up to an empty surface, never to a panic.
        assert!(cosine_file_surface(&[]).is_empty());
    }

    /// At entity granularity `files[]` is the query-wide provenance summary, so
    /// it remains stable while the primary `results[]` ranking pages.
    #[test]
    fn the_cosine_entity_surface_keeps_a_query_wide_file_summary() {
        let rows = vec![
            cosine_row("start_daemon", Some("src/daemon.rs"), 0.9, None),
            cosine_row("serve", Some("src/api.rs"), 0.7, None),
            cosine_row("route", Some("src/router.rs"), 0.5, None),
        ];

        // One row per page: the window holds a single file, the ranking holds
        // three, and the surface reports the ranking.
        let body = cosine_locate_body(&rows, 0, 1);
        assert_eq!(body["results"].as_array().unwrap().len(), 1);
        assert_eq!(body["total_ranked"], json!(3));
        let paths: Vec<&str> = body["files"]
            .as_array()
            .unwrap()
            .iter()
            .map(|file| file["path"].as_str().unwrap())
            .collect();
        assert_eq!(paths, vec!["src/daemon.rs", "src/api.rs", "src/router.rs"]);

        // And it is page-invariant: paging forward re-states the same answer
        // rather than reporting the files of whichever window was served.
        let page_two = cosine_locate_body(&rows, 2, 1);
        assert_eq!(page_two["results"].as_array().unwrap().len(), 1);
        assert_eq!(page_two["files"], body["files"]);

        // Serialized unconditionally, so an empty ranking says `[]` rather than
        // omitting the key and making absence read like emptiness. This matches
        // the fused arm, whose `files` is always serialized.
        let empty = cosine_locate_body(&[], 0, 20);
        assert_eq!(empty["files"], json!([]));
    }

    #[test]
    fn cosine_file_granularity_pages_files_without_results_repeats_or_gaps() {
        let rows = vec![
            cosine_row("start_daemon", Some("src/daemon.rs"), 0.9, None),
            cosine_row("serve", Some("src/api.rs"), 0.7, None),
            cosine_row("route", Some("src/router.rs"), 0.5, None),
        ];
        let coverage = kin_cli::commands::locate::SemanticCoverage {
            supported: true,
            indexed: 3,
            total: 3,
            pending: 0,
            complete: true,
            embedding_state: kin_cli::commands::locate::EmbeddingState::Present,
            limited_by: Vec::new(),
            read_at: None,
            note: None,
            graph_bodies: None,
        };
        let body = |page: usize, start: usize, width: usize| {
            let tool = semantic_locate_payload(
                "where does the daemon start",
                true,
                &coverage,
                "file-ranking",
                page,
                start,
                width,
                &rows,
                &[],
            );
            serde_json::from_str::<serde_json::Value>(
                tool_result_json(&tool)["content"][0]["text"]
                    .as_str()
                    .unwrap(),
            )
            .unwrap()
        };

        let first = body(0, 0, 2);
        assert!(
            first.get("results").is_none(),
            "file mode has one primary: {first}"
        );
        assert_eq!(first["total_ranked"], 3);
        assert_eq!(
            first["files"]
                .as_array()
                .unwrap()
                .iter()
                .map(|file| file["path"].as_str().unwrap())
                .collect::<Vec<_>>(),
            vec!["src/daemon.rs", "src/api.rs"]
        );
        let cursor = kin_core::LocateCursor::decode(first["next_cursor"].as_str().unwrap())
            .expect("a followable file cursor");
        assert_eq!(cursor.next_offset, Some(2));

        // Width changes only the number emitted from the absolute offset.
        let second = body(1, cursor.next_offset.unwrap(), 1);
        assert_eq!(
            second["files"][0]["path"], "src/router.rs",
            "the continuation covers the next file without overlap or a gap"
        );
        assert!(second["next_cursor"].is_null());
    }

    /// The cosine `files[]` is a rollup of `results`, so every file it names is
    /// already counted as a row. The negative envelope must therefore keep
    /// counting `results` alone on this arm: adding `files` into the total the
    /// way the fused branch does would double-count the same hits and could talk
    /// a genuinely empty page out of being qualified. The fused branch counts
    /// both because its two surfaces are independently ranked; this one's are
    /// not, and the shapes now look similar enough that a later tidy-up could
    /// merge the branches without noticing.
    #[test]
    fn the_cosine_file_surface_does_not_change_what_the_negative_envelope_counts() {
        let rows = vec![
            cosine_row("start_daemon", Some("src/daemon.rs"), 0.9, None),
            cosine_row("stop_daemon", Some("src/daemon.rs"), 0.4, None),
        ];
        let body = cosine_locate_body(&rows, 0, 20);
        assert_eq!(body["routing"], json!("cosine-v0"));
        // Two rows rolling up into one file: if the count ever became files +
        // results it would read 3, and if it became files alone it would read 1.
        assert_eq!(body["files"].as_array().unwrap().len(), 1);
        assert_eq!(body["results"].as_array().unwrap().len(), 2);

        // An empty cosine page still carries `files: []` and must still be
        // qualified as an absence, which is the case a files-aware count would
        // have broken first.
        let empty = cosine_locate_body(&[], 0, 20);
        let negative = kin_mcp::negative::negative_for(
            "semantic_locate",
            &empty,
            &kin_mcp::Envelope::daemon(),
            &[],
        )
        .expect("an empty cosine page must carry a negative");
        assert_eq!(negative["kind"], json!("no_ranked_match"));
        assert_eq!(negative["result_count"], json!(0));
    }

    /// The cosine arm used to omit the guidance entirely. It now follows the
    /// same whole-ranking `all_fallback` fact as the fused arm, and a name hit
    /// remains the control that clears both fields.
    #[test]
    fn cosine_description_rankings_carry_file_granularity_guidance() {
        let mut semantic = cosine_row("serve_request", Some("src/api.rs"), 0.83, None);
        semantic["match_kind"] = json!("semantic");
        let advised = cosine_locate_body(&[semantic], 0, 20);
        assert_eq!(advised["all_fallback"], json!(true));
        let guidance = advised["degradations"]
            .as_array()
            .and_then(|items| {
                items.iter().find(|item| {
                    item["component"] == kin_mcp::negative::QUERY_SHAPE_COMPONENT
                        && item["reason"] == kin_mcp::negative::DESCRIPTION_ENTITY_RANKING_REASON
                })
            })
            .expect("the cosine arm must publish description-ranking guidance");
        assert!(
            guidance["remediation"]
                .as_str()
                .unwrap_or_default()
                .contains("granularity: \"file\""),
            "the response names the file-level fallback that remained useful: {guidance}"
        );

        let mut named = cosine_row("start_daemon", Some("src/daemon.rs"), 0.81, None);
        named["match_kind"] = json!("name");
        let control = cosine_locate_body(&[named], 0, 20);
        assert!(control.get("all_fallback").is_none(), "{control}");
        assert!(
            control
                .get("degradations")
                .and_then(serde_json::Value::as_array)
                .is_none_or(|items| items.iter().all(|item| {
                    item["reason"] != kin_mcp::negative::DESCRIPTION_ENTITY_RANKING_REASON
                })),
            "a ranking with a name hit does not need description-only guidance: {control}"
        );
    }

    #[test]
    fn cosine_match_evidence_is_deterministic_and_gates_rerank_signals() {
        use kin_model::EntityRole;
        // Re-rank OFF (the shipped default): stable base fields, role echoed, and
        // NO rerank_signals object (the boost/demotion did not affect ordering).
        let off = cosine_match_evidence(
            "find Detector",
            "Detector",
            Some(EntityRole::Source),
            false,
            false,
        );
        assert_eq!(off["ranker"], json!("cosine-v0"));
        assert_eq!(off["score_source"], json!("vector_cosine"));
        assert_eq!(off["name_match"], json!("exact"));
        assert_eq!(off["role"], json!("source"));
        assert_eq!(off["reranked"], json!(false));
        assert!(off.get("rerank_signals").is_none());

        // Re-rank ON: signals present. A Test-role hit on a non-test query is
        // demoted, and an exact-name match records the boost that fired.
        let on = cosine_match_evidence(
            "find Detector",
            "Detector",
            Some(EntityRole::Test),
            true,
            false,
        );
        assert_eq!(on["reranked"], json!(true));
        assert_eq!(on["rerank_signals"]["role_demoted"], json!(true));
        assert_eq!(on["rerank_signals"]["exact_name_boost"], json!(true));

        // A test-related query must NOT demote a Test-role hit.
        let test_q = cosine_match_evidence(
            "test Detector",
            "Detector",
            Some(EntityRole::Test),
            true,
            true,
        );
        assert_eq!(test_q["rerank_signals"]["role_demoted"], json!(false));

        // A non-entity hit (no role) omits the role field but is still well-formed.
        let no_role = cosine_match_evidence("find Detector", "Detector", None, false, false);
        assert!(no_role.get("role").is_none());
        assert_eq!(no_role["ranker"], json!("cosine-v0"));

        // Deterministic across repeated calls.
        for _ in 0..50 {
            assert_eq!(
                cosine_match_evidence(
                    "find Detector",
                    "Detector",
                    Some(EntityRole::Source),
                    false,
                    false
                ),
                off
            );
        }
    }

    #[test]
    fn fused_match_evidence_derives_from_locate_entity() {
        use kin_cli::commands::locate::{LocateEntity, LocateProvenance};
        let with_explain = LocateEntity {
            entity_id: "e1".into(),
            id_space: kin_cli::commands::locate::LocateIdSpace::Entity,
            artifact_path: None,
            kind: "function".into(),
            name: "parse_request".into(),
            signature: String::new(),
            score: 0.9,
            definition: true,
            span: None,
            body: None,
            match_kind: None,
            provenance: LocateProvenance {
                file: Some("src/lib.rs".into()),
                origin: "vector".into(),
                cosine: Some(0.42),
            },
            matched_queries: Vec::new(),
        };
        let ev = fused_match_evidence("parse the request", &with_explain);
        assert_eq!(ev["ranker"], json!("fused-v1"));
        assert_eq!(ev["score_source"], json!("fused_composite"));
        assert_eq!(ev["name_match"], json!("partial"));
        assert_eq!(ev["definition"], json!(true));
        assert_eq!(ev["resolution_origin"], json!("vector"));
        let seed = ev["seed_cosine"].as_f64().expect("seed_cosine is a number");
        assert!((seed - 0.42).abs() < 1e-6, "seed_cosine ~ 0.42, got {seed}");

        // Without --explain provenance, origin/cosine are omitted (additive-only).
        let plain = LocateEntity {
            provenance: LocateProvenance {
                file: Some("src/lib.rs".into()),
                origin: String::new(),
                cosine: None,
            },
            ..with_explain
        };
        let ev2 = fused_match_evidence("parse the request", &plain);
        assert!(ev2.get("resolution_origin").is_none());
        assert!(ev2.get("seed_cosine").is_none());
        assert_eq!(ev2["definition"], json!(true));

        // Fusion promotes match_kind from the strongest contributing variant.
        // Evidence must inspect that same set or the row can say `name` beside
        // `name_match: none` when only a secondary variant named the entity.
        let secondary_name = LocateEntity {
            match_kind: Some(kin_cli::commands::locate::LocateMatchKind::Name),
            matched_queries: vec![
                "where is request handling implemented".to_string(),
                "parse_request".to_string(),
            ],
            ..plain
        };
        let ev3 = fused_match_evidence("where is request handling implemented", &secondary_name);
        assert_eq!(ev3["name_match"], json!("exact"));
    }

    #[test]
    fn with_auto_sharp_variant_appends_identifier_query_for_single_variant() {
        let (out, auto) = with_auto_sharp_variant(vec![
            "The ScanResult keeps RemoveRaspbianPackFromResult stale entries".to_string(),
        ]);
        assert_eq!(out.len(), 2, "sharp variant must append: {out:?}");
        assert!(auto, "auto flag must mark the appended variant");
        assert!(out[1].contains("RemoveRaspbianPackFromResult"));
        assert!(out[1].contains("ScanResult"));
    }

    #[test]
    fn with_auto_sharp_variant_is_a_no_op_without_identifiers_or_with_explicit_queries() {
        let (prose, prose_auto) =
            with_auto_sharp_variant(vec!["please fix the broken behavior".to_string()]);
        assert_eq!(prose.len(), 1, "no identifiers means no fan-out: {prose:?}");
        assert!(!prose_auto);
        let (explicit, explicit_auto) = with_auto_sharp_variant(vec![
            "primary RemoveRaspbianPackFromResult".to_string(),
            "user variant".to_string(),
        ]);
        assert!(!explicit_auto, "explicit variants never gate on confidence");
        assert_eq!(
            explicit.len(),
            2,
            "caller-supplied variants are never modified"
        );
    }

    #[test]
    fn build_locate_variants_dedups_and_keeps_primary_first() {
        // Primary first, blanks dropped, exact duplicates collapsed, order stable.
        let variants = build_locate_variants(
            "primary query",
            &[
                "  ".to_string(),
                "variant two".to_string(),
                "primary query".to_string(),
                "variant three".to_string(),
                "variant two".to_string(),
            ],
        );
        assert_eq!(
            variants,
            vec![
                "primary query".to_string(),
                "variant two".to_string(),
                "variant three".to_string(),
            ]
        );
        // An empty primary with variants yields a variant-only list.
        assert_eq!(
            build_locate_variants("", &["only".to_string()]),
            vec!["only".to_string()]
        );
        // No variants → the single primary; a single entry means no fan-out.
        assert_eq!(build_locate_variants("solo", &[]), vec!["solo".to_string()]);
    }

    #[test]
    fn semantic_locate_argument_types_reject_invalid_query_arrays_before_reading() {
        let mut args: HashMap<String, serde_json::Value> = HashMap::new();
        args.insert(
            "queries".to_string(),
            json!(["alpha", 7, "beta", null, "gamma"]),
        );
        assert!(validate_semantic_locate_argument_types(&args)
            .unwrap_err()
            .contains("every item"));

        // Absence is the only shape that means no additional query variants.
        args.remove("queries");
        assert!(validate_semantic_locate_argument_types(&args).is_ok());
        assert!(arg_string_array(&args, "missing").is_empty());

        args.insert("queries".to_string(), json!("not-an-array"));
        assert!(validate_semantic_locate_argument_types(&args)
            .unwrap_err()
            .contains("array of strings"));

        for key in ["limit", "page_size"] {
            args.clear();
            args.insert(key.to_string(), json!(0));
            let error = validate_semantic_locate_argument_types(&args).unwrap_err();
            assert!(
                error.contains(key) && error.contains("positive integer"),
                "an explicit zero cannot silently select the default: {error}"
            );
        }
    }

    #[test]
    fn a_hit_indexes_the_response_variant_list_instead_of_copying_it() {
        use kin_cli::commands::locate::{LocateEntity, LocateProvenance};
        let mut entity = LocateEntity {
            entity_id: "e1".into(),
            id_space: kin_cli::commands::locate::LocateIdSpace::Entity,
            artifact_path: None,
            kind: "function".into(),
            name: "parse_request".into(),
            signature: String::new(),
            score: 0.9,
            definition: true,
            span: None,
            body: None,
            match_kind: None,
            provenance: LocateProvenance {
                file: Some("src/lib.rs".into()),
                origin: String::new(),
                cosine: None,
            },
            matched_queries: Vec::new(),
        };
        let variants = vec![
            "q".to_string(),
            "ParseRequest".to_string(),
            "parse the request".to_string(),
        ];

        // No attribution → no attribution key (single-query byte-identical).
        let mut slot = json!({ "entity_id": "e1" });
        write_locate_variant_indexes(&mut slot, &entity.matched_queries, &variants);
        assert!(slot.get("matched_variant_indexes").is_none(), "{slot}");

        // With attribution → POSITIONS in the response's own variant list, and
        // the hit's own copy of the text is gone. FIR-2415: the text copies were
        // the cost, so a hit that serializes a variant string has regressed.
        entity.matched_queries = vec!["ParseRequest".into(), "parse the request".into()];
        let mut slot = json!({
            "entity_id": "e1",
            "matched_queries": entity.matched_queries.clone(),
        });
        write_locate_variant_indexes(&mut slot, &entity.matched_queries, &variants);
        assert_eq!(slot["matched_variant_indexes"], json!([1, 2]));
        assert!(
            slot.get("matched_queries").is_none(),
            "the variant text must be carried once per response, not once per hit: {slot}"
        );
        let serialized = serde_json::to_string(&slot).expect("hit serializes");
        assert!(
            !serialized.contains("parse the request"),
            "no hit may serialize a variant string: {serialized}"
        );

        // The evidence object carries no attribution of its own any more, so the
        // two copies cannot come back one at a time.
        let evidence = fused_match_evidence("q", &entity);
        assert!(
            evidence.get("matched_variants").is_none()
                && evidence.get("matched_variant_indexes").is_none(),
            "attribution belongs to the hit, not to a second object on it: {evidence}"
        );
    }

    /// A fixture standing in for one ranked page: the shape the compact tests
    /// below measure against.
    fn compact_surface_fixture(hits: usize) -> kin_cli::commands::locate::LocateResult {
        use kin_cli::commands::locate::{
            EmbeddingState, LocateEntity, LocateFileEntry, LocateProvenance, LocateResult,
            LocateSymbol, SemanticCoverage,
        };
        let symbol = |index: usize| LocateSymbol {
            name: format!("redisAsyncHandleWrite{index}"),
            span: Some([256, 301]),
            score: 570.908_43,
            kind: "function".into(),
            definition: true,
            origin: "text".into(),
            cosine: None,
            snippet: Some("static int redisAsyncHandleWrite(...) { /* body */ }".into()),
        };
        LocateResult {
            entities: (0..hits)
                .map(|index| LocateEntity {
                    entity_id: format!("11111111-2222-3333-4444-5555555555{index:02}"),
                    id_space: kin_cli::commands::locate::LocateIdSpace::Entity,
                    artifact_path: None,
                    kind: "function".into(),
                    name: format!("redisAsyncHandleWrite{index}"),
                    signature: format!(
                        "static int redisAsyncHandleWrite{index}(redisAsyncContext *ac, int flags)"
                    ),
                    score: 570.908_43,
                    definition: true,
                    span: Some([256, 301]),
                    body: Some(
                        "static int redisAsyncHandleWrite(redisAsyncContext *ac) {\n    \
                         /* several lines of body that the compact surface drops */\n}"
                            .into(),
                    ),
                    match_kind: Some(kin_cli::commands::locate::LocateMatchKind::TextFallback),
                    provenance: LocateProvenance {
                        file: Some("async.c".into()),
                        origin: "text".into(),
                        cosine: None,
                    },
                    matched_queries: Vec::new(),
                })
                .collect(),
            files: (0..hits)
                .map(|index| LocateFileEntry {
                    path: format!("src/async{index}.c"),
                    score: 12.5,
                    signals: vec!["text".into()],
                    spans: vec![[1, 40]],
                    // The block this whole change is about: 69 percent of a real
                    // payload.
                    symbols: (0..6).map(symbol).collect(),
                    explain: vec!["a per-file explain line".into()],
                    provenance: None,
                    signal_scores: None,
                    score_breakdown: None,
                    matched_queries: Vec::new(),
                })
                .collect(),
            total_ranked: 41,
            semantic_coverage: Some(SemanticCoverage {
                supported: true,
                indexed: 0,
                total: 1460,
                pending: 1460,
                complete: false,
                embedding_state: EmbeddingState::Absent,
                limited_by: vec!["embeddings_incomplete".into()],
                read_at: None,
                note: Some("semantic signal absent".into()),
                graph_bodies: None,
            }),
            ..Default::default()
        }
    }

