    /// The direct server API is the bypass the invoking shell cannot close.
    /// A hosted daemon built without a usable durable spine must leave the GCS
    /// rollout active and refuse both admission and direct ingest. A test-only
    /// local backend must never make the production control route look green.
    /// The composed rollout path, driven end to end against a durable fake.
    ///
    /// This is the positive half the suite did not have. Every other test of
    /// this surface asserts a refusal, and a refusal passes on a daemon that
    /// refuses everything, so without this the routes could stop working
    /// entirely and nothing would say so.
    ///
    /// It drives the real sequence: acquire derives the Firestore fleet fence
    /// from server-owned lease state, advances it, checkpoints the returned
    /// evidence back into the GCS lease and completes the acquisition; admit
    /// publishes the exact five heads and binds the reader; release clears the
    /// rollout. The spine underneath is kin-spine's own durable fake behind
    /// `FirestoreSpineBackend`, so the CAS semantics exercised here are the
    /// same ones that crate's suite exercises, not a second implementation.
    ///
    /// Hosted readiness is left exactly as production has it. The older
    /// in-memory seam also switches readiness off, and every control-plane
    /// route then refuses before it starts, which is why this test could not
    /// have been written on that seam.
    #[tokio::test]
    #[serial_test::serial]
    async fn publication_control_api_drives_the_rollout_to_release() {
        const READER_A: &str =
            "sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
        const READER_B: &str =
            "sha256:bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";
        let fleet = vec![
            "kin".to_string(),
            "kin-db".to_string(),
            "kin-editor".to_string(),
            "kin-vfs".to_string(),
            "kinlab".to_string(),
        ];

        let mut environment = kin_core::test_env::EnvVarGuard::new();
        environment.apply("GOOGLE_CLOUD_PROJECT", Some("fixture-project"));
        environment.apply("KIN_GCS_BUCKET", Some("fixture-bucket"));
        environment.apply("KIN_GCS_PREFIX", Some("fixture-prefix"));
        environment.apply("KIN_REPO_IDS", Some(&fleet.join(",")));
        environment.apply::<_, &str>("KIN_DISABLE_SPINE", None);
        let scope = "gcs://fixture-bucket/fixture-prefix";

        // Every repository in the exact fleet needs a graph, because admit
        // publishes all five heads and then proves the exact set.
        let backend_root = tempfile::tempdir().unwrap();
        for repo_id in &fleet {
            let graph = kin_db::InMemoryGraph::new();
            graph
                .upsert_entity(&test_entity(
                    &format!("{}_entity", repo_id.replace('-', "_")),
                    "src/lib.rs",
                ))
                .unwrap();
            kin_db::StorageBackend::save_snapshot(
                &kin_db::LocalFileBackend::new(backend_root.path()),
                repo_id,
                &graph.to_snapshot().to_bytes().unwrap(),
                kin_db::GENERATION_INIT,
            )
            .unwrap();
        }

        let repo = tempfile::tempdir().unwrap();
        let initialized = kin_core::init(repo.path()).unwrap();
        let store = Arc::new(crate::publication_lease::InMemoryPublicationControlStore::default());
        let control = Arc::new(
            crate::publication_lease::PublicationControl::new(
                scope,
                READER_A,
                fleet.clone(),
                store,
            )
            .unwrap(),
        );
        let state = Arc::new(
            DaemonState::open_with_backend_and_publication_control(
                initialized.layout,
                Box::new(kin_db::LocalFileBackend::new(backend_root.path())),
                "kin",
                Some(fleet.iter().cloned().collect()),
                control,
            )
            .unwrap(),
        );
        state.install_hosted_durable_spine_for_test(Arc::new(
            kin_spine::FirestoreSpineBackend::with_store(Arc::new(
                kin_spine::test_support::FakeSpineStore::cold(),
            )),
        ));
        assert!(
            state.hosted_spine_readiness_required(),
            "this test is only about the composed path if hosted readiness is on, which the \
             older in-memory seam turns off"
        );

        let app = router_with_publication_control_auth(
            Arc::clone(&state),
            Some("daemon-test-token".to_string()),
            Some("publication-test-token".to_string()),
        );

        let (status, lease) = publication_post(
            app.clone(),
            "/authority/publication-control/rollout/acquire",
            serde_json::json!({
                "scope": scope,
                "repositories": fleet,
                "holder": "positive-regression",
                "request_id": "run-positive-1",
                "ttl_seconds": 300,
                "bootstrap_reader": {
                    "identity": READER_A,
                    "min_snapshot_schema": kin_db::GraphSnapshot::MIN_SUPPORTED_VERSION,
                    "max_snapshot_schema": kin_db::GraphSnapshot::CURRENT_VERSION,
                    "valid_for_seconds": 3600
                }
            }),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "acquire must succeed: {lease}");
        let token = lease["token"]
            .as_str()
            .unwrap_or_else(|| panic!("acquire must return a lease token: {lease}"))
            .to_string();
        let fence = lease["fence"]
            .as_u64()
            .unwrap_or_else(|| panic!("acquire must return a lease fence: {lease}"));

        // LeaseProof is serde(flatten) on both request types, so scope, token
        // and fence sit at the top level rather than under a "lease" key.
        let (status, admitted) = publication_post(
            app.clone(),
            "/authority/publication-control/rollout/admit-reader",
            serde_json::json!({
                "scope": scope,
                "token": token,
                "fence": fence,
                "repositories": fleet,
                "reader": {
                    "identity": READER_A,
                    "min_snapshot_schema": kin_db::GraphSnapshot::MIN_SUPPORTED_VERSION,
                    "max_snapshot_schema": kin_db::GraphSnapshot::CURRENT_VERSION,
                    "valid_for_seconds": 3600
                },
                // Without this the seal is never created and hosted reads stay
                // closed behind the legacy writer-drain boundary, which is the
                // fail-closed behaviour the negative fixture already covers.
                // Supplying it is what the daemon binary does from
                // KIN_SPINE_LEGACY_DRAIN_PROOF_SHA256_INTERNAL, so the sequence
                // under test is the deployed one.
                "legacy_writer_drain_proof_sha256": format!("sha256:{}", "b".repeat(64))
            }),
        )
        .await;
        assert_eq!(
            status,
            StatusCode::OK,
            "admit must publish the exact fleet, seal the legacy boundary and bind the \
             reader: {admitted}"
        );

        let (status, released) = publication_post(
            app.clone(),
            "/authority/publication-control/rollout/release",
            serde_json::json!({ "scope": scope, "token": token, "fence": fence }),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "release must succeed: {released}");

        // The point of the whole sequence: a reader is admitted afterwards and
        // semantic readiness is open. Asserting only the three 200s would pass
        // on routes that returned 200 and changed nothing.
        let readiness = app
            .clone()
            .oneshot(Request::get("/readiness").body(Body::empty()).unwrap())
            .await
            .unwrap();
        assert_eq!(
            readiness.status(),
            StatusCode::OK,
            "the daemon must be reader-ready once the rollout has released"
        );

        // The promotion's own call, in the state production is actually in when
        // it runs: settled, ready, no lease anywhere. It presents no proof
        // because there is none to present.
        let (status, authorized) = publication_post(
            app.clone(),
            "/authority/publication-control/rollout/authorize-next-reader",
            serde_json::json!({ "scope": scope, "identity": READER_B }),
        )
        .await;
        assert_eq!(
            status,
            StatusCode::OK,
            "the promotion must name its successor with no lease at all: {authorized}"
        );
        assert_eq!(
            authorized["next_reader_identity"].as_str(),
            Some(READER_B),
            "{authorized}"
        );
        assert!(
            authorized["active_lease"].is_null(),
            "naming the successor must take no lease: {authorized}"
        );

        // And it costs the running daemon nothing. This is the property that
        // paid for dropping the lease: readiness is open on the same daemon
        // immediately after the call, so a promotion opens no gap at all.
        let readiness = app
            .clone()
            .oneshot(Request::get("/readiness").body(Body::empty()).unwrap())
            .await
            .unwrap();
        assert_eq!(
            readiness.status(),
            StatusCode::OK,
            "naming a successor must not close the running daemon's readiness"
        );

        let control_status = app
            .clone()
            .oneshot(
                Request::get("/authority/publication-control")
                    .header("authorization", "Bearer publication-test-token")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(control_status.status(), StatusCode::OK);
        let status_body = axum::body::to_bytes(control_status.into_body(), 256 * 1024)
            .await
            .unwrap();
        let status_text = String::from_utf8(status_body.to_vec()).unwrap();
        let status_json: serde_json::Value = serde_json::from_slice(&status_body).unwrap();
        assert_eq!(
            status_json["next_reader_identity"].as_str(),
            Some(READER_B),
            "the successor starts long after this call, so the record has to carry it: {status_json}"
        );
        assert!(
            !status_text.contains("\"token\""),
            "read-only publication status must not disclose live lease capability: {status_text}"
        );
    }

    /// The route sits on the administrator surface, not the daemon one. It is
    /// the only publication-control route a caller reaches while holding no
    /// lease, so nothing else stands between an ordinary daemon credential and
    /// a write that decides which image opens readiness on the whole fleet.
    #[tokio::test]
    async fn authorizing_the_next_reader_demands_the_administrator_token() {
        const READER_B: &str =
            "sha256:bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";
        let app = router_with_publication_control_auth(
            test_state(),
            Some("daemon-test-token".to_string()),
            Some("publication-test-token".to_string()),
        );
        let authorize = |app: Router, token: Option<&'static str>| async move {
            let mut request =
                Request::post("/authority/publication-control/rollout/authorize-next-reader")
                    .header("content-type", "application/json");
            if let Some(token) = token {
                request = request.header("authorization", format!("Bearer {token}"));
            }
            app.oneshot(
                request
                    .body(Body::from(
                        serde_json::to_vec(&serde_json::json!({
                            "scope": "gcs://fixture/v2",
                            "identity": READER_B
                        }))
                        .unwrap(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap()
            .status()
        };

        // An ordinary daemon token is authenticated and unauthorized here, so
        // 403 rather than 401: telling a caller holding a live credential that
        // it holds none sends it to rotate a working token.
        assert_eq!(
            authorize(app.clone(), Some("daemon-test-token")).await,
            StatusCode::FORBIDDEN
        );
        assert_eq!(
            authorize(app.clone(), Some("not-a-token")).await,
            StatusCode::UNAUTHORIZED
        );
        assert_eq!(authorize(app.clone(), None).await, StatusCode::UNAUTHORIZED);

        // The control the refusals need: the administrator token passes the
        // guard. Without it every assertion above would also hold on a route
        // that refuses everyone, including the caller it exists for.
        let admin = authorize(app, Some("publication-test-token")).await;
        assert!(
            admin != StatusCode::UNAUTHORIZED && admin != StatusCode::FORBIDDEN,
            "the administrator token must pass the auth guard, got {admin}"
        );
    }

    ///
    /// The absence this asserts has to be established, not assumed. Other tests
    /// in this library set `GOOGLE_CLOUD_PROJECT` and its companions, and the
    /// process environment is shared, so under a plain parallel `cargo test`
    /// this fixture could otherwise enter a different or real Firestore path
    /// and still read green. The guard clears them and `serial` keeps a
    /// concurrent test from setting them back mid-run.
    #[tokio::test]
    #[serial_test::serial]
    async fn publication_control_api_fails_closed_without_durable_spine() {
        const READER_A: &str =
            "sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
        const SCOPE: &str = "gcs://fixture/v2";

        let mut environment = kin_core::test_env::EnvVarGuard::new();
        for name in [
            "GOOGLE_CLOUD_PROJECT",
            "FIRESTORE_DATABASE_ID",
            "KIN_GCS_BUCKET",
            "KIN_GCS_PREFIX",
            "KIN_REPO_IDS",
        ] {
            environment.apply::<_, &str>(name, None);
        }
        assert!(
            std::env::var("GOOGLE_CLOUD_PROJECT").is_err(),
            "this fixture proves a refusal that only holds while the hosted Firestore \
             environment is absent"
        );

        let fleet = vec![
            "kin".to_string(),
            "kin-db".to_string(),
            "kin-vfs".to_string(),
            "kinlab".to_string(),
            "kin-editor".to_string(),
        ];

        let repo = tempfile::tempdir().unwrap();
        let initialized = kin_core::init(repo.path()).unwrap();
        let backend_root = tempfile::tempdir().unwrap();
        let store = Arc::new(crate::publication_lease::InMemoryPublicationControlStore::default());
        let control = Arc::new(
            crate::publication_lease::PublicationControl::new(
                SCOPE,
                READER_A,
                fleet.clone(),
                store,
            )
            .unwrap(),
        );
        let state = Arc::new(
            DaemonState::open_with_backend_and_publication_control(
                initialized.layout,
                Box::new(kin_db::LocalFileBackend::new(backend_root.path())),
                "kin",
                Some(fleet.iter().cloned().collect()),
                control,
            )
            .unwrap(),
        );
        let unauthenticated_embedded = std::panic::catch_unwind(std::panic::AssertUnwindSafe({
            let state = Arc::clone(&state);
            move || router(state)
        }));
        assert!(
            unauthenticated_embedded.is_err(),
            "the public embedded router must not expose hosted rollout mutation without auth"
        );
        let app = router_with_publication_control_auth(
            Arc::clone(&state),
            Some("daemon-test-token".to_string()),
            Some("publication-test-token".to_string()),
        );

        let ordinary_cannot_read_control = app
            .clone()
            .oneshot(
                Request::get("/authority/publication-control")
                    .header("authorization", "Bearer daemon-test-token")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(ordinary_cannot_read_control.status(), StatusCode::FORBIDDEN);
        let unauthenticated_cannot_read_control = app
            .clone()
            .oneshot(
                Request::get("/authority/publication-control")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(
            unauthenticated_cannot_read_control.status(),
            StatusCode::UNAUTHORIZED
        );

        let missing = app
            .clone()
            .oneshot(
                Request::get("/authority/publication-control")
                    .header("authorization", "Bearer publication-test-token")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(missing.status(), StatusCode::SERVICE_UNAVAILABLE);
        let missing_health = app
            .clone()
            .oneshot(
                Request::get("/health")
                    .header("authorization", "Bearer daemon-test-token")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(missing_health.status(), StatusCode::OK);
        let missing_health_body = axum::body::to_bytes(missing_health.into_body(), 64 * 1024)
            .await
            .unwrap();
        let missing_health: HealthResponse = serde_json::from_slice(&missing_health_body).unwrap();
        assert!(!missing_health.reader_admitted);
        assert_eq!(missing_health.status, "attention");
        let missing_readiness = app
            .clone()
            .oneshot(Request::get("/readiness").body(Body::empty()).unwrap())
            .await
            .unwrap();
        assert_eq!(missing_readiness.status(), StatusCode::SERVICE_UNAVAILABLE);
        let (status, body) = publication_spine_ingest(app.clone(), "kin").await;
        assert_eq!(status, StatusCode::SERVICE_UNAVAILABLE);
        assert!(String::from_utf8_lossy(&body).contains("record is absent"));

        let acquire = serde_json::json!({
            "scope": SCOPE,
            "repositories": ["kin", "kin-db", "kin-vfs", "kinlab", "kin-editor"],
            "holder": "staging-promotion",
            "request_id": "run-123",
            "ttl_seconds": 300,
            "bootstrap_reader": {
                "identity": READER_A,
                "min_snapshot_schema": kin_db::GraphSnapshot::CURRENT_VERSION,
                "max_snapshot_schema": kin_db::GraphSnapshot::CURRENT_VERSION,
                "valid_for_seconds": 3600
            }
        });
        let (status, lease) = publication_post(
            app.clone(),
            "/authority/publication-control/rollout/acquire",
            acquire.clone(),
        )
        .await;
        assert_eq!(status, StatusCode::SERVICE_UNAVAILABLE, "{lease}");
        let first_error = lease
            .get("text")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default();
        assert!(
            first_error.contains("GOOGLE_CLOUD_PROJECT") || first_error.contains("durable spine"),
            "the production route must name its missing durable authority: {lease}"
        );
        let (retry_status, retry) = publication_post(
            app.clone(),
            "/authority/publication-control/rollout/acquire",
            acquire,
        )
        .await;
        assert_eq!(retry_status, StatusCode::SERVICE_UNAVAILABLE, "{retry}");

        let control_status = app
            .clone()
            .oneshot(
                Request::get("/authority/publication-control")
                    .header("authorization", "Bearer publication-test-token")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(control_status.status(), StatusCode::OK);
        let status_body = axum::body::to_bytes(control_status.into_body(), 256 * 1024)
            .await
            .unwrap();
        let status_json: serde_json::Value = serde_json::from_slice(&status_body).unwrap();
        let status_text = String::from_utf8(status_body.to_vec()).unwrap();
        assert!(status_json["active_lease"].is_object());
        assert!(
            !status_text.contains("\"token\""),
            "read-only publication status must not disclose live lease capability: {status_text}"
        );

        let (blocked_status, blocked_body) = publication_spine_ingest(app.clone(), "kin").await;
        assert_eq!(blocked_status, StatusCode::SERVICE_UNAVAILABLE);
        let blocked_body = String::from_utf8_lossy(&blocked_body);
        assert!(blocked_body.contains("rollout fence"), "{blocked_body}");
    }

    /// The identity contract a client depends on: read `repo_id` off `/health`
    /// and every `/repos/{repo_id}/…` route resolves it. Two key spaces here
    /// meant a caller that trusted the advertised id got a storage-mode 500 on
    /// every repo-scoped call against a perfectly healthy daemon.
    #[tokio::test]
    async fn health_repo_id_addresses_every_repo_scoped_route() {
        let state = test_state();
        let repo_id = advertised_repo_id(Arc::clone(&state)).await;
        assert!(!repo_id.trim().is_empty(), "/health must advertise an id");

        let (status, body) =
            repo_route(Arc::clone(&state), &format!("/repos/{repo_id}/health")).await;
        assert_eq!(
            status,
            StatusCode::OK,
            "advertised repo id must route: {}",
            String::from_utf8_lossy(&body)
        );
        let health: RepoHealthResponse = serde_json::from_slice(&body).unwrap();
        assert_eq!(
            health.repo_id, repo_id,
            "the repo route must echo the advertised identity back"
        );

        for path in [
            format!("/repos/{repo_id}/entities"),
            format!("/repos/{repo_id}/refs"),
            format!("/repos/{repo_id}/files"),
            format!("/repos/{repo_id}/history"),
            format!("/repos/{repo_id}/provenance/verify"),
        ] {
            let (status, body) = repo_route(Arc::clone(&state), &path).await;
            assert_eq!(
                status,
                StatusCode::OK,
                "{path} must accept the advertised repo id: {}",
                String::from_utf8_lossy(&body)
            );
        }

        // /repos lists the same key space the advertised id belongs to.
        let (status, body) = repo_route(Arc::clone(&state), "/repos").await;
        assert_eq!(status, StatusCode::OK);
        let listed: ReposResponse = serde_json::from_slice(&body).unwrap();
        assert!(
            listed.repos.contains(&repo_id),
            "the advertised id must appear in the repo listing: {:?}",
            listed.repos
        );
    }

    /// An id this daemon does not serve is an identity mismatch, not a broken
    /// daemon: 404 naming the id that is served, rather than the lazy
    /// multi-repo loader's "no storage backend configured" 500.
    ///
    /// The route list covers every surface the identity resolution reaches,
    /// including the four that resolve through `repository_authority_snapshot`.
    /// Those short-circuit on the advertised id, so driving them with an id the
    /// daemon serves exercises none of this: only an unserved id reaches
    /// `repo_scoped_graph` through them.
    #[tokio::test]
    async fn an_unserved_repo_id_is_an_identity_mismatch_rather_than_a_storage_failure() {
        let state = test_state();
        let served = advertised_repo_id(Arc::clone(&state)).await;
        let unserved = format!("not-{served}");
        // Parses as a canonical semantic change id, so the archive route
        // reaches identity resolution instead of refusing on the id shape.
        let well_formed_change = "a".repeat(64);

        for path in [
            format!("/repos/{unserved}/health"),
            format!("/repos/{unserved}/entities"),
            format!("/repos/{unserved}/provenance/verify"),
            format!("/repos/{unserved}/files"),
            format!("/repos/{unserved}/refs"),
            format!("/repos/{unserved}/history"),
            format!("/repos/{unserved}/archive/tar/{well_formed_change}"),
        ] {
            let (status, body) = repo_route(Arc::clone(&state), &path).await;
            assert_eq!(status, StatusCode::NOT_FOUND, "{path}");
            let message = String::from_utf8_lossy(&body);
            assert!(
                message.contains(&served) && message.contains(&unserved),
                "the refusal must name both the served and requested ids: {message}"
            );
            assert!(
                !message.contains("no storage backend configured"),
                "an identity mismatch must not read as a storage-mode failure: {message}"
            );
        }
    }

    /// A `StorageBackend` that faults on demand for named repositories,
    /// delegating everything else to a real local backend.
    ///
    /// The faults it raises are the ones a hosted backend actually raises for a
    /// repository it is configured to serve: an unreachable object store,
    /// expired credentials, a snapshot authority that disagrees with the
    /// acknowledged head, or a corrupt delta chain. All of them arrive as an
    /// `Err` out of the recovery read, which is the single path
    /// `load_recovered_snapshot` takes, so fault injection is scoped to exactly
    /// the three reads that path makes.
    ///
    /// Every other trait method forwards to the inner backend, including the
    /// ones whose trait defaults would answer instead of delegating. That is
    /// not tidiness: `supports_incremental_deltas` defaults to `false` and the
    /// whole source-blob family defaults to "not supported by this backend",
    /// so a partially-forwarding fixture silently downgrades the very
    /// capabilities a hosted backend has. A test reusing it would then be
    /// measuring the fixture's degraded shape and reporting it as hosted
    /// behavior.
    ///
    /// The single method deliberately left on its trait default is
    /// `compact_deltas`, which `LocalFileBackend` also leaves defaulted. That
    /// default composes through this type's own reads, so compaction stays
    /// fault-aware instead of routing around the switch.
    struct RepoFaultBackend {
        inner: kin_db::LocalFileBackend,
        faulting: FaultSwitch,
    }

    /// Handle the test keeps after the backend is moved into the daemon, so a
    /// fault can be armed once the daemon has already opened healthy.
    #[derive(Default)]
    struct BackendBlockState {
        remaining_arrivals: usize,
        arrivals: usize,
        released: bool,
    }

    struct BackendBlock {
        state: std::sync::Mutex<BackendBlockState>,
        changed: std::sync::Condvar,
    }

    impl BackendBlock {
        fn new(arrivals: usize) -> Self {
            Self {
                state: std::sync::Mutex::new(BackendBlockState {
                    remaining_arrivals: arrivals,
                    ..BackendBlockState::default()
                }),
                changed: std::sync::Condvar::new(),
            }
        }

        fn arrive_and_wait(&self) {
            let mut state = self.state.lock().unwrap();
            if state.released || state.remaining_arrivals == 0 {
                return;
            }
            state.remaining_arrivals -= 1;
            state.arrivals += 1;
            self.changed.notify_all();
            while !state.released {
                state = self.changed.wait(state).unwrap();
            }
        }

        fn arrivals(&self) -> usize {
            self.state.lock().unwrap().arrivals
        }

        fn released(&self) -> bool {
            self.state.lock().unwrap().released
        }

        fn release(&self) {
            let mut state = self.state.lock().unwrap();
            state.released = true;
            self.changed.notify_all();
        }
    }

    #[derive(Clone)]
    struct BackendBlockHandle(Arc<BackendBlock>);

    impl BackendBlockHandle {
        fn arrivals(&self) -> usize {
            self.0.arrivals()
        }

        fn released(&self) -> bool {
            self.0.released()
        }

        fn release(&self) {
            self.0.release();
        }

        /// Fail-safe for tests that deliberately park synchronous backend I/O.
        ///
        /// Assertions happen only after the test releases and drains the
        /// parked operation, but a mutant can prevent the expected rendezvous
        /// entirely. This watchdog keeps that failure diagnostic instead of
        /// leaving the test process hung forever.
        fn release_on_deadline(&self, deadline: Duration) -> std::thread::JoinHandle<()> {
            let block = self.clone();
            std::thread::spawn(move || {
                let deadline = Instant::now() + deadline;
                while !block.released() && Instant::now() < deadline {
                    std::thread::sleep(Duration::from_millis(5));
                }
                if !block.released() {
                    block.release();
                }
            })
        }
    }

    async fn join_task_or_abort<T: Send + 'static>(
        task: &mut tokio::task::JoinHandle<T>,
        bound: Duration,
    ) -> std::result::Result<T, String> {
        match tokio::time::timeout(bound, &mut *task).await {
            Ok(Ok(value)) => Ok(value),
            Ok(Err(error)) => Err(format!("task failed while draining: {error}")),
            Err(_) => {
                task.abort();
                let _ = task.await;
                Err(format!("task did not drain within {bound:?}; aborted"))
            }
        }
    }

    async fn drain_join_set_or_abort<T: Send + 'static>(
        tasks: &mut tokio::task::JoinSet<T>,
        bound: Duration,
    ) -> std::result::Result<Vec<T>, String> {
        let drained = tokio::time::timeout(bound, async {
            let mut values = Vec::new();
            while let Some(result) = tasks.join_next().await {
                match result {
                    Ok(value) => values.push(value),
                    Err(error) => return Err(format!("task failed while draining: {error}")),
                }
            }
            Ok(values)
        })
        .await;

        match drained {
            Ok(Ok(values)) => Ok(values),
            Ok(Err(error)) => {
                tasks.abort_all();
                while tasks.join_next().await.is_some() {}
                Err(error)
            }
            Err(_) => {
                tasks.abort_all();
                while tasks.join_next().await.is_some() {}
                Err(format!("task set did not drain within {bound:?}; aborted"))
            }
        }
    }

    #[derive(Default)]
    struct FaultState {
        authority_faults: std::collections::HashSet<String>,
        cursor_faults: std::collections::HashSet<String>,
        /// Every authority-shaped read: recovery state, snapshot authority and
        /// raw snapshot.
        authority_loads: std::collections::HashMap<String, usize>,
        /// Only `load_recovery_state`. Separate from `authority_loads` because
        /// the concurrency tests assert exact deltas against this one call
        /// site, and a counter that also moved on the other two authority reads
        /// would make those assertions mean something else.
        recovery_loads: std::collections::HashMap<String, usize>,
        cursor_probes: std::collections::HashMap<String, usize>,
        cursor_probe_blocks: std::collections::HashMap<String, Arc<BackendBlock>>,
        recovery_load_blocks: std::collections::HashMap<String, Arc<BackendBlock>>,
        recovery_return_blocks: std::collections::HashMap<String, Arc<BackendBlock>>,
        publication_save_blocks: std::collections::HashMap<String, Arc<BackendBlock>>,
        /// Every `max_bytes` the route asked a bounded source read for. A route
        /// that never bounds its reads leaves this empty while everything else
        /// about the response looks the same.
        blob_read_ceilings: Vec<u64>,
        /// Bytes actually handed back across the whole run.
        blob_bytes_served: u64,
        /// Calls that reached the UNBOUNDED arm. A hosted route must never make
        /// one, and zero here is only evidence beside a nonzero bounded count.
        unbounded_blob_reads: usize,
        blob_faults: std::collections::HashSet<String>,
        /// Panic inside the source read rather than returning an error.
        ///
        /// `spawn_blocking` yields `Err(JoinError)` only when the closure panics
        /// or the runtime shuts down. A closure that returns `Err` takes the
        /// `Ok(Err(..))` arm, which is a different path, so a test that returns
        /// an error asserts on a proxy and cannot see a join failure at all.
        blob_panics: std::collections::HashSet<String>,
        /// Wall-clock delay a source read holds for, used to prove the read is
        /// not running on the thread driving the request future.
        blob_read_delay: Option<Duration>,
        /// Wall-clock cost every source publication cursor probe pays, so a
        /// readiness probe's per-repository reads are measured rather than
        /// assumed free.
        cursor_probe_delay: Option<Duration>,
        /// Cursor probes inside the backend right now, and the most that were
        /// ever there together. Concurrency is a structural property, so it is
        /// counted rather than inferred from how long a probe took: a shared
        /// CI runner can add a second of scheduling to any wall-clock reading,
        /// and a bound tight enough to separate concurrent from serial is
        /// tight enough to fail on that noise. This one cannot.
        cursor_probes_in_flight: usize,
        peak_cursor_probes_in_flight: usize,
    }

    #[derive(Clone)]
    struct FaultSwitch(Arc<std::sync::Mutex<FaultState>>);

    impl FaultSwitch {
        fn start_faulting(&self, repo_id: &str) {
            let mut state = self.0.lock().unwrap();
            state.authority_faults.insert(repo_id.to_string());
            state.cursor_faults.insert(repo_id.to_string());
        }

        fn start_authority_faulting(&self, repo_id: &str) {
            self.0
                .lock()
                .unwrap()
                .authority_faults
                .insert(repo_id.to_string());
        }

        fn start_cursor_faulting(&self, repo_id: &str) {
            self.0
                .lock()
                .unwrap()
                .cursor_faults
                .insert(repo_id.to_string());
        }

        fn authority_fault_for(&self, repo_id: &str) -> Option<kin_db::KinDbError> {
            self.0
                .lock()
                .unwrap()
                .authority_faults
                .contains(repo_id)
                .then(|| {
                    kin_db::KinDbError::StorageError(format!(
                        "{BACKEND_FAULT_TEXT} while reading {repo_id}"
                    ))
                })
        }

        /// Names both the armed backend and the specific read that failed.
        ///
        /// `BACKEND_FAULT_TEXT` is what a caller asserts to prove the armed
        /// backend was reached at all. On the repo-scoped route the cursor
        /// probe is the FIRST backend read (`load_hosted_repository_mcp_view`
        /// calls `hosted_snapshot_cursor` before any authority load), so a
        /// message carrying only the cursor text makes that proof fail on a
        /// fault that did happen. `CURSOR_FAULT_TEXT` stays beside it so a test
        /// can still tell a cursor fault from an authority one, because only
        /// this path emits it.
        fn cursor_fault_for(&self, repo_id: &str) -> Option<kin_db::KinDbError> {
            self.0
                .lock()
                .unwrap()
                .cursor_faults
                .contains(repo_id)
                .then(|| {
                    kin_db::KinDbError::StorageError(format!(
                        "{BACKEND_FAULT_TEXT}: {CURSOR_FAULT_TEXT} while reading {repo_id}"
                    ))
                })
        }

        fn record_authority_load(&self, repo_id: &str) {
            *self
                .0
                .lock()
                .unwrap()
                .authority_loads
                .entry(repo_id.to_string())
                .or_default() += 1;
        }

        fn authority_loads(&self, repo_id: &str) -> usize {
            self.0
                .lock()
                .unwrap()
                .authority_loads
                .get(repo_id)
                .copied()
                .unwrap_or_default()
        }

        fn record_recovery_load(&self, repo_id: &str) {
            *self
                .0
                .lock()
                .unwrap()
                .recovery_loads
                .entry(repo_id.to_string())
                .or_default() += 1;
        }

        fn recovery_loads(&self, repo_id: &str) -> usize {
            self.0
                .lock()
                .unwrap()
                .recovery_loads
                .get(repo_id)
                .copied()
                .unwrap_or_default()
        }

        fn record_cursor_probe(&self, repo_id: &str) {
            *self
                .0
                .lock()
                .unwrap()
                .cursor_probes
                .entry(repo_id.to_string())
                .or_default() += 1;
        }

        fn charge_each_cursor_probe(&self, cost: Duration) {
            self.0.lock().unwrap().cursor_probe_delay = Some(cost);
        }

        fn enter_cursor_probe(&self) {
            let mut state = self.0.lock().unwrap();
            state.cursor_probes_in_flight += 1;
            state.peak_cursor_probes_in_flight = state
                .peak_cursor_probes_in_flight
                .max(state.cursor_probes_in_flight);
        }

        fn leave_cursor_probe(&self) {
            self.0.lock().unwrap().cursor_probes_in_flight -= 1;
        }

        /// The most source cursor probes this backend ever served at one time.
        fn peak_concurrent_cursor_probes(&self) -> usize {
            self.0.lock().unwrap().peak_cursor_probes_in_flight
        }

        fn cursor_probe_delay(&self) -> Option<Duration> {
            self.0.lock().unwrap().cursor_probe_delay
        }

        /// Every cursor probe this backend has served, across every repository.
        fn total_cursor_probes(&self) -> usize {
            self.0.lock().unwrap().cursor_probes.values().sum()
        }

        fn cursor_probes(&self, repo_id: &str) -> usize {
            self.0
                .lock()
                .unwrap()
                .cursor_probes
                .get(repo_id)
                .copied()
                .unwrap_or_default()
        }

        fn block_cursor_probes(&self, repo_id: &str, arrivals: usize) -> BackendBlockHandle {
            let block = Arc::new(BackendBlock::new(arrivals));
            self.0
                .lock()
                .unwrap()
                .cursor_probe_blocks
                .insert(repo_id.to_string(), Arc::clone(&block));
            BackendBlockHandle(block)
        }

        fn block_recovery_loads(&self, repo_id: &str, arrivals: usize) -> BackendBlockHandle {
            let block = Arc::new(BackendBlock::new(arrivals));
            self.0
                .lock()
                .unwrap()
                .recovery_load_blocks
                .insert(repo_id.to_string(), Arc::clone(&block));
            BackendBlockHandle(block)
        }

        fn block_recovery_returns(&self, repo_id: &str, arrivals: usize) -> BackendBlockHandle {
            let block = Arc::new(BackendBlock::new(arrivals));
            self.0
                .lock()
                .unwrap()
                .recovery_return_blocks
                .insert(repo_id.to_string(), Arc::clone(&block));
            BackendBlockHandle(block)
        }

        fn block_publication_saves(&self, repo_id: &str, arrivals: usize) -> BackendBlockHandle {
            let block = Arc::new(BackendBlock::new(arrivals));
            self.0
                .lock()
                .unwrap()
                .publication_save_blocks
                .insert(repo_id.to_string(), Arc::clone(&block));
            BackendBlockHandle(block)
        }

        fn cursor_probe_block_for(&self, repo_id: &str) -> Option<Arc<BackendBlock>> {
            self.0
                .lock()
                .unwrap()
                .cursor_probe_blocks
                .get(repo_id)
                .cloned()
        }

        fn recovery_load_block_for(&self, repo_id: &str) -> Option<Arc<BackendBlock>> {
            self.0
                .lock()
                .unwrap()
                .recovery_load_blocks
                .get(repo_id)
                .cloned()
        }

        fn recovery_return_block_for(&self, repo_id: &str) -> Option<Arc<BackendBlock>> {
            self.0
                .lock()
                .unwrap()
                .recovery_return_blocks
                .get(repo_id)
                .cloned()
        }

        fn publication_save_block_for(&self, repo_id: &str) -> Option<Arc<BackendBlock>> {
            self.0
                .lock()
                .unwrap()
                .publication_save_blocks
                .get(repo_id)
                .cloned()
        }

        fn start_blob_panicking(&self, repo_id: &str) {
            self.0
                .lock()
                .unwrap()
                .blob_panics
                .insert(repo_id.to_string());
        }

        fn blob_panics_for(&self, repo_id: &str) -> bool {
            self.0.lock().unwrap().blob_panics.contains(repo_id)
        }

        fn start_blob_faulting(&self, repo_id: &str) {
            self.0
                .lock()
                .unwrap()
                .blob_faults
                .insert(repo_id.to_string());
        }

        fn delay_blob_reads(&self, delay: Duration) {
            self.0.lock().unwrap().blob_read_delay = Some(delay);
        }

        /// Records a bounded read and returns the delay it should hold for.
        ///
        /// The lock is released before the caller sleeps, so a delay does not
        /// serialize the instrument itself.
        fn record_bounded_blob_read(&self, max_bytes: u64) -> Option<Duration> {
            let mut state = self.0.lock().unwrap();
            state.blob_read_ceilings.push(max_bytes);
            state.blob_read_delay
        }

        fn record_blob_bytes(&self, bytes: u64) {
            self.0.lock().unwrap().blob_bytes_served += bytes;
        }

        fn record_unbounded_blob_read(&self) {
            self.0.lock().unwrap().unbounded_blob_reads += 1;
        }

        fn blob_fault_for(&self, repo_id: &str) -> Option<kin_db::KinDbError> {
            self.0
                .lock()
                .unwrap()
                .blob_faults
                .contains(repo_id)
                .then(|| {
                    kin_db::KinDbError::StorageError(format!(
                        "{BACKEND_FAULT_TEXT} while reading a source blob of {repo_id}"
                    ))
                })
        }

        fn blob_read_ceilings(&self) -> Vec<u64> {
            self.0.lock().unwrap().blob_read_ceilings.clone()
        }

        fn blob_bytes_served(&self) -> u64 {
            self.0.lock().unwrap().blob_bytes_served
        }

        fn unbounded_blob_reads(&self) -> usize {
            self.0.lock().unwrap().unbounded_blob_reads
        }
    }

    impl RepoFaultBackend {
        fn new(path: &std::path::Path) -> (Self, FaultSwitch) {
            let faulting = FaultSwitch(Arc::new(std::sync::Mutex::new(FaultState::default())));
            (
                Self {
                    inner: kin_db::LocalFileBackend::new(path),
                    faulting: faulting.clone(),
                },
                faulting,
            )
        }

        fn authority_fault_for(&self, repo_id: &str) -> Option<kin_db::KinDbError> {
            self.faulting.authority_fault_for(repo_id)
        }
    }

    const BACKEND_FAULT_TEXT: &str = "object store unreachable";
    const CURSOR_FAULT_TEXT: &str = "publication metadata unavailable";

    impl kin_db::StorageBackend for RepoFaultBackend {
        fn supports_incremental_deltas(&self) -> bool {
            self.inner.supports_incremental_deltas()
        }

        fn load_recovery_state(
            &self,
            repo_id: &str,
        ) -> std::result::Result<kin_db::SnapshotRecoveryState, kin_db::KinDbError> {
            self.faulting.record_authority_load(repo_id);
            self.faulting.record_recovery_load(repo_id);
            if let Some(block) = self.faulting.recovery_load_block_for(repo_id) {
                block.arrive_and_wait();
            }
            let outcome = match self.authority_fault_for(repo_id) {
                Some(error) => Err(error),
                None => self.inner.load_recovery_state(repo_id),
            };
            if let Some(block) = self.faulting.recovery_return_block_for(repo_id) {
                block.arrive_and_wait();
            }
            outcome
        }

        fn load_snapshot_cursor(
            &self,
            repo_id: &str,
        ) -> std::result::Result<Option<kin_db::SnapshotCursor>, kin_db::KinDbError> {
            // Count the probe before parking on any rendezvous, so a blocked
            // probe still shows up in `cursor_probes`.
            self.faulting.record_cursor_probe(repo_id);
            self.faulting.enter_cursor_probe();
            if let Some(cost) = self.faulting.cursor_probe_delay() {
                std::thread::sleep(cost);
            }
            self.faulting.leave_cursor_probe();
            if let Some(block) = self.faulting.cursor_probe_block_for(repo_id) {
                block.arrive_and_wait();
            }
            match self.faulting.cursor_fault_for(repo_id) {
                Some(error) => Err(error),
                None => self.inner.load_snapshot_cursor(repo_id),
            }
        }

        fn load_snapshot_authority(
            &self,
            repo_id: &str,
        ) -> std::result::Result<Option<kin_db::SnapshotAuthority>, kin_db::KinDbError> {
            self.faulting.record_authority_load(repo_id);
            match self.authority_fault_for(repo_id) {
                Some(error) => Err(error),
                None => self.inner.load_snapshot_authority(repo_id),
            }
        }

        fn load_snapshot(
            &self,
            repo_id: &str,
        ) -> std::result::Result<Option<(Vec<u8>, kin_db::Generation)>, kin_db::KinDbError>
        {
            self.faulting.record_authority_load(repo_id);
            match self.authority_fault_for(repo_id) {
                Some(error) => Err(error),
                None => self.inner.load_snapshot(repo_id),
            }
        }

        fn save_source_blob(
            &self,
            repo_id: &str,
            digest: [u8; 32],
            data: &[u8],
        ) -> std::result::Result<(), kin_db::KinDbError> {
            self.inner.save_source_blob(repo_id, digest, data)
        }

        fn load_source_blob(
            &self,
            repo_id: &str,
            digest: [u8; 32],
        ) -> std::result::Result<Option<Vec<u8>>, kin_db::KinDbError> {
            self.faulting.record_unbounded_blob_read();
            self.inner.load_source_blob(repo_id, digest)
        }

        fn load_source_blob_bounded(
            &self,
            repo_id: &str,
            digest: [u8; 32],
            max_bytes: u64,
        ) -> std::result::Result<Option<Vec<u8>>, kin_db::KinDbError> {
            if let Some(delay) = self.faulting.record_bounded_blob_read(max_bytes) {
                std::thread::sleep(delay);
            }
            if self.faulting.blob_panics_for(repo_id) {
                panic!("{BACKEND_FAULT_TEXT}: source read panicked for {repo_id}");
            }
            if let Some(error) = self.faulting.blob_fault_for(repo_id) {
                return Err(error);
            }
            let bytes = self
                .inner
                .load_source_blob_bounded(repo_id, digest, max_bytes)?;
            if let Some(bytes) = bytes.as_ref() {
                self.faulting
                    .record_blob_bytes(u64::try_from(bytes.len()).unwrap_or(u64::MAX));
            }
            Ok(bytes)
        }

        fn with_verified_source_blob_batch(
            &self,
            repo_id: &str,
            operation: &mut dyn FnMut(
                &dyn kin_db::VerifiedSourceBlobBatch,
            ) -> std::result::Result<(), kin_db::KinDbError>,
        ) -> std::result::Result<(), kin_db::KinDbError> {
            self.inner
                .with_verified_source_blob_batch(repo_id, operation)
        }

        fn source_blob_len(
            &self,
            repo_id: &str,
            digest: [u8; 32],
        ) -> std::result::Result<Option<u64>, kin_db::KinDbError> {
            self.inner.source_blob_len(repo_id, digest)
        }

        fn save_snapshot(
            &self,
            repo_id: &str,
            data: &[u8],
            expected_gen: kin_db::Generation,
        ) -> std::result::Result<kin_db::Generation, kin_db::KinDbError> {
            let outcome = self.inner.save_snapshot(repo_id, data, expected_gen);
            if outcome.is_ok() {
                if let Some(block) = self.faulting.publication_save_block_for(repo_id) {
                    block.arrive_and_wait();
                }
            }
            outcome
        }

        fn save_snapshot_classified(
            &self,
            repo_id: &str,
            data: &[u8],
            expected_cursor: kin_db::SnapshotCursor,
        ) -> kin_db::SnapshotSaveOutcome {
            let outcome = self
                .inner
                .save_snapshot_classified(repo_id, data, expected_cursor);
            if matches!(&outcome, kin_db::SnapshotSaveOutcome::Committed { .. }) {
                if let Some(block) = self.faulting.publication_save_block_for(repo_id) {
                    block.arrive_and_wait();
                }
            }
            outcome
        }

        fn save_snapshot_validated(
            &self,
            repo_id: &str,
            data: &[u8],
            expected: kin_db::SnapshotCursor,
            history_validator_version: Option<u32>,
        ) -> kin_db::SnapshotSaveOutcome {
            let outcome = self.inner.save_snapshot_validated(
                repo_id,
                data,
                expected,
                history_validator_version,
            );
            if matches!(&outcome, kin_db::SnapshotSaveOutcome::Committed { .. }) {
                if let Some(block) = self.faulting.publication_save_block_for(repo_id) {
                    block.arrive_and_wait();
                }
            }
            outcome
        }

        fn record_history_validation(
            &self,
            repo_id: &str,
            generation: kin_db::Generation,
            snapshot_sha256: &str,
            validator_version: u32,
        ) -> std::result::Result<bool, kin_db::KinDbError> {
            self.inner.record_history_validation(
                repo_id,
                generation,
                snapshot_sha256,
                validator_version,
            )
        }

        fn save_delta(
            &self,
            repo_id: &str,
            delta_data: &[u8],
            base_gen: kin_db::Generation,
        ) -> std::result::Result<kin_db::Generation, kin_db::KinDbError> {
            let outcome = self.inner.save_delta(repo_id, delta_data, base_gen);
            if outcome.is_ok() {
                if let Some(block) = self.faulting.publication_save_block_for(repo_id) {
                    block.arrive_and_wait();
                }
            }
            outcome
        }

        fn load_deltas_since(
            &self,
            repo_id: &str,
            since_gen: kin_db::Generation,
        ) -> std::result::Result<Vec<(Vec<u8>, kin_db::Generation)>, kin_db::KinDbError> {
            self.inner.load_deltas_since(repo_id, since_gen)
        }

        fn clear_deltas(&self, repo_id: &str) -> std::result::Result<(), kin_db::KinDbError> {
            self.inner.clear_deltas(repo_id)
        }

        fn save_overlay(
            &self,
            repo_id: &str,
            session_id: &str,
            data: &[u8],
        ) -> std::result::Result<(), kin_db::KinDbError> {
            self.inner.save_overlay(repo_id, session_id, data)
        }

        fn load_overlay(
            &self,
            repo_id: &str,
            session_id: &str,
        ) -> std::result::Result<Option<Vec<u8>>, kin_db::KinDbError> {
            self.inner.load_overlay(repo_id, session_id)
        }

        fn delete_overlay(
            &self,
            repo_id: &str,
            session_id: &str,
        ) -> std::result::Result<(), kin_db::KinDbError> {
            self.inner.delete_overlay(repo_id, session_id)
        }

        fn list_repos(&self) -> std::result::Result<Vec<String>, kin_db::KinDbError> {
            self.inner.list_repos()
        }
    }

    /// The shipped hosted shape: one advertised repo, several allowlisted
    /// siblings, none of them pre-warmed into the repo graph map, over a
    /// backend that can be made to fault per repository.
    /// The instrumented fixture, returning the backend directory so a test can
    /// publish a real repository into it and then measure what the route reads.
    ///
    /// [`hosted_state_with_allowlist`] hides that directory, which is right for
    /// a test that only needs a fault armed; a test measuring source reads has
    /// to publish bodies worth reading first.
    fn hosted_state_with_backend_dir(
        label: &str,
        advertised: &str,
        siblings: &[&str],
    ) -> (Arc<DaemonState>, FaultSwitch, std::path::PathBuf) {
        let dir = std::env::temp_dir().join(format!("kin-daemon-{label}-{}", Uuid::new_v4()));
        let kin_dir = dir.join(".kin");
        std::fs::create_dir_all(kin_dir.join("objects")).unwrap();
        std::fs::create_dir_all(kin_dir.join("working")).unwrap();
        let layout = kin_core::KinLayout::new(kin_dir);
        kin_core::manifest::KinManifest::new()
            .save(&layout.manifest_path())
            .unwrap();
        let backend_dir = dir.join("backend");
        std::fs::create_dir_all(&backend_dir).unwrap();

        let (backend, faults) = RepoFaultBackend::new(&backend_dir);
        let allowed: std::collections::HashSet<String> = std::iter::once(advertised)
            .chain(siblings.iter().copied())
            .map(ToOwned::to_owned)
            .collect();
        let state = Arc::new(
            DaemonState::open_with_backend(layout, Box::new(backend), advertised, Some(allowed))
                .unwrap(),
        );
        state.allow_hosted_in_memory_spine_for_test();
        (state, faults, backend_dir)
    }

    fn hosted_state_with_allowlist(
        label: &str,
        advertised: &str,
        siblings: &[&str],
    ) -> (Arc<DaemonState>, FaultSwitch) {
        let (state, faults, _backend_dir) =
            hosted_state_with_backend_dir(label, advertised, siblings);
        (state, faults)
    }

    fn hosted_state_without_allowlist(
        label: &str,
        advertised: &str,
    ) -> (Arc<DaemonState>, FaultSwitch, PathBuf) {
        let dir = std::env::temp_dir().join(format!("kin-daemon-{label}-{}", Uuid::new_v4()));
        let kin_dir = dir.join(".kin");
        std::fs::create_dir_all(kin_dir.join("objects")).unwrap();
        std::fs::create_dir_all(kin_dir.join("working")).unwrap();
        let layout = kin_core::KinLayout::new(kin_dir);
        kin_core::manifest::KinManifest::new()
            .save(&layout.manifest_path())
            .unwrap();
        let backend_dir = dir.join("backend");
        std::fs::create_dir_all(&backend_dir).unwrap();
        let (backend, faults) = RepoFaultBackend::new(&backend_dir);
        let state = Arc::new(
            DaemonState::open_with_backend(layout, Box::new(backend), advertised, None).unwrap(),
        );
        state.allow_hosted_in_memory_spine_for_test();
        (state, faults, backend_dir)
    }

    /// The fault fixture must be indistinguishable from the backend it wraps
    /// except when a fault is armed. A trait default answering in place of a
    /// forward is not a smaller lie than a wrong value: it reports "this
    /// backend cannot do that" about a backend that can, so a test reusing the
    /// fixture measures a degraded shape and reports it as hosted behavior.
    #[test]
    fn the_fault_fixture_forwards_the_capabilities_of_the_backend_it_wraps() {
        use kin_db::StorageBackend;

        let dir =
            std::env::temp_dir().join(format!("kin-daemon-fault-fidelity-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&dir).unwrap();
        let real = kin_db::LocalFileBackend::new(&dir);
        let (fixture, _faults) = RepoFaultBackend::new(&dir);

        assert!(
            real.supports_incremental_deltas(),
            "the wrapped backend is expected to have a delta write path"
        );
        assert_eq!(
            fixture.supports_incremental_deltas(),
            real.supports_incremental_deltas(),
            "a fixture that under-reports delta support sends writes down the wrong path"
        );

        let repo_id = "fidelity-repo";
        let body: &[u8] = b"fn main() {}";
        let digest: [u8; 32] = Sha256::digest(body).into();
        fixture
            .save_source_blob(repo_id, digest, body)
            .expect("the fixture must forward immutable source-blob writes");
        assert_eq!(
            real.load_source_blob(repo_id, digest).unwrap().as_deref(),
            Some(body),
            "the forwarded write must land in the wrapped backend"
        );
        assert_eq!(
            fixture
                .load_source_blob(repo_id, digest)
                .unwrap()
                .as_deref(),
            Some(body)
        );
        assert_eq!(
            fixture
                .load_source_blob_bounded(repo_id, digest, kin_db::MAX_SOURCE_BLOB_BYTES)
                .unwrap()
                .as_deref(),
            Some(body)
        );
        assert_eq!(
            fixture.source_blob_len(repo_id, digest).unwrap(),
            Some(body.len() as u64)
        );

        let mut batched: Option<Vec<u8>> = None;
        fixture
            .with_verified_source_blob_batch(repo_id, &mut |batch| {
                batched = batch
                    .load_verified(kin_db::SourceBlobValidationRequest {
                        digest,
                        max_bytes: kin_db::MAX_SOURCE_BLOB_BYTES,
                    })?
                    .map(|verified| verified.into_bytes());
                Ok(())
            })
            .expect("the fixture must forward verified batch reads");
        assert_eq!(batched.as_deref(), Some(body));
    }

    /// Ref discovery is a metadata read over authority the daemon already
    /// validated and loaded. Reopening the whole backend snapshot for every
    /// request made one 315-byte response download and decode the complete
    /// hosted repository authority, which took 54 seconds on the production
    /// Kin graph and multiplied peak memory under concurrent status probes.
    ///
    /// Faulting storage after startup makes the boundary deterministic. The
    /// loaded generation must keep answering from its generation-bound cache;
    /// a cache invalidation test below proves that a later authority movement
    /// does not stay hidden behind it.
    #[tokio::test]
    async fn hosted_refs_reuse_startup_authority_metadata_instead_of_reopening_storage() {
        let repo_id = format!("hosted-refs-cache-{}", Uuid::new_v4());
        let repository_id = RepositoryId::new(repo_id.clone()).unwrap();
        let dir = std::env::temp_dir().join(format!("kin-daemon-hosted-refs-{}", Uuid::new_v4()));
        let kin_dir = dir.join(".kin");
        std::fs::create_dir_all(kin_dir.join("objects")).unwrap();
        std::fs::create_dir_all(kin_dir.join("working")).unwrap();
        let layout = kin_core::KinLayout::new(kin_dir);
        kin_core::manifest::KinManifest::new()
            .save(&layout.manifest_path())
            .unwrap();
        let backend_dir = dir.join("backend");
        std::fs::create_dir_all(&backend_dir).unwrap();
        let expected_head = seed_replica_change(
            &backend_dir,
            &repository_id,
            None,
            0x8053,
            "serve refs from the loaded authority generation",
        );
        let (backend, faults) = RepoFaultBackend::new(&backend_dir);
        let state = Arc::new(
            DaemonState::open_with_backend(layout, Box::new(backend), &repo_id, None).unwrap(),
        );

        let startup_recovery_loads = faults.recovery_loads(&repo_id);
        faults.start_authority_faulting(&repo_id);
        let (status, body) =
            repo_route(Arc::clone(&state), &format!("/repos/{repo_id}/refs")).await;
        assert_eq!(
            status,
            StatusCode::OK,
            "the loaded authority metadata must not reopen storage: {}",
            String::from_utf8_lossy(&body)
        );
        let refs: RepoRefsResponse = serde_json::from_slice(&body).unwrap();
        assert_eq!(
            refs.head_ref.as_deref(),
            Some(expected_head.to_string().as_str())
        );
        assert_eq!(
            faults.recovery_loads(&repo_id),
            startup_recovery_loads,
            "an unchanged cursor must not reopen the full authority"
        );

        state.evict_repo_cache_for_test(&repo_id).await;
        let (status, body) =
            repo_route(Arc::clone(&state), &format!("/repos/{repo_id}/refs")).await;
        let message = String::from_utf8_lossy(&body);
        assert_eq!(
            status,
            StatusCode::INTERNAL_SERVER_ERROR,
            "an invalidated generation must reopen storage rather than serve stale refs: {message}"
        );
        assert!(
            message.contains(BACKEND_FAULT_TEXT),
            "the reopen must preserve the backend failure: {message}"
        );
    }

