    #[tokio::test]
    #[serial_test::serial(commit_phase_capture)]
    async fn commit_amend_cannot_drop_a_leased_entity_by_reverting_its_old_change() {
        let repo = tempfile::tempdir().unwrap();
        let state =
            Arc::new(DaemonState::open(kin_core::init(repo.path()).unwrap().layout).unwrap());
        let app = router(Arc::clone(&state));
        std::fs::write(repo.path().join("value.txt"), b"base\n").unwrap();
        commit_through_api(&app, kin_model::OperationId::new(), "base").await;
        std::fs::write(repo.path().join("main.rs"), b"pub fn value() -> u8 { 1 }\n").unwrap();
        let second = commit_through_api(&app, kin_model::OperationId::new(), "add source").await;
        let change = state.graph.get_change(&second).unwrap().unwrap();
        assert!(change
            .entity_deltas
            .iter()
            .all(|delta| matches!(delta, EntityDelta::Added { .. })));
        let entity = change
            .entity_deltas
            .first()
            .expect("the added source must have a semantic delta")
            .target_id();
        let owner = state
            .coordinator
            .register_session(
                "codex",
                "lease owner",
                SessionTransport::Mcp,
                None,
                repo.path().to_path_buf(),
                SessionCapabilities {
                    can_write: true,
                    can_commit: true,
                    ..SessionCapabilities::default()
                },
            )
            .unwrap();
        assert!(matches!(
            state
                .coordinator
                .register_intent(
                    &owner,
                    vec![IntentScope::Entity(entity)],
                    LockType::Hard,
                    "protected entity",
                    None,
                )
                .unwrap(),
            crate::session_registry::IntentRegistrationResult::Registered { .. }
        ));
        std::fs::remove_file(repo.path().join("main.rs")).unwrap();
        let count = state.graph.to_snapshot().changes.len();
        let (status, body) = amend_request_through_api(&app, second, None).await;
        assert_eq!(status, StatusCode::CONFLICT, "{body}");
        assert!(body.contains("lease_conflict"), "{body}");
        assert_eq!(branch_change(&state), second);
        assert_eq!(state.graph.to_snapshot().changes.len(), count);
        assert!(!repo.path().join("main.rs").exists());
        assert!(state.graph.get_entity(&entity).unwrap().is_none());
    }

    #[cfg(unix)]
    #[tokio::test]
    #[serial_test::serial(repository_commit)]
    async fn commit_amend_during_open_merge_refuses_before_admission() {
        let (state, _layout, repository, _, _) = universal_branch_test_state("amend-open-merge");
        let app = router(Arc::clone(&state));
        std::fs::write(
            repository.join("selected/compose.yaml"),
            b"services:\n  api:\n    image: main-conflict\n",
        )
        .unwrap();
        let head =
            commit_through_api(&app, kin_model::OperationId::new(), "conflicting main").await;
        let merge = kin_cli::commands::merge::MergeRequest {
            source: kin_model::RefName::branch(b"feature").unwrap(),
            operation_id: kin_model::OperationId::new(),
            actor: AuthorId::new("merge test"),
        };
        let response = app
            .clone()
            .oneshot(
                Request::post("/commands/merge")
                    .header("content-type", "application/json")
                    .body(Body::from(serde_json::to_vec(&merge).unwrap()))
                    .unwrap(),
            )
            .await
            .unwrap();
        let body = axum::body::to_bytes(response.into_body(), 512 * 1024)
            .await
            .unwrap();
        let merged: kin_cli::commands::merge::MergeResponse =
            serde_json::from_slice(&body).unwrap();
        assert!(matches!(
            merged.report.unwrap().outcome,
            kin_cli::commands::merge::MergeOutcome::Conflicted
        ));
        let before = generation_pair(&state);
        std::fs::write(repository.join("pending.txt"), b"pending outside merge\n").unwrap();
        let (status, body) = amend_request_through_api(&app, head, Some("must refuse")).await;
        assert_eq!(status, StatusCode::CONFLICT, "{body}");
        assert!(
            body.contains("merge transaction") && body.contains("still open"),
            "{body}"
        );
        assert_eq!(generation_pair(&state), before);
        assert_eq!(branch_change(&state), head);
        assert!(state
            .graph
            .resolved_tree()
            .artifact_at_path(&kin_model::RepoPath::from_utf8("pending.txt").unwrap())
            .is_none());
    }

    /// FIR-3209. A session that deletes an entity-owning file reconciles, the
    /// file's entities are absent from every query afterwards, and the next
    /// commit records the removal.
    ///
    /// kin-db refuses a transition that leaves an entity on a path the staged
    /// tree no longer carries, and it names the remedy in its own message:
    /// "carry its exact entity removal or relocation in the same delta". The
    /// invariant is right and the session admission was the caller that owed
    /// the removal, so an agent's `rm` of a source file could not reconcile at
    /// all. The existing session-reconcile test deletes `delete.me`, a file with
    /// no entities, which is why the suite was green over this.
    ///
    /// Falsify by restoring `semantic_delta: WorkspaceSemanticDelta::default()`
    /// in `plan_session_workspace_admission`: the reconcile returns the 500 the
    /// review's control probe measured, and `gone.rs` keeps its entity with no
    /// file behind it.
    #[cfg(unix)]
    #[tokio::test]
    #[serial_test::serial(commit_phase_capture)]
    async fn a_session_that_deletes_an_entity_source_file_retires_its_entities() {
        let repo = tempfile::tempdir().unwrap();
        let initialized = kin_core::init(repo.path()).unwrap();
        let state = Arc::new(DaemonState::open(initialized.layout).unwrap());
        state
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);
        std::fs::write(repo.path().join("keep.rs"), b"pub fn keep() -> u32 { 1 }\n").unwrap();
        std::fs::write(repo.path().join("gone.rs"), b"pub fn gone() -> u32 { 7 }\n").unwrap();
        let app = router(Arc::clone(&state));
        commit_through_api(&app, kin_model::OperationId::new(), "publish the fixtures").await;
        let entities_at = |path: &str| {
            state
                .graph
                .query_entities(&kin_db::EntityFilter {
                    file_path: Some(kin_model::FilePathId::new(path)),
                    ..Default::default()
                })
                .unwrap()
        };
        let gone_before = entities_at("gone.rs");
        eprintln!(
            "FIR-3209 measurement: before gone.rs entities={} keep.rs entities={}",
            gone_before.len(),
            entities_at("keep.rs").len()
        );
        assert_eq!(gone_before.len(), 1, "the fixture owns exactly one entity");
        let gone_id = gone_before[0].id;

        let session_dir = state.layout.root().join("runs/session-fir3209");
        materialize_session_through_api(&app, &session_dir).await;
        std::fs::remove_file(session_dir.join("gone.rs")).unwrap();

        let response = app
            .clone()
            .oneshot(
                Request::post("/reconcile")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        json!({"session_dir": session_dir, "confirm_mass_deletion": false})
                            .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        let status = response.status();
        let body = axum::body::to_bytes(response.into_body(), 128 * 1024)
            .await
            .unwrap();
        let body = String::from_utf8_lossy(&body).to_string();
        eprintln!(
            "FIR-3209 measurement: reconcile status={status} after gone.rs entities={} body={body}",
            entities_at("gone.rs").len()
        );
        assert_eq!(
            status,
            StatusCode::OK,
            "deleting a source file in a session is an ordinary edit and must reconcile: {body}"
        );
        let summary: kin_cli::commands::reconcile::ReconcileSummary =
            serde_json::from_str(&body).unwrap();
        assert_eq!(summary.removed, 1);

        // Absent from every query, not only the by-path one the invariant is
        // phrased in: by id, by name, and from the exact tree.
        assert!(
            entities_at("gone.rs").is_empty(),
            "an entity must not outlive the path that owned it"
        );
        assert_eq!(entities_at("keep.rs").len(), 1, "the sibling is untouched");
        assert!(state.graph.get_entity(&gone_id).unwrap().is_none());
        assert!(state
            .graph
            .query_entities(&kin_db::EntityFilter {
                name_pattern: Some("gone".to_string()),
                ..Default::default()
            })
            .unwrap()
            .is_empty());
        assert!(state
            .graph
            .resolved_tree()
            .artifact_at_path(&RepoPath::from_utf8("gone.rs".to_string()).unwrap())
            .is_none());

        // The next commit carries the removal into history.
        let change_id =
            commit_through_api(&app, kin_model::OperationId::new(), "commit the deletion").await;
        let change = state.graph.get_change(&change_id).unwrap().unwrap();
        assert!(
            change.entity_deltas.iter().any(|delta| matches!(
                delta,
                kin_model::EntityDelta::Removed { old } if old.id == gone_id
            )),
            "the commit after the session must record the entity's removal: {:?}",
            change.entity_deltas
        );
        assert!(
            change
                .tree_deltas
                .iter()
                .any(|delta| matches!(delta, kin_model::TreeDelta::Removed { .. })),
            "and the file's removal beside it"
        );
    }

    /// FIR-3209, the artifact half. A session that deletes a file another file
    /// imports.
    ///
    /// The cross-file linker mints an artifact-to-artifact `Imports` edge that
    /// no entity reaches, and kin-db validates every relation endpoint against
    /// the staged artifact set, so retiring the file's entities alone left one
    /// edge standing and the whole transaction was refused with "unadmitted
    /// destination endpoint". Measured red by review1503's probe C at 03476033c.
    ///
    /// Falsify by dropping the `GraphNodeId::Artifact` arm from `departs` in
    /// `retire_semantics_on_vacated`: the 500 returns with that message.
    #[cfg(unix)]
    #[tokio::test]
    #[serial_test::serial(commit_phase_capture)]
    async fn a_session_that_deletes_an_imported_file_retires_its_artifact_edges() {
        let repo = tempfile::tempdir().unwrap();
        let initialized = kin_core::init(repo.path()).unwrap();
        let state = Arc::new(DaemonState::open(initialized.layout).unwrap());
        state
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);
        std::fs::write(
            repo.path().join("gone.ts"),
            b"export function gone(): number { return 7; }\n",
        )
        .unwrap();
        std::fs::write(
            repo.path().join("keep.ts"),
            b"import { gone } from \"./gone\";\nexport function keep(): number { return gone(); }\n",
        )
        .unwrap();
        let app = router(Arc::clone(&state));
        commit_through_api(&app, kin_model::OperationId::new(), "publish the fixtures").await;
        let gone_path = RepoPath::from_utf8("gone.ts".to_string()).unwrap();
        let gone_artifact = state
            .graph
            .resolved_tree()
            .artifact_at_path(&gone_path)
            .map(|artifact| artifact.artifact_id)
            .expect("the fixture is in the tree");
        let gone_node = kin_model::GraphNodeId::Artifact(gone_artifact);
        assert!(
            !state
                .graph
                .get_all_relations_for_node(&gone_node)
                .unwrap()
                .is_empty(),
            "the fixture only means something if the linker bound an edge to the artifact node"
        );

        let session_dir = state.layout.root().join("runs/session-fir3209-imported");
        materialize_session_through_api(&app, &session_dir).await;
        std::fs::remove_file(session_dir.join("gone.ts")).unwrap();
        let summary = reconcile_session_through_api(&app, &session_dir).await;
        assert_eq!(summary.removed, 1);

        assert!(state
            .graph
            .resolved_tree()
            .artifact_at_path(&gone_path)
            .is_none());
        assert!(
            state
                .graph
                .get_all_relations_for_node(&gone_node)
                .unwrap()
                .is_empty(),
            "no relation may outlive the artifact node it is bound to"
        );
        assert!(state
            .graph
            .query_entities(&kin_db::EntityFilter {
                file_path: Some(kin_model::FilePathId::new("gone.ts")),
                ..Default::default()
            })
            .unwrap()
            .is_empty());
        assert!(!state
            .graph
            .query_entities(&kin_db::EntityFilter {
                file_path: Some(kin_model::FilePathId::new("keep.ts")),
                ..Default::default()
            })
            .unwrap()
            .is_empty());
        commit_through_api(&app, kin_model::OperationId::new(), "commit the deletion").await;
    }

    /// FIR-3209, the split-brain half. Modify an entity-owning file in one
    /// session, then delete it in the next.
    ///
    /// The first reconcile's readmission re-derives the path's entities into
    /// the live graph only, so authority and the live graph now hold different
    /// payloads for the same entity. A removal delta diffed against authority
    /// and then applied to the live graph is refused there, "stale old payload
    /// for removed entity", after authority has already committed, which left
    /// the two graphs on different trees. Measured red by review1503's probe E
    /// at 03476033c. Each graph now diffs itself with the same vacated set.
    ///
    /// Falsify by applying the plan's authority-derived deltas to the live
    /// graph instead of the live-derived ones: the delete reconcile 500s with
    /// that message after the authority commit is durable.
    #[cfg(unix)]
    #[tokio::test]
    #[serial_test::serial(commit_phase_capture)]
    async fn a_session_that_deletes_a_file_an_earlier_session_modified_reconciles() {
        let repo = tempfile::tempdir().unwrap();
        let initialized = kin_core::init(repo.path()).unwrap();
        let state = Arc::new(DaemonState::open(initialized.layout).unwrap());
        state
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);
        std::fs::write(repo.path().join("keep.rs"), b"pub fn keep() -> u32 { 1 }\n").unwrap();
        std::fs::write(repo.path().join("gone.rs"), b"pub fn gone() -> u32 { 7 }\n").unwrap();
        let app = router(Arc::clone(&state));
        commit_through_api(&app, kin_model::OperationId::new(), "publish the fixtures").await;
        let entities_at = |path: &str| {
            state
                .graph
                .query_entities(&kin_db::EntityFilter {
                    file_path: Some(kin_model::FilePathId::new(path)),
                    ..Default::default()
                })
                .unwrap()
        };
        assert_eq!(entities_at("gone.rs").len(), 1);

        let first = state.layout.root().join("runs/session-fir3209-modify");
        materialize_session_through_api(&app, &first).await;
        prepend_session_lines(&first.join("gone.rs"), 17);
        let modified = reconcile_session_through_api(&app, &first).await;
        assert_eq!(modified.semantic_files_enriched, 1);
        assert_eq!(
            entities_at("gone.rs")[0].span.as_ref().unwrap().start_line,
            17,
            "the live graph moved on; authority did not"
        );

        let second = state.layout.root().join("runs/session-fir3209-then-delete");
        materialize_session_through_api(&app, &second).await;
        std::fs::remove_file(second.join("gone.rs")).unwrap();
        let deleted = reconcile_session_through_api(&app, &second).await;
        assert_eq!(deleted.removed, 1);
        assert!(entities_at("gone.rs").is_empty());
        assert_eq!(entities_at("keep.rs").len(), 1);

        // The two graphs must still be level: a third session materializes and
        // the next commit carries the removal into history.
        let change_id =
            commit_through_api(&app, kin_model::OperationId::new(), "commit the deletion").await;
        let change = state.graph.get_change(&change_id).unwrap().unwrap();
        assert!(
            change.entity_deltas.iter().any(|delta| matches!(
                delta,
                kin_model::EntityDelta::Removed { old }
                    if old.file_origin.as_ref().is_some_and(|f| f.0 == "gone.rs")
            )),
            "history must record the removal: {:?}",
            change.entity_deltas
        );
    }

    /// Changes in repository authority, read the way `kin log` reads them.
    #[cfg(unix)]
    fn authority_change_count(state: &Arc<DaemonState>) -> usize {
        let context =
            crate::local_repository_authority::LocalRepositoryAuthorityContext::from_state(state)
                .unwrap();
        let authority = context.open().unwrap();
        let lease = authority.read_authority();
        let count = lease.snapshot().changes.len();
        count
    }

    /// The endpoint used to resolve its own author, and the resolution was two
    /// environment reads with the word "unknown" behind them. It now takes the
    /// author from the caller and has no fallback at all, so a request that
    /// names nobody has to be refused rather than completed. The daemon cannot
    /// answer this question for itself: it runs with every `GIT_*` variable
    /// scrubbed and does not share the caller's working directory.
    #[tokio::test]
    async fn commit_refuses_a_request_that_names_no_author() {
        let repo = tempfile::tempdir().unwrap();
        let initialized = kin_core::init(repo.path()).unwrap();
        let state = Arc::new(DaemonState::open(initialized.layout).unwrap());
        std::fs::write(
            repo.path().join("unattributable.rs"),
            b"pub fn unattributable() -> u32 { 1 }\n",
        )
        .unwrap();

        let before = crate::loop_runner::current_authority_admission(&state)
            .unwrap()
            .0
            .generation;
        let response = router(Arc::clone(&state))
            .oneshot(
                Request::post("/commands/commit")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        json!({
                            "operation_id": kin_model::OperationId::new(),
                            "timestamp": kin_model::Timestamp::now(),
                            "message": "nobody authored this"
                        })
                        .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();

        let status = response.status();
        assert!(
            status.is_client_error(),
            "a commit naming no author must be refused, got {status}"
        );
        let after = crate::loop_runner::current_authority_admission(&state)
            .unwrap()
            .0
            .generation;
        assert_eq!(
            after, before,
            "a refused commit must publish no authority successor"
        );
    }

    /// The author the caller named is the author the change carries, byte for
    /// byte. A daemon that normalized, truncated, or re-derived it would be
    /// answering with its own idea of who committed.
    #[tokio::test]
    async fn commit_records_the_author_the_caller_named() {
        let repo = tempfile::tempdir().unwrap();
        let initialized = kin_core::init(repo.path()).unwrap();
        let state = Arc::new(DaemonState::open(initialized.layout).unwrap());
        std::fs::write(
            repo.path().join("attributed.rs"),
            b"pub fn attributed() -> u32 { 1 }\n",
        )
        .unwrap();

        let response = router(Arc::clone(&state))
            .oneshot(
                Request::post("/commands/commit")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        json!({
                            "operation_id": kin_model::OperationId::new(),
                            "timestamp": kin_model::Timestamp::now(),
                            "author": "Ada Lovelace <ada@example.com>",
                            "message": "attribute this change to a person"
                        })
                        .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        let status = response.status();
        let body = axum::body::to_bytes(response.into_body(), 64 * 1024)
            .await
            .unwrap();
        assert_eq!(
            status,
            StatusCode::OK,
            "commit must succeed: {}",
            String::from_utf8_lossy(&body)
        );

        let context =
            crate::local_repository_authority::LocalRepositoryAuthorityContext::from_state(&state)
                .unwrap();
        let authority = context.open().unwrap();
        let lease = authority.read_authority();
        let committed = lease
            .snapshot()
            .changes
            .values()
            .find(|change| change.message == "attribute this change to a person")
            .expect("the published change");
        assert_eq!(committed.author.0, "Ada Lovelace <ada@example.com>");
    }

    /// A commit that reaches authority clears a wedge, because its transaction
    /// carried the graph's tree across.
    ///
    /// The other half of the deferral's own contract. A commit that fails
    /// publishes its deferred tree standalone, and a failure there wedges the
    /// daemon; a commit that succeeds is the same transition arriving by the
    /// intended door, so the divergence a wedge names cannot survive it. Without
    /// this the flag would be a one-way latch that a daemon carried until
    /// restart even after the state had resolved.
    #[cfg(unix)]
    #[tokio::test]
    // Commit phases are emitted at debug level when they are fast, and the
    // level a `tracing` event is filtered by is a process-global hint. A test
    // that captures those events therefore cannot run beside one that emits
    // them, so every test on either side of that shares this group.
    #[serial_test::serial(commit_phase_capture)]
    async fn a_commit_that_reaches_authority_clears_a_recorded_wedge() {
        let repo = tempfile::tempdir().unwrap();
        let initialized = kin_core::init(repo.path()).unwrap();
        let state = Arc::new(DaemonState::open(initialized.layout).unwrap());
        std::fs::write(
            repo.path().join("recovered.rs"),
            b"pub fn recovered() -> u32 { 1 }\n",
        )
        .unwrap();
        state
            .background_work
            .reconcile()
            .record_deferred_tree_wedge(
                "an earlier restoring publication failed",
                std::time::Instant::now(),
            );
        assert!(
            state
                .background_work
                .reconcile_report(std::time::Instant::now())
                .degraded(),
            "the fixture must start wedged, or the assertion below proves nothing"
        );

        let app = router(Arc::clone(&state));
        commit_through_api(
            &app,
            kin_model::OperationId::new(),
            "publish through the deferral's own transaction",
        )
        .await;

        let report = state
            .background_work
            .reconcile_report(std::time::Instant::now());
        assert!(
            report.deferred_tree_wedge.is_none(),
            "a commit that published cannot leave the graph ahead of authority"
        );
        assert!(!report.degraded(), "{:?}", report.degraded_reasons());
    }

    #[tokio::test]
    async fn graph_only_command_commit_fails_before_filesystem_delta_computation() {
        let state = test_state();
        state
            .graph
            .upsert_entity(&test_entity("remote_authority", "src/remote.rs"))
            .unwrap();
        state
            .filesystem_reconcile_disabled
            .store(true, std::sync::atomic::Ordering::Relaxed);
        let root_before = state.graph.compute_root_hash();
        let snapshot_before = state.graph.to_snapshot().to_bytes().unwrap();
        let generation_before = state
            .snapshot_generation
            .load(std::sync::atomic::Ordering::Relaxed);

        let response = router(Arc::clone(&state))
            .oneshot(
                Request::post("/commands/commit")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        json!({
                            "operation_id": kin_model::OperationId::new(),
                            "timestamp": kin_model::Timestamp::now(),
                            "author": "Test Author <test@example.invalid>",
                            "message": "must not infer emptyDir removals"
                        })
                        .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::CONFLICT);
        let body = axum::body::to_bytes(response.into_body(), 4096)
            .await
            .unwrap();
        let json: serde_json::Value = serde_json::from_slice(&body).unwrap();
        assert_eq!(json["error"], "filesystem_admission_disabled");
        assert_eq!(json["endpoint"], "/commands/commit");
        assert_eq!(json["mutation_applied"], false);
        assert_eq!(state.graph.compute_root_hash(), root_before);
        assert_eq!(
            state.graph.to_snapshot().to_bytes().unwrap(),
            snapshot_before
        );
        assert_eq!(
            state
                .snapshot_generation
                .load(std::sync::atomic::Ordering::Relaxed),
            generation_before
        );
    }

    /// Every span the CLI commit path spends before durable publication names
    /// itself in the log.
    ///
    /// The finalize after publication already reported its steps, so the wall a
    /// user waits was attributable only from its tail backwards. Everything in
    /// front of it, the coordination gate, the forced filesystem admission it
    /// guards, transaction planning, and the live-graph install, ran silent,
    /// which left a slow commit blamable on any of them and disprovable against
    /// none. This drives one real commit through the router under a capture
    /// subscriber and reads the phase lines back, so a span that stops
    /// reporting fails here rather than reappearing as an unexplained gap.
    ///
    /// The names are asserted because the proof parser keys on them. A fabricated
    /// name is checked too: without it a capture that silently collected nothing
    /// would satisfy every membership assertion it was given.
    #[tokio::test]
    // Commit phases are emitted at debug level when they are fast, and the
    // level a `tracing` event is filtered by is a process-global hint. A test
    // that captures those events therefore cannot run beside one that emits
    // them, so every test on either side of that shares this group.
    #[serial_test::serial(commit_phase_capture)]
    async fn the_cli_commit_path_names_every_phase_it_spends() {
        use tracing_subscriber::layer::SubscriberExt as _;

        #[derive(Default)]
        struct Captured {
            phases: Vec<String>,
            malformed: Vec<String>,
        }

        struct CaptureLayer(Arc<std::sync::Mutex<Captured>>);

        impl<S: tracing::Subscriber> tracing_subscriber::Layer<S> for CaptureLayer {
            fn on_event(
                &self,
                event: &tracing::Event<'_>,
                _ctx: tracing_subscriber::layer::Context<'_, S>,
            ) {
                #[derive(Default)]
                struct Read {
                    phase: Option<String>,
                    message: Option<String>,
                    elapsed_ms: bool,
                }
                impl tracing::field::Visit for Read {
                    fn record_str(&mut self, field: &tracing::field::Field, value: &str) {
                        if field.name() == "phase" {
                            self.phase = Some(value.to_string());
                        }
                    }
                    fn record_debug(
                        &mut self,
                        field: &tracing::field::Field,
                        value: &dyn std::fmt::Debug,
                    ) {
                        match field.name() {
                            "message" => self.message = Some(format!("{value:?}")),
                            "elapsed_ms" => self.elapsed_ms = true,
                            _ => {}
                        }
                    }
                }

                let mut read = Read::default();
                event.record(&mut read);
                let message = read.message.unwrap_or_default();
                if message != "commit phase" && message != "slow commit phase" {
                    return;
                }
                let mut captured = self.0.lock().unwrap();
                match read.phase {
                    // The proof parser reads `phase=` and `elapsed_ms=` off these
                    // two needles, so a line carrying one without the other is a
                    // parse failure and is collected as such rather than dropped.
                    Some(phase) if read.elapsed_ms => captured.phases.push(phase),
                    other => captured.malformed.push(format!("{message}: {other:?}")),
                }
            }
        }

        let state = test_state();
        let root = state.layout.working_dir();
        std::fs::write(root.join("attributable.rs"), b"pub fn attributable() {}\n").unwrap();
        let app = router(Arc::clone(&state));

        let captured = Arc::new(std::sync::Mutex::new(Captured::default()));
        let subscriber = tracing_subscriber::registry().with(CaptureLayer(Arc::clone(&captured)));
        let response = {
            let _capture = crate::capture_events_on_this_thread(subscriber);
            // The parallel test that broke this, made deliberate. A thread
            // carrying no subscriber of its own reaches the blocking phase
            // helper and registers its callsite. Without the second dispatcher
            // the capture holds, `tracing` resolves that callsite against this
            // thread's absent subscriber and caches `Interest::never()` for the
            // whole process, so every phase below emitted through that helper is
            // dropped while the two emitted through the async helper survive.
            std::thread::spawn(|| {
                crate::mcp_commit::timed_commit_phase("phase_registered_off_this_thread", || ())
            })
            .join()
            .unwrap();
            app.oneshot(
                Request::post("/commands/commit")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        json!({
                            "operation_id": kin_model::OperationId::new(),
                            "timestamp": kin_model::Timestamp::now(),
                            "author": "Test Author <test@example.invalid>",
                            "message": "attribute the commit wall"
                        })
                        .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap()
        };
        let status = response.status();
        let body = axum::body::to_bytes(response.into_body(), 64 * 1024)
            .await
            .unwrap();
        assert_eq!(status, StatusCode::OK, "{}", String::from_utf8_lossy(&body));

        let captured = std::mem::take(&mut *captured.lock().unwrap());
        assert!(
            captured.malformed.is_empty(),
            "every commit phase line must carry both phase and elapsed_ms: {:?}",
            captured.malformed
        );
        assert!(
            !captured
                .phases
                .iter()
                .any(|phase| phase == "phase_registered_off_this_thread"),
            "the capture stays scoped to the thread that installed it, so the phase \
             registered off it must not appear; captured {:?}",
            captured.phases
        );
        for phase in [
            "coordination_gate_wait",
            "forced_filesystem_admission",
            "scan_working_copy",
            "observe_tree_and_stage_blobs",
            "plan_transaction",
            "plan_snapshot_clone",
            "plan_diff_semantics",
            "plan_compute_deltas",
            "plan_derive_admission_policy",
            "install_live_graph",
        ] {
            assert!(
                captured.phases.iter().any(|captured| captured == phase),
                "the commit path must name the {phase} phase; captured {:?}",
                captured.phases
            );
        }
        for phase in [
            // A phase the path never runs must not be reported. The fabricated
            // name is the control: it can never appear, so it proves the
            // assertion is looking at something.
            "phase_this_commit_never_spends",
            // The commit no longer publishes the admitted tree in a successor
            // of its own. The admission derives the tree and hands it to the
            // commit's transaction, which carries the tree transition beside
            // the semantic change, so one repository-authority successor is
            // prepared and one store snapshot persisted for the whole commit.
            // Publishing the tree separately is what this phase timed, and a
            // commit that spends it again has gone back to paying for two.
            //
            // The phase itself is still live and still timed on the standalone
            // admission path, which is where the ambient watcher tick and every
            // explicit `kin admit` publish from.
            "publish_workspace_admission",
        ] {
            assert!(
                !captured.phases.iter().any(|captured| captured == phase),
                "the commit path must not name the {phase} phase; captured {:?}",
                captured.phases
            );
        }
    }

    /// A commit performs a complete exact-tree admission, so it must leave the
    /// durable record of one behind.
    ///
    /// The marker had two writers before this, the ambient reconcile tick and
    /// `kin admit`, and a convert-then-commit session runs neither: the tick
    /// stands its own round down for a commit already inside the daemon. So two
    /// stores converted and committed by one binary ended in opposite freshness
    /// states, one carrying a timestamp because an ambient tick happened to land
    /// milliseconds before its commit took the coordination gate, and the other
    /// reporting that no complete admission had ever been recorded for it.
    ///
    /// The absent read before the commit is the control. `test_state` opens a
    /// store with no ambient loop and no marker, so a marker afterwards can only
    /// have been written by the commit under test, and an assertion that passed
    /// on a store that was already stamped would prove nothing.
    #[tokio::test]
    #[serial_test::serial(commit_phase_capture)]
    async fn a_commit_records_the_complete_admission_it_performed() {
        use kin_core::last_admission::LastAdmissionRead;

        let state = test_state();
        assert!(
            matches!(
                kin_core::last_admission::read(&state.layout),
                LastAdmissionRead::Absent
            ),
            "the fixture store must carry no marker, or a marker afterwards proves nothing"
        );

        let root = state.layout.working_dir();
        std::fs::write(root.join("admitted.rs"), b"pub fn admitted() {}\n").unwrap();
        let app = router(Arc::clone(&state));
        let response = app
            .clone()
            .oneshot(
                Request::post("/commands/commit")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        json!({
                            "operation_id": kin_model::OperationId::new(),
                            "timestamp": kin_model::Timestamp::now(),
                            "author": "Test Author <test@example.invalid>",
                            "message": "record the admission this commit performed"
                        })
                        .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        let status = response.status();
        let body = axum::body::to_bytes(response.into_body(), 64 * 1024)
            .await
            .unwrap();
        assert_eq!(status, StatusCode::OK, "{}", String::from_utf8_lossy(&body));

        let recorded = match kin_core::last_admission::read(&state.layout) {
            LastAdmissionRead::Recorded(recorded) => recorded,
            other => panic!(
                "a successful commit must record the complete admission it performed, read {other:?}"
            ),
        };
        assert_eq!(
            recorded.tracked_artifacts,
            state.graph.resolved_tree().len() as u64,
            "the record must cover the tree the commit left behind, not a different count"
        );
        assert!(
            recorded.age_seconds(chrono::Utc::now()) < 300,
            "the record must be stamped by this commit rather than carried in from elsewhere"
        );

        // The in-memory probes carry the same fact, so `/health`, `kin doctor`
        // and `kin admit` name a commit's admission instead of reporting that
        // none has succeeded in this daemon's life.
        assert!(
            state
                .background_work
                .reconcile_report(std::time::Instant::now())
                .last_admission_success_age_seconds
                .is_some(),
            "a commit's admission must reach the reconcile probes as a success"
        );
    }

    /// A commit that never reached authority must not restamp the marker.
    ///
    /// The forced admission still runs on this path and still succeeds, but its
    /// tree is deferred to a transaction that was refused, so recording a
    /// complete admission here would claim freshness for a tree repository
    /// authority never accepted. The failure direction is the safe one: an
    /// unrefreshed marker reads as staler than the store is and never as
    /// fresher.
    ///
    /// A second commit on an unchanged tree is the refusal with no mocking in
    /// it. `refuse_a_successor_that_records_nothing` answers it 409 after the
    /// admission has already run, which is exactly the ordering under test. An
    /// empty workspace is not that case and was the first guess: the first
    /// commit of a freshly initialized store is accepted, so a test written on
    /// it asserts nothing about a refusal.
    ///
    /// The first commit's timestamp is the control. Asserting only that some
    /// marker exists afterwards would pass on a build that restamped on every
    /// request, which is the defect this guards.
    #[tokio::test]
    #[serial_test::serial(commit_phase_capture)]
    async fn a_commit_that_reaches_no_authority_records_no_admission() {
        use kin_core::last_admission::LastAdmissionRead;

        let state = test_state();
        let root = state.layout.working_dir();
        std::fs::write(root.join("committed.rs"), b"pub fn committed() {}\n").unwrap();

        let commit = |body: &'static str| {
            let app = router(Arc::clone(&state));
            app.oneshot(
                Request::post("/commands/commit")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        json!({
                            "operation_id": kin_model::OperationId::new(),
                            "timestamp": kin_model::Timestamp::now(),
                            "author": "Test Author <test@example.invalid>",
                            "message": body
                        })
                        .to_string(),
                    ))
                    .unwrap(),
            )
        };

        let accepted = commit("record the first admission").await.unwrap();
        assert_eq!(
            accepted.status(),
            StatusCode::OK,
            "the first commit must be accepted, or there is no marker to leave alone"
        );
        let stamped = match kin_core::last_admission::read(&state.layout) {
            LastAdmissionRead::Recorded(recorded) => recorded,
            other => panic!("the accepted commit must record its admission, read {other:?}"),
        };

        let refused = commit("commit the same tree again").await.unwrap();
        assert_eq!(
            refused.status(),
            StatusCode::CONFLICT,
            "a second commit on an unchanged tree must be refused, or this test is not \
             exercising a failed commit"
        );

        match kin_core::last_admission::read(&state.layout) {
            LastAdmissionRead::Recorded(after) => assert_eq!(
                after, stamped,
                "a commit that reached no authority must leave the freshness record exactly as \
                 the last complete admission left it"
            ),
            other => panic!("the refused commit must not have removed the record, read {other:?}"),
        }
    }

    #[cfg(unix)]
    #[tokio::test]
    async fn command_commit_preserves_complete_arbitrary_repository_tree() {
        use kin_model::RepositoryAuthorityStore as _;
        use std::os::unix::fs::{symlink, PermissionsExt as _};

        let state = test_state();
        let root = state.layout.working_dir();
        std::fs::create_dir_all(root.join("assets")).unwrap();
        std::fs::write(
            root.join("compose.yaml"),
            b"services:\n  app:\n    image: kin:test\n",
        )
        .unwrap();
        std::fs::write(root.join("Dockerfile"), b"FROM scratch\n").unwrap();
        let mut executable = std::fs::metadata(root.join("Dockerfile"))
            .unwrap()
            .permissions();
        executable.set_mode(0o755);
        std::fs::set_permissions(root.join("Dockerfile"), executable).unwrap();
        std::fs::write(root.join("assets/model.bin"), [0, 0xff, 0x41, 0]).unwrap();
        std::fs::write(
            root.join("deployment.kin-unknown"),
            b"opaque=still-repository-truth\n",
        )
        .unwrap();
        symlink("compose.yaml", root.join("current-compose")).unwrap();

        let generation_before = ActiveApiRepositoryAuthority::open(&state)
            .unwrap()
            .manager
            .read_authority()
            .roots()
            .generation;
        let app = router(Arc::clone(&state));
        let obsolete_dry_run = app
            .clone()
            .oneshot(
                Request::post("/commands/commit")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        json!({
                            "operation_id": kin_model::OperationId::new(),
                            "timestamp": kin_model::Timestamp::now(),
                            "author": "Test Author <test@example.invalid>",
                            "message": "obsolete dry run must not commit",
                            "dry_run": true
                        })
                        .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(obsolete_dry_run.status(), StatusCode::UNPROCESSABLE_ENTITY);
        assert_eq!(
            ActiveApiRepositoryAuthority::open(&state)
                .unwrap()
                .manager
                .read_authority()
                .roots()
                .generation,
            generation_before,
            "removed dry-run payload must fail before filesystem admission"
        );

        let response = app
            .oneshot(
                Request::post("/commands/commit")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        json!({
                            "operation_id": kin_model::OperationId::new(),
                            "timestamp": kin_model::Timestamp::now(),
                            "author": "Test Author <test@example.invalid>",
                            "message": "commit the complete arbitrary repository"
                        })
                        .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        let status = response.status();
        let body = axum::body::to_bytes(response.into_body(), 64 * 1024)
            .await
            .unwrap();
        assert_eq!(status, StatusCode::OK, "{}", String::from_utf8_lossy(&body));
        let response: serde_json::Value = serde_json::from_slice(&body).unwrap();
        assert_eq!(response["file_count"], 5);
        let change_id = kin_model::SemanticChangeId::from_hash(
            Hash256::from_hex(response["change_id"].as_str().unwrap()).unwrap(),
        );

        let authority = ActiveApiRepositoryAuthority::open(&state).unwrap();
        let lease = authority.manager.read_authority();
        let workspace = lease
            .metadata()
            .workspaces
            .iter()
            .find(|workspace| workspace.workspace_id == authority.workspace_id)
            .unwrap();
        assert_eq!(workspace.tree.len(), 5);
        assert_eq!(workspace.tree, state.graph.resolved_tree());
        assert_eq!(
            workspace
                .tree
                .artifact_at_path(&RepoPath::from_utf8("Dockerfile").unwrap())
                .unwrap()
                .entry,
            TreeEntry::blob(
                Hash256::from_bytes(kin_blobs::digest_bytes(b"FROM scratch\n")),
                true
            )
        );
        assert!(matches!(
            workspace
                .tree
                .artifact_at_path(&RepoPath::from_utf8("current-compose").unwrap())
                .unwrap()
                .entry,
            TreeEntry::Symlink { .. }
        ));
        assert_eq!(
            authority
                .manager
                .get_repository_ref(
                    &authority.repository_id,
                    lease.metadata().ref_state.default_ref.as_ref().unwrap(),
                )
                .unwrap()
                .unwrap()
                .target,
            kin_model::RefTarget::change(change_id)
        );
        assert!(lease
            .snapshot()
            .changes
            .iter()
            .any(|(_, change)| change.id == change_id));
    }

