    /// Every hit `semantic_locate` serves on a code store, unchanged.
    ///
    /// The healthy path is the thing a labeling change is most likely to break,
    /// so it is pinned first: a live entity still carries its graph entity id
    /// under `entity_id`, and now says which id space that is.
    #[test]
    fn a_live_entity_hit_keeps_its_entity_id_and_declares_the_entity_id_space() {
        let entity = test_entity("resolve_retrieval_key", "src/engine/graph.rs");
        let identity =
            locate_hit_identity(&kin_db::ResolvedRetrievalItem::Entity(entity.clone()), true)
                .expect("a live entity hit must be served");

        assert_eq!(
            identity.id_space,
            kin_cli::commands::locate::LocateIdSpace::Entity
        );
        assert_eq!(identity.entity_id.as_deref(), Some(&*entity.id.to_string()));
        assert_eq!(identity.file.as_deref(), Some("src/engine/graph.rs"));
        assert_eq!(identity.kind.as_deref(), Some("function"));

        let mut hit = json!({ "name": identity.name });
        write_locate_hit_identity(&mut hit, &identity);
        assert_eq!(hit["id_space"], json!("entity"));
        assert_eq!(hit["entity_id"], json!(entity.id.to_string()));
        assert!(
            hit.get("artifact_path").is_none(),
            "an entity hit must not carry artifact fields: {hit}"
        );
    }

    /// The reported defect, on the artifact-only store shape.
    ///
    /// An artifact-level embedding is a tracked file the parsers produced no
    /// entities for. It used to be served with its own path in a field named
    /// `entity_id`, which every id-consuming tool refuses, so an agent could
    /// only discover the id was dead by spending a call on it.
    #[test]
    fn an_artifact_hit_carries_no_entity_id_and_names_the_tool_that_reads_it() {
        let artifact = kin_db::ResolvedRetrievalItem::OpaqueArtifact(kin_model::OpaqueArtifact {
            file_id: kin_model::FilePathId::new("docs/design.md"),
            content_hash: Hash256::from_bytes([0x07; 32]),
            mime_type: Some("text/markdown".to_string()),
            text_preview: None,
        });
        let identity =
            locate_hit_identity(&artifact, false).expect("an artifact hit must still be served");

        assert_eq!(
            identity.id_space,
            kin_cli::commands::locate::LocateIdSpace::Artifact
        );
        assert_eq!(
            identity.entity_id, None,
            "an artifact hit has no entity id, and a path in that field is the defect"
        );
        assert_eq!(identity.name, "design.md");
        assert_eq!(identity.file.as_deref(), Some("docs/design.md"));
        // It still dedupes, on its path rather than on an id it does not have.
        assert_eq!(identity.dedupe_key(), "docs/design.md");

        let mut hit = json!({ "name": identity.name });
        write_locate_hit_identity(&mut hit, &identity);
        assert_eq!(hit["id_space"], json!("artifact"));
        assert!(
            hit.get("entity_id").is_none(),
            "the dead id must be absent, not merely labelled: {hit}"
        );
        assert_eq!(hit["artifact_path"], json!("docs/design.md"));
        assert_eq!(hit["resolves_with"], json!("kin_artifact_read"));
        assert!(hit["note"].as_str().unwrap().contains("get_entity_source"));
    }

    /// The second dead-id path, and the one that produced the ticket's title.
    ///
    /// A `RetrievalKey::EntityRevision` resolves through immutable revision
    /// history, and retiring an entity deliberately leaves that history in
    /// place, so a deleted entity's head revision still resolves to an `Entity`
    /// whose id names nothing the graph holds. That id is entity-SHAPED — a
    /// bare UUID — so no consumer can tell it from a live one. It must be
    /// dropped rather than served under any label.
    #[test]
    fn a_retired_entity_key_is_dropped_rather_than_served_as_a_dead_id() {
        let retired = test_entity("deleted_symbol", "src/gone.rs");
        assert!(
            locate_hit_identity(
                &kin_db::ResolvedRetrievalItem::Entity(retired.clone()),
                false
            )
            .is_none(),
            "an id the graph no longer holds must not reach a row"
        );
        // Falsification: the same item with liveness restored IS served, so the
        // assertion above is about liveness and not about the fixture.
        assert!(
            locate_hit_identity(&kin_db::ResolvedRetrievalItem::Entity(retired), true).is_some()
        );
    }

    /// The two id spaces are distinguishable in the output, which is the whole
    /// point: `EntityId` and `ArtifactId` are both bare UUID newtypes, so
    /// nothing about a rendered id says which space produced it.
    #[test]
    fn the_two_id_spaces_serialize_to_distinct_stable_tokens() {
        assert_eq!(
            kin_cli::commands::locate::LocateIdSpace::Entity.as_str(),
            "entity"
        );
        assert_eq!(
            kin_cli::commands::locate::LocateIdSpace::Artifact.as_str(),
            "artifact"
        );
        assert_eq!(
            serde_json::to_value(kin_cli::commands::locate::LocateIdSpace::Artifact).unwrap(),
            json!("artifact"),
            "the enum and the emitted token must be one spelling"
        );
    }

    /// The gap `kin admit` exists to close: a working tree the daemon holds no
    /// watcher event for, and therefore never admits on its own.
    ///
    /// The files are written to disk only. Nothing admits them, which is
    /// precisely the state a store lands in when ingest was interrupted or when
    /// a rule change made previously-excluded content admissible, and the
    /// daemon has been quiet since.
    #[tokio::test]
    async fn admit_admits_a_complete_tree_no_watcher_event_ever_named() {
        let state = test_state();
        state
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);
        for (path, content) in [
            ("docs/design.md", &b"# design\n"[..]),
            (".github/workflows/ci.yml", &b"name: ci\n"[..]),
            ("scripts/deploy.sh", &b"#!/bin/sh\necho deploy\n"[..]),
        ] {
            install_working_copy_file(&state, path, content, false);
        }

        // Precondition, so a pass that admitted nothing cannot read as success:
        // none of this is tracked yet.
        let before = tracked_paths(&state);
        assert!(
            !before.contains("docs/design.md"),
            "the fixture admitted the tree before the command ran: {before:?}"
        );

        let app = router(Arc::clone(&state));
        let (_, response) = admit_through_api(&app).await;

        assert_eq!(response["report"]["admitted"], json!(true));
        assert_eq!(response["mutated"], json!(true));
        let after = tracked_paths(&state);
        for path in [
            "docs/design.md",
            ".github/workflows/ci.yml",
            "scripts/deploy.sh",
        ] {
            assert!(after.contains(path), "{path} was not admitted: {after:?}");
        }
        assert_eq!(
            response["report"]["tracked_before"],
            json!(before.len()),
            "the report must name the tree it started from"
        );
        assert_eq!(response["report"]["tracked_after"], json!(after.len()));

        // A second pass observes the same tree and has nothing to do. This is
        // what makes the route safe on the retrying poster the CLI uses.
        let (_, replay) = admit_through_api(&app).await;
        assert_eq!(replay["report"]["admitted"], json!(true));
        assert_eq!(replay["mutated"], json!(false));
        assert_eq!(
            replay["report"]["tracked_before"],
            replay["report"]["tracked_after"]
        );
    }

    /// A request that hangs up mid-pass must never become a retry that reports a
    /// complete admission.
    ///
    /// The seam publishes repository authority before it enriches and has one
    /// await between the two, so a client timeout could cancel the pass exactly
    /// there, leaving the tree admitted with nothing parsed for it. Nothing
    /// re-enriches a file that did not change, so the next request observed a
    /// settled tree, found no deltas, and answered with a complete admission
    /// that had skipped every entity in the backlog.
    ///
    /// This drives that sequence: the pass is parked at its one await, the
    /// request waiting on it is dropped, and the attempt that follows has to
    /// report the real transition rather than an empty one.
    #[tokio::test]
    async fn a_client_timeout_mid_pass_never_lets_a_retry_report_a_complete_admission() {
        let state = test_state();
        state
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);
        install_working_copy_file(
            &state,
            "src/admitted.rs",
            b"pub fn admitted() -> u8 {\n    7\n}\n",
            false,
        );

        // Precondition: nothing is admitted and nothing is enriched, so neither
        // half of the assertion below can pass on the fixture.
        assert!(tracked_paths(&state).is_empty(), "the fixture pre-admitted");
        assert_eq!(state.graph.entity_count(), 0);

        // The seam's single await is the reconciler write lock, so holding it
        // parks the pass precisely where a hang-up used to cancel it.
        let held = state.reconciler.write().await;

        let mut abandoned = Box::pin(crate::repository_admit::execute(&state));
        let mut context = std::task::Context::from_waker(std::task::Waker::noop());
        assert!(
            std::future::Future::poll(abandoned.as_mut(), &mut context).is_pending(),
            "the request must be waiting on a pass rather than running one"
        );
        // The client hung up: an HTTP timeout, or an interrupt.
        drop(abandoned);

        let retry = tokio::spawn({
            let state = Arc::clone(&state);
            async move { crate::repository_admit::execute(&state).await }
        });
        // Let the abandoned pass and the retry both reach the lock this test
        // holds before releasing it.
        tokio::task::yield_now().await;
        tokio::task::yield_now().await;
        drop(held);

        let response = retry.await.unwrap().expect("the pass reported an outcome");
        let report = response.report.expect("a reported pass carries its report");
        assert!(report.admitted, "{:?}", report.failure);
        assert!(
            tracked_paths(&state).contains("src/admitted.rs"),
            "the abandoned request took its own admission down with it"
        );
        assert!(
            report.entities_after > 0,
            "an admission whose enrichment was skipped read as complete: {report:?}"
        );
        assert!(
            response.mutated,
            "the pass moved the graph and the report denied it: {report:?}"
        );
    }

    /// A daemon whose admission seam would decline to run has to refuse, not
    /// report.
    ///
    /// The seam returns without running when filesystem reconcile is disabled,
    /// and that silent skip is indistinguishable from a pass that ran and found
    /// a settled tree. Answering it with a report would stamp a successful
    /// admission on the probes every health surface reads, on a daemon where no
    /// admission can happen at all, while the locate degradation added beside
    /// this command tells the operator to run exactly this.
    #[tokio::test]
    async fn an_admission_refuses_on_a_daemon_whose_seam_would_silently_skip() {
        let state = test_state();
        state
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);
        install_working_copy_file(&state, "docs/notes.md", b"notes\n", false);
        state
            .filesystem_reconcile_disabled
            .store(true, std::sync::atomic::Ordering::Relaxed);

        let response = router(Arc::clone(&state))
            .oneshot(admit_request())
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::CONFLICT);
        let body = axum::body::to_bytes(response.into_body(), 64 * 1024)
            .await
            .unwrap();
        let refusal: serde_json::Value = serde_json::from_slice(&body).unwrap();
        assert_eq!(refusal["error"], json!("filesystem_admission_disabled"));
        assert_eq!(refusal["mutation_applied"], json!(false));

        // The refusal has to leave the health surfaces telling the truth: no
        // admission succeeded here, because none ran.
        let probes = state
            .background_work
            .reconcile()
            .report(std::time::Instant::now());
        assert!(
            probes.last_admission_success_age_seconds.is_none(),
            "a refused request stamped a successful admission on the probes"
        );
        assert!(tracked_paths(&state).is_empty());
    }

    /// The seam's other silent skip. A bare Git repository has no working copy
    /// to admit, so the pass returns without running, and the refusal is what
    /// keeps that from reading as an admission that succeeded.
    ///
    /// The predicate is asked here rather than shared with the seam, so this
    /// pins both directions: an ordinary working directory is admitted, and one
    /// carrying a bare repository's own layout is refused.
    #[tokio::test]
    async fn an_admission_refuses_on_a_bare_repository_the_seam_would_skip() {
        let state = test_state();
        state
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);
        assert!(
            admission_seam_would_skip(&state).is_none(),
            "the fixture already refuses, so this cannot discriminate"
        );

        let working_dir = state.layout.working_dir().to_path_buf();
        std::fs::write(working_dir.join("config"), b"[core]\n\tbare = true\n").unwrap();
        std::fs::create_dir_all(working_dir.join("objects")).unwrap();
        std::fs::create_dir_all(working_dir.join("refs")).unwrap();
        let git = working_dir.join(".git");
        if git.is_dir() {
            std::fs::remove_dir_all(&git).unwrap();
        } else if git.exists() {
            std::fs::remove_file(&git).unwrap();
        }

        let response = router(Arc::clone(&state))
            .oneshot(admit_request())
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::CONFLICT);
        let body = axum::body::to_bytes(response.into_body(), 64 * 1024)
            .await
            .unwrap();
        let refusal: serde_json::Value = serde_json::from_slice(&body).unwrap();
        assert_eq!(
            refusal["error"],
            json!("bare_repository_has_no_working_copy")
        );

        let probes = state
            .background_work
            .reconcile()
            .report(std::time::Instant::now());
        assert!(
            probes.last_admission_success_age_seconds.is_none(),
            "a refused request stamped a successful admission on the probes"
        );
    }

    /// A requested admission has to reach the probes the health surfaces read.
    ///
    /// `kin graph status` and `/health` both answer from `ReconcileHealth`, so
    /// an operator's own recovery pass being the one admission those surfaces
    /// cannot see would reproduce the blindness the probes were added to fix.
    #[tokio::test]
    async fn admit_records_its_pass_on_the_probes_the_health_surfaces_read() {
        let state = test_state();
        state
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);
        install_working_copy_file(&state, "docs/notes.md", b"notes\n", false);

        // Precondition: nothing has recorded a successful admission yet, so the
        // assertion below cannot pass on a pre-existing mark.
        let before = state
            .background_work
            .reconcile()
            .report(std::time::Instant::now());
        assert!(
            before.last_admission_success_age_seconds.is_none(),
            "the fixture recorded an admission before the command ran"
        );

        let app = router(Arc::clone(&state));
        let (_, response) = admit_through_api(&app).await;
        assert_eq!(response["report"]["admitted"], json!(true));
        assert!(
            response["report"]["reconcile"]["last_admission_success_age_seconds"].is_number(),
            "the response must carry the probe reading: {response}"
        );

        let after = state
            .background_work
            .reconcile()
            .report(std::time::Instant::now());
        assert!(
            after.last_admission_success_age_seconds.is_some(),
            "the pass did not reach the probes the health surfaces read"
        );
        assert_eq!(after.admission_failure_streak, 0);
    }

    /// The idle window is what would otherwise end a long pass, so the lease the
    /// CLI takes has to be the thing that suppresses it.
    ///
    /// `kin admit` registers a session before its request and releases it after.
    /// This pins the daemon-side half of that contract: a CLI-vendored session
    /// makes the daemon ineligible for idle shutdown, and ending it restores
    /// eligibility so the lease cannot keep a daemon awake forever.
    #[tokio::test]
    async fn a_cli_session_suppresses_the_idle_shutdown_that_would_end_an_admission() {
        let state = test_state();
        state
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);
        assert!(
            !state.has_external_sessions(),
            "the fixture already held a session, so this cannot discriminate"
        );

        let app = router(Arc::clone(&state));
        let response = app
            .clone()
            .oneshot(
                Request::post("/session")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        json!({
                            "vendor": kin_cli::commands::admit::ADMIT_SESSION_VENDOR,
                            "client_name": kin_cli::commands::admit::ADMIT_SESSION_CLIENT,
                            "transport": "cli",
                            "pid": std::process::id(),
                            "cwd": state.layout.working_dir().display().to_string(),
                        })
                        .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = axum::body::to_bytes(response.into_body(), 64 * 1024)
            .await
            .unwrap();
        let started: serde_json::Value = serde_json::from_slice(&body).unwrap();
        let session_id = started["session_id"].as_str().unwrap().to_string();

        assert!(
            state.has_external_sessions(),
            "a kin-cli session must pin the daemon against idle shutdown"
        );

        let response = app
            .oneshot(
                Request::delete(format!("/session/{session_id}"))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        assert!(
            !state.has_external_sessions(),
            "releasing the lease must restore idle eligibility"
        );
    }

    /// A default exclude alone retires nothing, because ignore rules never hide
    /// tracked identity. The purge is what retires the backlog, and the removal
    /// has to be in authority rather than only in the live graph.
    #[tokio::test]
    async fn purge_ignored_untracks_admitted_derived_output_and_survives_restart() {
        let state = test_state();
        state
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);
        let layout = state.layout.clone();

        for (path, content) in [
            ("src/lib.rs", &b"pub fn kept() {}"[..]),
            ("target/debug/app.o", &b"derived"[..]),
            ("target/debug/deps/lib.rlib", &b"derived"[..]),
        ] {
            install_working_copy_file(&state, path, content, false);
            install_repository_file(&state, path, content);
        }
        let app = router(Arc::clone(&state));

        // Precondition: the derived output really is tracked, so the assertions
        // below cannot pass because it was never admitted.
        assert!(tracked_paths(&state).contains("target/debug/app.o"));

        let (_, dry) = purge_ignored_through_api(&app, false).await;
        assert_eq!(dry["mutated"], json!(false));
        assert_eq!(dry["report"]["purge_count"], json!(2));
        assert_eq!(dry["report"]["tracked_total"], json!(3));
        assert_eq!(dry["report"]["retained_total"], json!(1));
        assert_eq!(dry["report"]["applied"], json!(false));
        assert_eq!(dry["report"]["kinignore_present"], json!(false));
        assert_eq!(
            dry["report"]["sample_paths"],
            json!(["target/debug/app.o", "target/debug/deps/lib.rlib"])
        );
        assert!(
            tracked_paths(&state).contains("target/debug/app.o"),
            "a dry run untracked a path"
        );

        let (_, applied) = purge_ignored_through_api(&app, true).await;
        assert_eq!(applied["mutated"], json!(true));
        assert_eq!(applied["report"]["applied"], json!(true));
        assert_eq!(applied["report"]["purge_count"], json!(2));
        assert!(applied["report"]["authority_generation"].is_number());

        let live = tracked_paths(&state);
        assert!(live.contains("src/lib.rs"));
        assert!(!live.contains("target/debug/app.o"));
        assert!(!live.contains("target/debug/deps/lib.rlib"));

        // The files are still on disk. Only tracking was retired.
        assert!(layout.working_dir().join("target/debug/app.o").exists());

        // Restart: a fresh daemon rebuilds its graph from persisted authority,
        // so this fails if the purge only moved the in-memory view.
        drop(app);
        drop(state);
        let restarted = Arc::new(DaemonState::open(layout).unwrap());
        let after_restart = tracked_paths(&restarted);
        assert!(after_restart.contains("src/lib.rs"));
        assert!(
            !after_restart.contains("target/debug/app.o"),
            "the purge did not survive a restart: {after_restart:?}"
        );
        assert!(!after_restart.contains("target/debug/deps/lib.rlib"));
    }

    /// A repository that states `!target` keeps its build output tracked, so the
    /// purge set is driven by the repository's rules and not by a hardcoded list.
    #[tokio::test]
    async fn purge_ignored_honors_a_readmitted_default() {
        let state = test_state();
        state
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);
        install_working_copy_file(&state, ".kinignore", b"!target\n", false);
        install_repository_file(&state, ".kinignore", b"!target\n");
        install_working_copy_file(&state, "target/debug/app.o", b"derived", false);
        install_repository_file(&state, "target/debug/app.o", b"derived");
        let app = router(Arc::clone(&state));

        let (_, dry) = purge_ignored_through_api(&app, false).await;
        assert_eq!(dry["report"]["purge_count"], json!(0));
        assert_eq!(dry["report"]["kinignore_present"], json!(true));
        assert!(dry["lines"]
            .as_array()
            .unwrap()
            .iter()
            .any(|line| line.as_str().unwrap().contains("Nothing to purge.")));

        let (_, applied) = purge_ignored_through_api(&app, true).await;
        assert_eq!(applied["mutated"], json!(false));
        assert!(tracked_paths(&state).contains("target/debug/app.o"));
    }

    /// Untracking is not enough. Entities are what rank, so a purge that left
    /// them behind produced the worst reading of all: the artifact listing no
    /// longer names the file while search and locate still return it.
    #[tokio::test]
    async fn purge_ignored_evicts_the_entities_that_made_a_path_rank() {
        let state = test_state();
        state
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);

        // The rule lands after the admission, which is the whole scenario: a
        // repository that already carries a path is told to stop carrying it.
        for (path, content) in [
            (
                "investor/deck/build_deck.py",
                &b"def valuation(): pass\n"[..],
            ),
            ("src/lib.py", &b"def kept(): pass\n"[..]),
            (".kinignore", &b"investor\n"[..]),
        ] {
            install_working_copy_file(&state, path, content, false);
            install_repository_file(&state, path, content);
        }

        let private = test_entity("valuation", "investor/deck/build_deck.py");
        let kept = test_entity("kept", "src/lib.py");
        state.graph.upsert_entity(&private).unwrap();
        state.graph.upsert_entity(&kept).unwrap();
        assert!(state.graph.get_entity(&private.id).unwrap().is_some());

        let app = router(Arc::clone(&state));
        let (_, applied) = purge_ignored_through_api(&app, true).await;
        assert_eq!(applied["report"]["purge_count"], json!(1));

        let live = tracked_paths(&state);
        assert!(!live.contains("investor/deck/build_deck.py"));
        assert!(
            state.graph.get_entity(&private.id).unwrap().is_none(),
            "a purged path's entity still resolves, so it still ranks"
        );
        assert!(state
            .graph
            .query_entities(&kin_db::EntityFilter {
                file_path: Some(kin_model::FilePathId::new("investor/deck/build_deck.py")),
                ..Default::default()
            })
            .unwrap()
            .is_empty());

        // The two-sided arm: an unnamed sibling keeps both its artifact and its
        // entity, so the purge removed one path rather than clearing the graph.
        assert!(live.contains("src/lib.py"));
        assert_eq!(state.graph.get_entity(&kept.id).unwrap(), Some(kept));
    }

    fn branch_change(state: &DaemonState) -> SemanticChangeId {
        let authority = ActiveApiRepositoryAuthority::open(state).unwrap();
        let lease = authority.manager.read_authority();
        let target = lease
            .metadata()
            .workspaces
            .iter()
            .find(|workspace| workspace.workspace_id == authority.workspace_id)
            .unwrap()
            .base_target
            .clone()
            .unwrap();
        lease.resolve_target_change_id(&target).unwrap()
    }

    /// A rollback derives the policy for the tree it restores, and it has to
    /// derive it through the entry point that reads a tracked `.kin-allowances`.
    ///
    /// Reverting `repository_rollback::plan_and_commit`'s derivation to
    /// `derive_from_tree` fails here, because the compatibility entry point
    /// refuses by name the moment the restored tree carries approvals it cannot
    /// read. That is the shape this covers: an approval a reviewer accepted,
    /// silently dropped by rolling back to the very change that carried it.
    ///
    /// The approval rides the FIRST change, because rollback derives from the
    /// target tree rather than from the tree it is leaving. The approved body is
    /// harmless for the same reason it is in the sealed-tree test: this asks
    /// whether the derivation reads the approval, and approving a real secret
    /// would pull in authority's separate rule about repository CAS ordering.
    #[tokio::test]
    async fn rolling_back_derives_the_approvals_the_restored_tree_carries() {
        let state = test_state();
        state
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);
        let root = state.layout.working_dir().to_path_buf();
        let app = router(Arc::clone(&state));

        let approved_body = b"def normalize(term):\n    return term.strip()\n";
        let approved_digest = Hash256::from_bytes(state.blobs.write(approved_body).unwrap().0);
        std::fs::create_dir_all(root.join("notekeeper")).unwrap();
        std::fs::write(root.join("notekeeper/client.py"), approved_body).unwrap();
        let approvals = format!(
            "# approvals for this fixture\n\
             kin-allowances 1\n\
             notekeeper/client.py\t{approved_digest}\tblob\tcredscan@firelock.ai\tpinned by \
             the test covering the restored-tree derivation site\n"
        );
        std::fs::write(root.join(".kin-allowances"), approvals.as_bytes()).unwrap();
        let restored = commit_through_api(
            &app,
            kin_model::OperationId::new(),
            "publish a tree carrying an approval",
        )
        .await;

        std::fs::write(
            root.join("notekeeper/client.py"),
            b"def normalize(term):\n    return term\n",
        )
        .unwrap();
        let regression =
            commit_through_api(&app, kin_model::OperationId::new(), "publish a regression").await;
        assert_eq!(branch_change(&state), regression);

        let (status, body) =
            rollback_through_api(&app, kin_model::OperationId::new(), restored).await;
        assert_eq!(
            status,
            StatusCode::OK,
            "rolling back to a tree carrying .kin-allowances must derive its approvals rather \
             than refusing: {body}"
        );
        // A rollback publishes a NEW change that restores the old tree rather
        // than moving the branch back onto the old id, so the branch must have
        // left the regression without landing on `restored` itself.
        let after = branch_change(&state);
        assert_ne!(
            after, regression,
            "the rollback must move the branch off the regression"
        );
        assert_ne!(
            after, restored,
            "a rollback publishes a restoring change rather than re-pointing at the old one"
        );

        let authority = ActiveApiRepositoryAuthority::open(&state).unwrap();
        let lease = authority.manager.read_authority();
        let carried = lease
            .metadata()
            .workspaces
            .iter()
            .find(|workspace| workspace.workspace_id == authority.workspace_id)
            .expect("the bound workspace survives the rollback")
            .shared_admission_policy
            .sensitive_allowances
            .clone();
        assert_eq!(
            carried.len(),
            1,
            "the restored policy must carry the tree's one approval: {carried:?}"
        );
        assert_eq!(carried[0].content_hash, approved_digest);
    }

    /// The daemon's generation counter and the authority's, read together with
    /// a control proving the read itself does not move the counter.
    ///
    /// Reading `roots().generation` requires opening authority, and that open
    /// could advance the counter and manufacture the equality a caller is
    /// testing for. So the counter is read bare, then through the open, then
    /// bare again, and the three must agree. Lane vcsreads added this control to
    /// the probe that produced these assertions, and without it the pair is
    /// unfalsifiable in the same way an unmeasured fixture is.
    ///
    /// Deliberately NOT `#[cfg(unix)]`. Two of its three callers are, because
    /// they build fixtures through `universal_branch_test_state`, which is;
    /// the rollback arm builds its own and has compiled on Windows since it
    /// was written. Gating this helper alongside the two made the third arm
    /// call a function that is absent on Windows, which is a compile error
    /// rather than a test failure, so the whole leg graded nothing. Both
    /// symbols it touches are ungated: `DaemonState::snapshot_generation`
    /// and `ActiveApiRepositoryAuthority::open`.
    fn generation_pair(state: &Arc<DaemonState>) -> (u64, u64) {
        use std::sync::atomic::Ordering::SeqCst;
        let bare = state.snapshot_generation.load(SeqCst);
        let authority = ActiveApiRepositoryAuthority::open(state).unwrap();
        let through_open = state.snapshot_generation.load(SeqCst);
        let roots = authority.manager.read_authority().roots().generation;
        drop(authority);
        let bare_after = state.snapshot_generation.load(SeqCst);
        assert_eq!(
            bare, through_open,
            "opening authority moved the daemon generation counter, so this read cannot be \
             evidence about what a publication did to it"
        );
        assert_eq!(
            through_open, bare_after,
            "the daemon generation counter moved while authority was held open, so this read \
             cannot be evidence about what a publication did to it"
        );
        (bare, roots)
    }

    #[cfg(unix)]
    #[tokio::test]
    #[serial_test::serial(repository_commit)]
    async fn ambient_admission_preserves_open_merge_restore_generation_across_restart() {
        let (state, layout, repository, _, _) = universal_branch_test_state("ambient-open-merge");
        let path = repository.join("selected/compose.yaml");
        let original = b"services:\n  api:\n    image: main-conflict\n";
        std::fs::write(&path, original).unwrap();
        let app = router(Arc::clone(&state));
        commit_through_api(
            &app,
            kin_model::OperationId::new(),
            "create a real conflict",
        )
        .await;
        let response = crate::repository_merge::execute(
            &state,
            &kin_cli::commands::merge::MergeRequest {
                source: kin_model::RefName::branch(b"feature").unwrap(),
                operation_id: kin_model::OperationId::new(),
                actor: AuthorId::new("ambient-merge-test"),
            },
        )
        .unwrap_or_else(|refusal| {
            panic!(
                "fixture merge refused: {}",
                axum::response::IntoResponse::into_response(refusal).status()
            )
        });
        assert!(matches!(
            response.report.unwrap().outcome,
            kin_cli::commands::merge::MergeOutcome::Conflicted
        ));
        let before = cached_authority_admission_entry(&state).unwrap();
        assert!(
            before.open_merge.is_some(),
            "the fixture must hold a durable open merge"
        );
        let expected_tree = state.graph.resolved_tree();
        let authored = b"services:\n  api:\n    image: hand-authored-resolution\n";
        std::fs::write(&path, authored).unwrap();
        let observation =
            std::iter::once(RepoPath::from_utf8("selected/compose.yaml").unwrap()).collect();
        let yielded = crate::loop_runner::ambient_admission_for_test(&state, &observation).unwrap();
        assert_eq!(
            cached_authority_admission_entry(&state).unwrap().roots,
            before.roots,
            "an ambient conflict edit must not advance the merge restore generation"
        );
        assert!(yielded, "the watcher must retain the unadmitted event");
        assert_eq!(state.graph.resolved_tree(), expected_tree);
        assert_eq!(std::fs::read(&path).unwrap(), authored);
        drop(app);
        drop(state);

        let state = Arc::new(DaemonState::open(layout).unwrap());
        assert!(crate::loop_runner::ambient_admission_for_test(&state, &observation).unwrap());
        assert_eq!(
            cached_authority_admission_entry(&state).unwrap().roots,
            before.roots
        );
        assert_eq!(state.graph.resolved_tree(), expected_tree);
        // Restore the projection before aborting; this test exercises the
        // ambient gate independently of custom-resolution projection policy.
        std::fs::write(&path, original).unwrap();
        crate::repository_merge_state::execute_resolve(
            &state,
            &kin_cli::commands::resolve::ResolveRequest {
                operation_id: kin_model::OperationId::new(),
                actor: AuthorId::new("ambient-merge-test"),
                action: kin_cli::commands::resolve::ResolveAction::Abort,
                expected_record: None,
            },
        )
        .unwrap_or_else(|refusal| {
            panic!(
                "fixture abort refused: {}",
                axum::response::IntoResponse::into_response(refusal).status()
            )
        });
        assert!(!cached_authority_has_open_merge(&state).unwrap());
        std::fs::write(&path, authored).unwrap();
        let after_abort = cached_authority_admission_entry(&state)
            .unwrap()
            .roots
            .generation;
        assert!(!crate::loop_runner::ambient_admission_for_test(&state, &observation).unwrap());
        assert_eq!(
            cached_authority_admission_entry(&state)
                .unwrap()
                .roots
                .generation,
            after_abort + 1,
            "the retained observation must admit normally after the merge closes"
        );
        assert_ne!(state.graph.resolved_tree(), expected_tree);
    }

    /// A merge published through `resolve --continue` must reach the live graph
    /// too, and this is the arm the plain-merge one below cannot cover.
    ///
    /// The two merge publications are different code: `publish` authors a clean
    /// merge, `publish_resolved_merge` publishes one whose conflicts were
    /// settled. kin#1287 installs on both. The plain-merge arm below drives only
    /// the first, proven by its own mutation grid: removing the first install
    /// leaves that arm GREEN. So this arm exists because a grid said the other
    /// one does not cover it, rather than because two arms felt tidier.
    ///
    /// The fixture is the work here. Both sides must edit the SAME artifact, or
    /// the merge is clean, `publish` runs, and this arm silently grades the
    /// path the other arm already covers. `selected/compose.yaml` is written by
    /// the fixture on main and rewritten on feature, so editing it again on the
    /// active branch after the split is what makes the conflict real.
    #[cfg(unix)]
    #[tokio::test]
    #[serial_test::serial(repository_commit)]
    async fn a_merge_published_through_resolve_reaches_the_live_graph_without_a_restart() {
        let (state, _layout, repository, _base_change, _feature_change) =
            universal_branch_test_state("resolve-live-graph");
        let app = router(Arc::clone(&state));

        // Conflict on purpose: the feature branch rewrote this same file.
        std::fs::write(
            repository.join("selected/compose.yaml"),
            b"services:\n  api:\n    image: active-branch-after-the-split\n",
        )
        .unwrap();
        let pre_merge = commit_through_api(
            &app,
            kin_model::OperationId::new(),
            "edit the file the other side also changed",
        )
        .await;

        // PRECONDITION, proved: the projection is populated before publication.
        state
            .graph
            .resolve_graph_at(&pre_merge)
            .unwrap_or_else(|error| {
                panic!(
                    "NOT RUN, precondition unmet rather than property refuted: the projection \
                     could not replay to the pre-merge change: {error}"
                )
            });

        let backend = state.local_repository_backend().unwrap();
        let repository_id = state
            .local_repository_authority_binding()
            .unwrap()
            .repository_id()
            .clone();
        let identity_before = read_local_publication_identity(&backend, &repository_id).unwrap();
        let (counter_before, roots_before) = generation_pair(&state);

        let post = |path: &'static str, body: Vec<u8>| {
            let app = router(Arc::clone(&state));
            async move {
                let response = app
                    .oneshot(
                        Request::post(path)
                            .header("content-type", "application/json")
                            .body(Body::from(body))
                            .unwrap(),
                    )
                    .await
                    .unwrap();
                let status = response.status();
                let bytes = axum::body::to_bytes(response.into_body(), 512 * 1024)
                    .await
                    .unwrap();
                (status, bytes.to_vec())
            }
        };

        let merge = kin_cli::commands::merge::MergeRequest {
            source: kin_model::RefName::branch(b"feature").unwrap(),
            operation_id: kin_model::OperationId::new(),
            actor: AuthorId::new("resolve-live-graph-test"),
        };
        let (_merge_status, merge_body) =
            post("/commands/merge", serde_json::to_vec(&merge).unwrap()).await;
        let merge_response: kin_cli::commands::merge::MergeResponse =
            serde_json::from_slice(&merge_body).unwrap();
        // The merge must have CONFLICTED, or this arm drove `publish` and covers
        // nothing the plain-merge arm does not.
        //
        // Keyed on the outcome rather than on `mutated`, which was the first
        // thing tried and is wrong: a conflicted merge reports `mutated: true`
        // because it wrote the merge transaction record, so `!mutated` refuses a
        // run that conflicted exactly as intended. The response carries the
        // answer directly and there is no reason to infer it from a side effect.
        let outcome = merge_response
            .report
            .as_ref()
            .map(|report| report.outcome)
            .expect("the merge response must carry a report to read its outcome from");
        assert!(
            matches!(outcome, kin_cli::commands::merge::MergeOutcome::Conflicted),
            "NOT RUN, precondition unmet: the merge reported {outcome:?} rather than Conflicted, \
             so this arm drove `publish` rather than `publish_resolved_merge` and covers nothing \
             the plain-merge arm does not: {}",
            String::from_utf8_lossy(&merge_body)
        );

        let settle = kin_cli::commands::resolve::ResolveRequest {
            operation_id: kin_model::OperationId::new(),
            actor: AuthorId::new("resolve-live-graph-test"),
            action: kin_cli::commands::resolve::ResolveAction::Settle {
                directives: Vec::new(),
                all: Some(kin_model::MergeSide::Theirs),
            },
            expected_record: None,
        };
        let (settle_status, settle_body) =
            post("/commands/resolve", serde_json::to_vec(&settle).unwrap()).await;
        assert_eq!(
            settle_status,
            StatusCode::OK,
            "settling every conflict from one side must succeed: {}",
            String::from_utf8_lossy(&settle_body)
        );

        let continue_request = kin_cli::commands::resolve::ResolveRequest {
            operation_id: kin_model::OperationId::new(),
            actor: AuthorId::new("resolve-live-graph-test"),
            action: kin_cli::commands::resolve::ResolveAction::Continue,
            expected_record: None,
        };
        let (continue_status, continue_body) = post(
            "/commands/resolve",
            serde_json::to_vec(&continue_request).unwrap(),
        )
        .await;
        assert_eq!(
            continue_status,
            StatusCode::OK,
            "the resolved merge must publish for this arm to grade anything: {}",
            String::from_utf8_lossy(&continue_body)
        );

        let published = branch_change(&state);
        assert_ne!(
            published, pre_merge,
            "the resolved merge must move the branch off its pre-merge change"
        );

        // The property, through the LIVE projection and owning the absence, so
        // a missing change is reported as missing rather than mapped onto a
        // parent count that reads like a publication of the wrong kind.
        let held = state.graph.get_change(&published).unwrap().expect(
            "the live graph does not hold the change `resolve --continue` just published, so \
             every read that replays the graph to it fails until the daemon restarts; authority \
             holds it and the derived query view does not",
        );
        assert_eq!(
            held.parents.len(),
            2,
            "NOT RUN, precondition unmet: the published change carries {} parent(s) rather than \
             two, so it is not a merge change",
            held.parents.len()
        );
        state
            .graph
            .resolve_graph_at(&published)
            .expect("a graph holding the published merge change must replay to it");

        // OVER-INVALIDATION guard.
        state.graph.resolve_graph_at(&pre_merge).expect(
            "the graph can no longer replay to a change it held before the merge, so the \
             projection was discarded rather than added to",
        );

        let identity_after = read_local_publication_identity(&backend, &repository_id).unwrap();
        let (counter_after, roots_after) = generation_pair(&state);
        // The daemon's counter moves by exactly what the authority's generation
        // moves across a publication. Both are asserted rather than only their
        // equality afterwards, because equal-after is consistent with two very
        // different worlds: something advances the counter on a publish, or the
        // counter and the roots both sat still. Only the DELTA separates them,
        // which is the same reason a cgroup's oom_kill cannot separate a cap
        // kill from an outside one while max and oom can.
        //
        // Measured by lane vcsreads before this became an assertion: counter 2
        // to 3 and roots 2 to 3 across a merge publish. The advancing site is
        // `finalize_local_repository_commit` calling
        // `record_repository_authority_commit` at `state.rs:9062` under its CAS
        // condition, reached from `repository_merge.rs:121` and
        // `repository_rollback.rs:91`, which is one level above where a
        // call-site count looks.
        assert!(
            roots_after > roots_before,
            "the authority generation did not move across this publication, so the counter \
             assertion below would grade a publication that did not happen"
        );
        assert_eq!(
            counter_after - counter_before,
            roots_after - roots_before,
            "the daemon generation counter moved by {} while the authority generation moved by \
             {}; they must move together, and a counter left behind is what makes every \
             freshness guard reading it refuse or pass wrongly",
            counter_after - counter_before,
            roots_after - roots_before
        );
        assert!(
            identity_before != identity_after,
            "the publication identity did not move across a resolved-merge publication"
        );
    }

    /// A published MERGE must reach the live graph too, by the same contract
    /// and with the same three guards as the rollback arm below.
    ///
    /// Its own arm rather than a second assertion in that one, because the two
    /// publications reach the live graph through different code: kin#1287
    /// installs on both merge publish paths, `publish` and
    /// `publish_resolved_merge`, and this drives the first. A single arm
    /// covering both would go red without saying which path regressed.
    ///
    /// The precondition is proved rather than assumed for the reason the
    /// rollback arm states: a daemon whose projection was never populated holds
    /// the change either way, so a check that publishes into an empty
    /// projection passes on the unpatched binary.
    #[cfg(unix)]
    #[tokio::test]
    #[serial_test::serial(repository_commit)]
    async fn a_published_merge_reaches_the_live_graph_without_a_restart() {
        let (state, _layout, repository, _base_change, _feature_change) =
            universal_branch_test_state("merge-live-graph");
        let app = router(Arc::clone(&state));

        // Diverge the active branch AFTER the split, so the merge must author a
        // merge change rather than fast-forwarding. Without this the merge moves
        // the ref onto the feature change, publishes nothing, and every
        // assertion below passes on a binary with the install removed: measured,
        // this arm survived all three mutations of the merge-side installs until
        // the divergence was added.
        std::fs::write(
            repository.join("selected/diverge.txt"),
            b"a change on the active branch after the split\n",
        )
        .unwrap();
        let main_change = commit_through_api(
            &app,
            kin_model::OperationId::new(),
            "diverge the active branch so the merge is not a fast-forward",
        )
        .await;

        // PRECONDITION, proved: this daemon's projection is populated before the
        // publication. A failure here is NOT a verdict on the property.
        state
            .graph
            .resolve_graph_at(&main_change)
            .unwrap_or_else(|error| {
                panic!(
                    "NOT RUN, precondition unmet rather than property refuted: the projection \
                     could not replay to the pre-merge change, so publishing into it proves \
                     nothing: {error}"
                )
            });

        let backend = state.local_repository_backend().unwrap();
        let repository_id = state
            .local_repository_authority_binding()
            .unwrap()
            .repository_id()
            .clone();
        let identity_before = read_local_publication_identity(&backend, &repository_id).unwrap();
        let (counter_before, roots_before) = generation_pair(&state);
        // CONTROL: two reads with no publication between must be the SAME, or
        // the comparison below cannot be evidence that a publication moved it.
        let identity_again = read_local_publication_identity(&backend, &repository_id).unwrap();
        assert!(
            identity_before == identity_again,
            "the publication identity differs between two reads with no publication between them"
        );

        let request = kin_cli::commands::merge::MergeRequest {
            source: kin_model::RefName::branch(b"feature").unwrap(),
            operation_id: kin_model::OperationId::new(),
            actor: AuthorId::new("merge-live-graph-test"),
        };
        let response = router(Arc::clone(&state))
            .oneshot(
                Request::post("/commands/merge")
                    .header("content-type", "application/json")
                    .body(Body::from(serde_json::to_vec(&request).unwrap()))
                    .unwrap(),
            )
            .await
            .unwrap();
        let status = response.status();
        let body = axum::body::to_bytes(response.into_body(), 256 * 1024)
            .await
            .unwrap();
        assert_eq!(
            status,
            StatusCode::OK,
            "the merge must publish for this arm to grade anything: {}",
            String::from_utf8_lossy(&body)
        );

        let published = branch_change(&state);
        assert_ne!(
            published, main_change,
            "the merge must move the branch off its pre-merge change, or nothing was published \
             and the assertions below would grade an unchanged store"
        );
        // A FAST-FORWARD moves the ref onto an existing change and publishes
        // nothing, so every assertion below would pass on an unpatched binary
        // for a change that was already in the graph. This arm grades nothing
        // unless a genuine merge change was authored, and the tell is that the
        // published change is neither side's tip and carries both as parents.
        assert_ne!(
            published, _feature_change,
            "NOT RUN, precondition unmet: the merge fast-forwarded onto the feature change rather \
             than authoring a merge change, so nothing was published and this arm cannot see the \
             defect it exists for"
        );
        // The property assertion comes FIRST, because it owns the absence. An
        // earlier read that mapped a missing change onto a parent count of zero
        // reported this defect as "not a merge change", which is a precondition
        // refusal wearing the property's clothes: measured, the install-removed
        // arms failed here saying the publication was the wrong KIND when the
        // truth is the change is missing from the graph. Never map a failed read
        // onto a value a real answer could take.
        //
        // It also goes through the LIVE projection rather than an
        // authority-backed surface: `kin log` and `kin status` answered rc=0 on
        // the unpatched binary throughout, so a check reading only those would
        // pass on both builds. The split is the whole tell.
        let held = state.graph.get_change(&published).unwrap().expect(
            "the live graph does not hold the change the merge just published, so every read \
                 that replays the graph to it fails until the daemon restarts; authority holds it \
                 and the derived query view does not",
        );
        // Only now, on a change the graph actually holds, is the KIND readable.
        assert_eq!(
            held.parents.len(),
            2,
            "NOT RUN, precondition unmet: the published change carries {} parent(s) rather than \
             two, so it is not a merge change and this arm graded a publication of a different \
             kind",
            held.parents.len()
        );

        // The assertion this arm exists for. No restart between publication and
        // this read, and it goes through the LIVE projection rather than an
        // authority-backed surface: `kin log` and `kin status` answered rc=0 on
        // the unpatched binary throughout, so a check reading only those would
        // pass on both builds. The split is the whole tell.
        state
            .graph
            .resolve_graph_at(&published)
            .expect("a graph holding the published merge change must replay to it");

        // OVER-INVALIDATION guard: discarding the projection would satisfy every
        // assertion above while destroying what it already held.
        state.graph.resolve_graph_at(&main_change).expect(
            "the graph can no longer replay to a change it held before the merge, so the \
             projection was discarded rather than added to",
        );

        let identity_after = read_local_publication_identity(&backend, &repository_id).unwrap();
        let (counter_after, roots_after) = generation_pair(&state);
        // The daemon's counter moves by exactly what the authority's generation
        // moves across a publication. Both are asserted rather than only their
        // equality afterwards, because equal-after is consistent with two very
        // different worlds: something advances the counter on a publish, or the
        // counter and the roots both sat still. Only the DELTA separates them,
        // which is the same reason a cgroup's oom_kill cannot separate a cap
        // kill from an outside one while max and oom can.
        //
        // Measured by lane vcsreads before this became an assertion: counter 2
        // to 3 and roots 2 to 3 across a merge publish. The advancing site is
        // `finalize_local_repository_commit` calling
        // `record_repository_authority_commit` at `state.rs:9062` under its CAS
        // condition, reached from `repository_merge.rs:121` and
        // `repository_rollback.rs:91`, which is one level above where a
        // call-site count looks.
        assert!(
            roots_after > roots_before,
            "the authority generation did not move across this publication, so the counter \
             assertion below would grade a publication that did not happen"
        );
        assert_eq!(
            counter_after - counter_before,
            roots_after - roots_before,
            "the daemon generation counter moved by {} while the authority generation moved by \
             {}; they must move together, and a counter left behind is what makes every \
             freshness guard reading it refuse or pass wrongly",
            counter_after - counter_before,
            roots_after - roots_before
        );
        assert!(
            identity_before != identity_after,
            "the publication identity did not move across a merge publication, so every authority \
             slot keyed on it stays valid across the merge and concurrent readers admit against \
             pre-merge roots"
        );
    }

    /// A published rollback must reach the LIVE graph, not only durable
    /// authority, without restarting the daemon.
    ///
    /// The transaction publishes an inverse change to repository authority and
    /// the in-process graph is a derived query view over it. This path
    /// published and never installed, so `graph.get_change` returned `None` for
    /// a change the authority resolved, and every read that replays the graph
    /// to it failed until a restart rebuilt the graph from authority. A further
    /// commit did not heal it, because a commit installs its OWN change and not
    /// the missing one.
    ///
    /// The daemon here has LIVED THROUGH the publications, which is the
    /// condition that makes the defect visible: this one `state` performs the
    /// commits and then the rollback, exactly as a running daemon does. A fresh
    /// state built after the publication rebuilds its graph from authority and
    /// therefore holds the change either way, which is why the original report
    /// did not reproduce on its first attempt against a new daemon.
    ///
    /// The reads that already worked are asserted too. They answer from
    /// authority rather than by replaying the graph, so a fix that invalidated
    /// the projection instead of installing into it could break them while
    /// leaving this test's first assertion green.
    #[tokio::test]
    #[serial_test::serial(repository_commit)]
    async fn a_published_rollback_reaches_the_live_graph_without_a_restart() {
        let state = test_state();
        let root = state.layout.working_dir().to_path_buf();
        let app = router(Arc::clone(&state));
        std::fs::create_dir_all(root.join("notekeeper")).unwrap();

        std::fs::write(
            root.join("notekeeper/client.py"),
            b"def normalize(term):\n    return 1\n",
        )
        .unwrap();
        let restored =
            commit_through_api(&app, kin_model::OperationId::new(), "publish the base").await;
        std::fs::write(
            root.join("notekeeper/client.py"),
            b"def normalize(term):\n    return 2\n",
        )
        .unwrap();
        let regression =
            commit_through_api(&app, kin_model::OperationId::new(), "publish a regression").await;
        assert_eq!(branch_change(&state), regression);

        // PRECONDITION, proved rather than assumed: this daemon's projection is
        // populated BEFORE the publication. That is the condition the defect
        // needs, and a check that publishes into an empty projection passes on
        // the unpatched binary, which is the single most likely way this test
        // could fail to fail. Forcing a graph-replaying read here both creates
        // the state and records that it existed.
        //
        // A failure HERE is not a verdict on the property. It says the fixture
        // never reached the state under test, and its message says so, because
        // a precondition red and a property red are different news and a reader
        // of a stack trace cannot tell them apart from the line number alone.
        state
            .graph
            .resolve_graph_at(&regression)
            .unwrap_or_else(|error| {
                panic!(
                    "NOT RUN, precondition unmet rather than property refuted: this daemon's \
                     graph could not replay to the change it just published, so the projection \
                     was never populated and publishing into it proves nothing: {error}"
                )
            });

        let backend = state.local_repository_backend().unwrap();
        let repository_id = state
            .local_repository_authority_binding()
            .unwrap()
            .repository_id()
            .clone();
        let identity_before = read_local_publication_identity(&backend, &repository_id).unwrap();
        let (counter_before, roots_before) = generation_pair(&state);
        // CONTROL for the comparison below: read the identity twice with no
        // publication between and require it to be the SAME. Without this, an
        // identity that differed on every read would make the across-publication
        // assertion pass while proving nothing about publications.
        let identity_again = read_local_publication_identity(&backend, &repository_id).unwrap();
        assert!(
            identity_before == identity_again,
            "the publication identity differs between two reads with no publication between them, \
             so it cannot be evidence that a publication moved it"
        );
        let loads_before = state.projection_authority.loads();

        let (status, body) =
            rollback_through_api(&app, kin_model::OperationId::new(), restored).await;
        assert_eq!(status, StatusCode::OK, "the rollback must publish: {body}");

        let identity_after = read_local_publication_identity(&backend, &repository_id).unwrap();
        let (counter_after, roots_after) = generation_pair(&state);
        // The daemon's counter moves by exactly what the authority's generation
        // moves across a publication. Both are asserted rather than only their
        // equality afterwards, because equal-after is consistent with two very
        // different worlds: something advances the counter on a publish, or the
        // counter and the roots both sat still. Only the DELTA separates them,
        // which is the same reason a cgroup's oom_kill cannot separate a cap
        // kill from an outside one while max and oom can.
        //
        // Measured by lane vcsreads before this became an assertion: counter 2
        // to 3 and roots 2 to 3 across a merge publish. The advancing site is
        // `finalize_local_repository_commit` calling
        // `record_repository_authority_commit` at `state.rs:9062` under its CAS
        // condition, reached from `repository_merge.rs:121` and
        // `repository_rollback.rs:91`, which is one level above where a
        // call-site count looks.
        assert!(
            roots_after > roots_before,
            "the authority generation did not move across this publication, so the counter \
             assertion below would grade a publication that did not happen"
        );
        assert_eq!(
            counter_after - counter_before,
            roots_after - roots_before,
            "the daemon generation counter moved by {} while the authority generation moved by \
             {}; they must move together, and a counter left behind is what makes every \
             freshness guard reading it refuse or pass wrongly",
            counter_after - counter_before,
            roots_after - roots_before
        );
        let _ = loads_before;

        let published = branch_change(&state);
        assert_ne!(
            published, regression,
            "the rollback must move the branch off the regression"
        );

        // MEASUREMENT, recorded in the test rather than in a report: does the
        // publication identity that `ProjectionAuthorityCache` keys on actually
        // MOVE across a publication that never calls
        // `record_repository_authority_commit`?
        //
        // CORRECTED. This comment previously read "neither this path nor the
        // merge paths call it, so `snapshot_generation` does not advance across
        // either". The first clause is true of DIRECT calls and the conclusion
        // does not follow: both paths call `finalize_local_repository_commit`,
        // which calls it at `state.rs:9062` behind a `generation_advanced`
        // guard, so the counter DOES advance. A call-site count is not a call
        // graph, and four separate readings were built on top of that zero
        // before an in-process probe measured `counter=2 roots=2` before a
        // merge and `counter=3 roots=3` after, with a control proving the
        // probe's own authority open did not advance it.
        //
        // What stands, and it is the reason this block is here: the cache does
        // not key on that counter either way.
        // `LocalPublicationIdentity::Published` is the SHA-256 of the durable
        // publication record's bytes, so it moves whenever the record is
        // rewritten, whatever the in-memory counter did. If it did NOT move, an
        // admission pair cached before this publication would stay valid after
        // it and every concurrent task would admit against pre-publication
        // roots, which is a defect in the cache rather than in this path.
        // `assert!` rather than `assert_ne!`: the identity is deliberately not
        // `Debug`, since printing a publication digest into a panic is not
        // something a test should teach the type to allow.
        assert!(
            identity_before != identity_after,
            "the publication identity did not move across a publication, so every authority slot \
             keyed on it stays valid across the change and concurrent readers admit against \
             pre-publication roots"
        );

        // The assertion this test exists for. No restart between the
        // publication and this read.
        assert!(
            state.graph.get_change(&published).unwrap().is_some(),
            "the live graph does not hold the change the rollback just published, so every read \
             that replays the graph to it fails until the daemon restarts; authority holds it and \
             the derived query view does not"
        );

        // The reads that already answered must still answer. `resolve_graph_at`
        // is what a graph-replaying read does, and the branch change is what
        // the authority resolves to.
        state
            .graph
            .resolve_graph_at(&published)
            .expect("a graph holding the published change must replay to it");

        // OVER-INVALIDATION guard, and it is the assertion a fix of the wrong
        // shape fails. Installing into the projection is one way to close this
        // defect; discarding the projection so the next read rebuilds is
        // another, and it would satisfy every assertion above while destroying
        // the changes the projection already held. Lane vcsreads measured which
        // reads keep working across the unpatched defect (`kin log`,
        // `kin diff <change> HEAD`, `kin status`, `kin graph status`, all
        // resolving the change fine while blame and history cannot), and
        // nothing guarded them. This is their equivalent one layer down: the
        // PRE-publication change must still replay after the publication.
        state.graph.resolve_graph_at(&regression).expect(
            "the graph can no longer replay to a change it held before this publication, so \
                 the projection was discarded rather than added to and every read that worked \
                 across the original defect now fails",
        );
    }

    /// An operation id is matched before any history validation runs, and an
    /// ordinary commit publishes the same receipt shape a rollback does. Only
    /// the restored content separates them, so reusing a commit's operation id
    /// must be refused instead of reported as a rollback that never happened.
    #[tokio::test]
    async fn command_rollback_refuses_an_operation_id_that_published_a_different_change() {
        let state = test_state();
        state
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);
        let root = state.layout.working_dir().to_path_buf();
        let app = router(Arc::clone(&state));

        std::fs::write(root.join("service.txt"), b"shipped\n").unwrap();
        let restored = commit_through_api(
            &app,
            kin_model::OperationId::new(),
            "publish the good state",
        )
        .await;
        std::fs::write(root.join("service.txt"), b"regressed\n").unwrap();
        let reused = kin_model::OperationId::new();
        let regression = commit_through_api(&app, reused, "publish the regression").await;
        assert_eq!(branch_change(&state), regression);

        // The retained receipt for `reused` is an ordinary commit's. It carries
        // one ref mutation onto a change under a MustEqual expectation and a
        // workspace mutation, so every shape check passes; only the restored
        // content refutes it.
        let (status, body) = rollback_through_api(&app, reused, restored).await;
        assert_eq!(
            status,
            StatusCode::CONFLICT,
            "a commit's receipt was reported as this caller's rollback: {body}"
        );
        assert_eq!(
            branch_change(&state),
            regression,
            "a refused rollback moved the branch"
        );
        assert_eq!(
            std::fs::read(root.join("service.txt")).unwrap(),
            b"regressed\n",
            "a refused rollback restored the working copy anyway"
        );

        // The same reuse against a change this repository never materialized is
        // refused for the same reason: the echoed target is never trusted.
        let (status, body) = rollback_through_api(
            &app,
            reused,
            SemanticChangeId::from_hash(Hash256::from_bytes([0; 32])),
        )
        .await;
        assert_eq!(
            status,
            StatusCode::CONFLICT,
            "a rollback reported a target this repository does not have: {body}"
        );

        // Honest idempotency still reports success: a genuine rollback retried
        // with its own operation id reports what it published and commits
        // nothing further.
        let rollback_operation = kin_model::OperationId::new();
        let (status, body) = rollback_through_api(&app, rollback_operation, restored).await;
        assert_eq!(status, StatusCode::OK, "{body}");
        let first: serde_json::Value = serde_json::from_str(&body).unwrap();
        assert_eq!(first["mutated"], true);
        assert_eq!(first["report"]["target_change_id"], restored.to_string());
        let published = branch_change(&state);
        assert_ne!(published, regression, "rollback published no change");

        let (status, body) = rollback_through_api(&app, rollback_operation, restored).await;
        assert_eq!(status, StatusCode::OK, "{body}");
        let replay: serde_json::Value = serde_json::from_str(&body).unwrap();
        assert_eq!(
            replay["mutated"], false,
            "an already-published rollback committed a second change"
        );
        assert_eq!(replay["report"]["idempotent"], true);
        assert_eq!(replay["report"]["target_change_id"], restored.to_string());
        assert_eq!(
            replay["report"]["inverse_change_id"], first["report"]["inverse_change_id"],
            "the replay reported a different published change"
        );
        assert_eq!(
            branch_change(&state),
            published,
            "an already-published rollback moved the branch again"
        );
        assert_eq!(
            std::fs::read(root.join("service.txt")).unwrap(),
            b"shipped\n",
            "the rollback did not leave the restored content in place"
        );
    }

