    /// End-to-end proof for the `exec`/`shell`/`open`/`with` cluster: the CLI
    /// session surface materializes from repository CAS over the real daemon
    /// HTTP path, a real process runs inside the projection, and the delta it
    /// leaves is admitted through repository authority.
    ///
    /// Every step is the product path. If the CLI stopped going through the
    /// daemon, or stopped admitting through reconcile, or started deleting a
    /// projection without admitting it, this fails.
    #[cfg(unix)]
    #[tokio::test]
    #[serial_test::serial]
    async fn cli_session_surface_runs_a_process_and_admits_its_delta_through_authority() {
        use std::os::unix::fs::PermissionsExt as _;

        let state = test_state();
        install_repository_file(&state, "src/lib.py", b"graph truth\n");
        install_repository_entry(&state, "bin/verify", b"#!/bin/sh\nexit 0\n", |hash| {
            TreeEntry::blob(hash, true)
        });
        install_working_copy_file(&state, "src/lib.py", b"graph truth\n", false);
        install_working_copy_file(&state, "bin/verify", b"#!/bin/sh\nexit 0\n", true);
        state
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);

        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let addr = listener.local_addr().unwrap();
        let app = router(state.clone());
        let server = tokio::spawn(async move {
            let _ = axum::serve(listener, app).await;
        });
        let _daemon_url =
            kin_core::test_env::EnvVarGuard::set("KIN_DAEMON_URL", format!("http://{addr}"));

        let projection =
            kin_cli::commands::session_run::materialize(state.layout.clone(), None, None)
                .await
                .expect("materialize an exact session projection through the daemon");

        // The projection is repository CAS truth, including the mode bit.
        assert_eq!(
            std::fs::read_to_string(projection.root().join("src/lib.py")).unwrap(),
            "graph truth\n"
        );
        assert_ne!(
            std::fs::metadata(projection.root().join("bin/verify"))
                .unwrap()
                .permissions()
                .mode()
                & 0o111,
            0,
            "an exact projection retains the executable mode"
        );

        // A real process, run with its working directory inside the projection.
        let invocation = kin_cli::commands::session_run::ExecInvocation::parse(
            vec![
                "printf 'session note\\n' > notes.txt && printf '%s' \"$KIN_SESSION_DIR\" > \
                 seen-session-dir.txt"
                    .to_string(),
            ],
            true,
        )
        .unwrap();
        let exit =
            kin_cli::commands::session_run::run_in_session(&projection, invocation.command())
                .expect("run a process in the session projection");
        assert_eq!(exit.code, 0);
        assert_eq!(
            std::fs::read_to_string(projection.root().join("seen-session-dir.txt")).unwrap(),
            projection.root().display().to_string(),
            "the child is told which projection it is running in"
        );

        let session_dir = state.layout.runs_dir().join(projection.name());
        kin_cli::commands::session_run::close(
            &projection,
            exit,
            kin_cli::commands::session_run::SessionCloseout::Reconcile,
        )
        .await
        .expect("admit the session observation through repository authority");

        assert!(
            !session_dir.exists(),
            "an admitted session projection is disposable and must not be left behind"
        );
        let notes = RepoPath::from_utf8("notes.txt").unwrap();
        assert!(
            state
                .graph
                .resolved_tree()
                .artifact_at_path(&notes)
                .is_some(),
            "the delta the process left must reach repository authority"
        );

        // A discarded session leaves authority untouched.
        let discarded =
            kin_cli::commands::session_run::materialize(state.layout.clone(), None, None)
                .await
                .unwrap();
        let discarded_dir = state.layout.runs_dir().join(discarded.name());
        let discard_exit = kin_cli::commands::session_run::run_in_session(
            &discarded,
            kin_cli::commands::session_run::ExecInvocation::parse(
                vec!["printf 'never admitted\\n' > dropped.txt".to_string()],
                true,
            )
            .unwrap()
            .command(),
        )
        .unwrap();
        assert_eq!(discard_exit.code, 0);
        let generation_before_discard = state.graph.resolved_tree().len();
        kin_cli::commands::session_run::close(
            &discarded,
            discard_exit,
            kin_cli::commands::session_run::SessionCloseout::Discard,
        )
        .await
        .unwrap();
        assert!(!discarded_dir.exists());
        assert_eq!(
            state.graph.resolved_tree().len(),
            generation_before_discard,
            "a discarded session must not move repository authority"
        );
        assert!(state
            .graph
            .resolved_tree()
            .artifact_at_path(&RepoPath::from_utf8("dropped.txt").unwrap())
            .is_none());

        // A failed process keeps its projection for inspection rather than
        // admitting or deleting it.
        let failed = kin_cli::commands::session_run::materialize(state.layout.clone(), None, None)
            .await
            .unwrap();
        let failed_dir = state.layout.runs_dir().join(failed.name());
        let failed_exit = kin_cli::commands::session_run::run_in_session(
            &failed,
            kin_cli::commands::session_run::ExecInvocation::parse(
                vec!["printf 'partial\\n' > partial.txt; exit 3".to_string()],
                true,
            )
            .unwrap()
            .command(),
        )
        .unwrap();
        assert_eq!(failed_exit.code, 3);
        kin_cli::commands::session_run::close(
            &failed,
            failed_exit,
            kin_cli::commands::session_run::SessionCloseout::Reconcile,
        )
        .await
        .unwrap();
        assert!(
            failed_dir.join("partial.txt").is_file(),
            "a failed run keeps its projection instead of admitting or deleting it"
        );
        assert!(state
            .graph
            .resolved_tree()
            .artifact_at_path(&RepoPath::from_utf8("partial.txt").unwrap())
            .is_none());

        server.abort();
    }

    /// `kin open` retains its projection, and `kin reconcile` collects it.
    ///
    /// `open` is the one surface in the cluster that never closes its own
    /// session: an editor detaches from the launching process, so there is no
    /// exit to admit on. That makes admission the only collector, and this
    /// drives the real `open` function to prove both halves. Without the
    /// collector every `kin open` would leave a full repository materialization
    /// under `.kin/runs/` forever.
    ///
    /// The refusal half matters just as much: a reconcile that cannot admit
    /// must leave the projection alone, because the only copy of that work is
    /// the directory it is being asked to take.
    #[cfg(unix)]
    #[tokio::test]
    #[serial_test::serial]
    async fn kin_open_retains_its_projection_until_reconcile_collects_it() {
        use std::os::unix::fs::PermissionsExt as _;

        /// Restore the process state `kin open` reads from.
        ///
        /// `open` resolves its repository from the working directory and its
        /// editor from `PATH`, so driving the real function means moving both.
        /// A guard puts them back even when an assertion unwinds.
        struct ProcessScope {
            working_dir: PathBuf,
            _search_path: kin_core::test_env::EnvVarGuard,
        }

        impl ProcessScope {
            fn enter(working_dir: &FsPath, editor_dir: &FsPath) -> Self {
                let mut search = vec![editor_dir.to_path_buf()];
                if let Some(existing) = std::env::var_os("PATH") {
                    search.extend(std::env::split_paths(&existing));
                }
                let scope = Self {
                    working_dir: std::env::current_dir().unwrap(),
                    _search_path: kin_core::test_env::EnvVarGuard::set(
                        "PATH",
                        std::env::join_paths(search).unwrap(),
                    ),
                };
                std::env::set_current_dir(working_dir).unwrap();
                scope
            }
        }

        impl Drop for ProcessScope {
            fn drop(&mut self) {
                let _ = std::env::set_current_dir(&self.working_dir);
            }
        }

        // `getcwd` returns a fully resolved path, so a fixture repository
        // reached through a symlinked temp root would give the CLI a different
        // layout than the daemon holds, and the reconcile boundary would
        // correctly refuse it as a foreign session path.
        install_test_registry_override();
        let root = std::fs::canonicalize(std::env::temp_dir())
            .unwrap()
            .join(format!("kin-daemon-open-collect-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&root).unwrap();
        let state = Arc::new(DaemonState::open(kin_core::init(&root).unwrap().layout).unwrap());
        install_repository_file(&state, "src/lib.py", b"graph truth\n");
        install_working_copy_file(&state, "src/lib.py", b"graph truth\n", false);
        state
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);

        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let addr = listener.local_addr().unwrap();
        let app = router(state.clone());
        let server = tokio::spawn(async move {
            let _ = axum::serve(listener, app).await;
        });
        let _daemon_url =
            kin_core::test_env::EnvVarGuard::set("KIN_DAEMON_URL", format!("http://{addr}"));

        // `kin open` launches an allowlisted editor by name, so the stand-in
        // has to be reachable exactly the way the real one is.
        let editor_dir = tempfile::tempdir().unwrap();
        let editor = editor_dir.path().join("code");
        std::fs::write(
            &editor,
            "#!/bin/sh\nprintf 'editor note\\n' > editor-note.txt\nprintf '%s' \"$1\" > \
             opened-path.txt\n",
        )
        .unwrap();
        std::fs::set_permissions(&editor, std::fs::Permissions::from_mode(0o755)).unwrap();

        let scope = ProcessScope::enter(state.layout.working_dir(), editor_dir.path());
        let opened = kin_cli::commands::session_run::open("code".to_string()).await;
        drop(scope);
        opened.expect("launch an allowlisted editor over a session projection");

        let session_dir = sole_session_projection(&state.layout);
        assert!(
            session_dir.join("editor-note.txt").is_file(),
            "the editor runs with its working directory inside the retained projection"
        );
        assert_eq!(
            std::fs::read_to_string(session_dir.join("opened-path.txt")).unwrap(),
            session_dir.display().to_string(),
            "the editor is pointed at the projection, not at the owning working tree"
        );
        let note = RepoPath::from_utf8("editor-note.txt").unwrap();
        assert!(
            state
                .graph
                .resolved_tree()
                .artifact_at_path(&note)
                .is_none(),
            "open must not admit anything on its own"
        );

        // A reconcile that cannot admit keeps the projection it refused.
        std::fs::create_dir(session_dir.join(".kin")).unwrap();
        std::fs::write(session_dir.join(".kin").join("stowaway"), b"reserved\n").unwrap();
        let refusal = kin_cli::commands::reconcile::run_for_layout(&state.layout, None, false)
            .await
            .expect_err("a projection carrying a reserved control path must be refused");
        assert!(
            session_dir.join("editor-note.txt").is_file(),
            "a refused reconcile must keep the projection it could not admit: {refusal:#}"
        );
        assert!(
            state
                .graph
                .resolved_tree()
                .artifact_at_path(&note)
                .is_none(),
            "a refused reconcile must not move repository authority"
        );

        // Once the refusal is cleared, admission is what collects it.
        std::fs::remove_dir_all(session_dir.join(".kin")).unwrap();
        kin_cli::commands::reconcile::run_for_layout(&state.layout, None, false)
            .await
            .expect("admit the retained projection through repository authority");
        assert!(
            !session_dir.exists(),
            "kin reconcile is the collector for a retained projection"
        );
        assert!(
            state
                .graph
                .resolved_tree()
                .artifact_at_path(&note)
                .is_some(),
            "the delta the editor left must reach repository authority"
        );

        server.abort();
    }

    /// The one session projection a fixture repository is holding.
    ///
    /// Asserting there is exactly one is part of the proof: a surface that
    /// materialized twice, or that collected nothing, shows up here.
    #[cfg(unix)]
    fn sole_session_projection(layout: &kin_core::KinLayout) -> PathBuf {
        let mut found = std::fs::read_dir(layout.runs_dir())
            .unwrap()
            .map(|entry| entry.unwrap().path())
            .filter(|path| {
                path.file_name()
                    .and_then(|name| name.to_str())
                    .is_some_and(|name| name.starts_with("session-"))
            })
            .collect::<Vec<_>>();
        assert_eq!(found.len(), 1, "expected exactly one session projection");
        found.pop().unwrap()
    }

    /// A working agent keeps its session by working.
    ///
    /// The session idle window is an idle timeout, so a tool call from a
    /// session refreshes its lease. Without this an agent that never calls
    /// `kin_session_heartbeat` gets reaped mid-task, taking its in-flight
    /// transaction with it, no matter how busy it was.
    ///
    /// What is proven here is that presenting a session id extends that
    /// session. Ownership is not checked and is not claimed: see
    /// [`touch_session_liveness`].
    #[tokio::test]
    async fn a_tool_call_refreshes_the_calling_session_lease() {
        let state = test_state();
        state
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);
        let session_id = state
            .coordinator
            .register_session(
                "claude-code",
                "busy-agent",
                kin_model::session::SessionTransport::Mcp,
                None,
                PathBuf::from("/"),
                kin_model::session::SessionCapabilities::default(),
            )
            .unwrap();
        let before = state
            .coordinator
            .get_session(&session_id)
            .unwrap()
            .unwrap()
            .last_heartbeat;

        std::thread::sleep(std::time::Duration::from_millis(20));
        let response = router(state.clone())
            .oneshot(
                Request::post("/mcp/tools/call")
                    .header("content-type", "application/json")
                    .header("X-Kin-Session", session_id.to_string())
                    .body(Body::from(
                        serde_json::json!({
                            "name": "kin_graph_status",
                            "arguments": {},
                        })
                        .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);

        let after = state
            .coordinator
            .get_session(&session_id)
            .unwrap()
            .expect("a working session is still live")
            .last_heartbeat;
        assert!(
            after > before,
            "a tool call must refresh the lease whose id it presents: {before:?} -> {after:?}"
        );
    }

    /// A capability-scoped session lease is registered for `kin with`, exported
    /// to the child, and released on closeout.
    #[cfg(unix)]
    #[tokio::test]
    #[serial_test::serial]
    async fn cli_session_lease_is_capability_scoped_and_released() {
        let state = test_state();
        install_repository_file(&state, "src/lib.py", b"graph truth\n");
        install_working_copy_file(&state, "src/lib.py", b"graph truth\n", false);
        state
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);

        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let addr = listener.local_addr().unwrap();
        let app = router(state.clone());
        let server = tokio::spawn(async move {
            let _ = axum::serve(listener, app).await;
        });
        let _daemon_url =
            kin_core::test_env::EnvVarGuard::set("KIN_DAEMON_URL", format!("http://{addr}"));

        let mut projection =
            kin_cli::commands::session_run::materialize(state.layout.clone(), None, None)
                .await
                .unwrap();
        let session_id = kin_cli::commands::session_run::register_lease(
            &mut projection,
            "claude",
            "kin with",
            kin_model::session::SessionCapabilities {
                can_read: true,
                can_write: true,
                can_execute: true,
                can_branch: false,
                can_commit: true,
                max_concurrent_intents: 8,
            },
        )
        .await
        .expect("register a capability-scoped session lease");

        let registered = state
            .coordinator
            .get_session(&SessionId(Uuid::parse_str(&session_id).unwrap()))
            .unwrap()
            .expect("the lease is live in the coordinator");
        assert!(registered.capabilities.can_write);
        assert!(!registered.capabilities.can_branch);
        assert_eq!(registered.cwd, projection.root());

        let exit = kin_cli::commands::session_run::run_in_session(
            &projection,
            kin_cli::commands::session_run::ExecInvocation::parse(
                vec!["printf '%s' \"$KIN_SESSION_ID\" > seen-session.txt".to_string()],
                true,
            )
            .unwrap()
            .command(),
        )
        .unwrap();
        assert_eq!(exit.code, 0);
        assert_eq!(
            std::fs::read_to_string(projection.root().join("seen-session.txt")).unwrap(),
            session_id,
            "the child inherits the lease it is coordinating under"
        );

        kin_cli::commands::session_run::close(
            &projection,
            exit,
            kin_cli::commands::session_run::SessionCloseout::Reconcile,
        )
        .await
        .unwrap();
        assert!(
            state
                .coordinator
                .get_session(&SessionId(Uuid::parse_str(&session_id).unwrap()))
                .unwrap()
                .is_none(),
            "closing a session releases its lease"
        );

        server.abort();
    }

    #[tokio::test]
    async fn session_workspace_endpoint_materializes_live_graph() {
        let state = test_state();
        install_repository_file(&state, "src/lib.py", b"graph truth\n");
        install_repository_file(
            &state,
            "compose.yaml",
            b"services:\n  api:\n    image: kin:test\n",
        );
        install_repository_entry(&state, "bin/verify", b"#!/bin/sh\nexit 0\n", |hash| {
            TreeEntry::blob(hash, true)
        });
        install_repository_file(
            &state,
            "assets/policy.unknown",
            b"\x00\xffopaque repository bytes\x00",
        );
        #[cfg(unix)]
        install_repository_entry(
            &state,
            "current-compose",
            b"compose.yaml",
            TreeEntry::symlink,
        );

        std::fs::create_dir_all(state.layout.working_dir().join("src")).unwrap();
        std::fs::write(
            state.layout.working_dir().join("src/lib.py"),
            b"checkout drift must not become session authority\n",
        )
        .unwrap();
        state
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);
        let app = router(state.clone());
        let session_dir = state.layout.root().join("runs/session-api");
        let scoped_session_dir = state.layout.root().join("runs/session-api-scoped");
        let scoped = app
            .clone()
            .oneshot(
                Request::post("/commands/session-workspace")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        serde_json::json!({
                            "session_dir": scoped_session_dir.display().to_string(),
                            "strategy": null,
                            "scope": "artifact:compose.yaml"
                        })
                        .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(scoped.status(), StatusCode::BAD_REQUEST);
        assert!(
            !scoped_session_dir.exists(),
            "unauthenticated scoped session selection must fail before publication"
        );

        let response = app
            .oneshot(
                Request::post("/commands/session-workspace")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        serde_json::json!({
                            "session_dir": session_dir.display().to_string(),
                            "strategy": null,
                            "scope": null
                        })
                        .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();

        assert_eq!(response.status(), StatusCode::OK);
        let body = axum::body::to_bytes(response.into_body(), 16 * 1024)
            .await
            .unwrap();
        let result: kin_cli::commands::session_workspace::SessionWorkspaceResponse =
            serde_json::from_slice(&body).unwrap();
        assert_eq!(result.source_kind, "exact-tree");
        assert_eq!(
            std::fs::read_to_string(session_dir.join("src/lib.py")).unwrap(),
            "graph truth\n"
        );
        assert_eq!(
            std::fs::read_to_string(session_dir.join("compose.yaml")).unwrap(),
            "services:\n  api:\n    image: kin:test\n"
        );
        assert_eq!(
            std::fs::read(session_dir.join("assets/policy.unknown")).unwrap(),
            b"\x00\xffopaque repository bytes\x00"
        );
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt as _;

            assert_ne!(
                std::fs::metadata(session_dir.join("bin/verify"))
                    .unwrap()
                    .permissions()
                    .mode()
                    & 0o111,
                0
            );
            assert_eq!(
                std::fs::read_link(session_dir.join("current-compose")).unwrap(),
                PathBuf::from("compose.yaml")
            );
        }
        assert!(session_dir.join(".kin-session/base.json").is_file());
        let base: kin_cli::commands::session_workspace::SessionWorkspaceBase =
            serde_json::from_slice(
                &std::fs::read(session_dir.join(".kin-session/base.json")).unwrap(),
            )
            .unwrap();
        base.validate().unwrap();
        assert_eq!(
            base.materialized_artifact_ids.len(),
            base.source_workspace.tree.len(),
            "the complete materializable tree is represented in the session"
        );
        #[cfg(unix)]
        assert_eq!(base.source_workspace.tree.len(), 5);
        #[cfg(not(unix))]
        assert_eq!(base.source_workspace.tree.len(), 4);
        assert!(
            !session_dir.join(".kin").exists(),
            "session projection must not shadow owning-repository discovery"
        );
    }

    #[cfg(unix)]
    #[tokio::test]
    async fn reconcile_endpoint_admits_complete_exact_session_tree_and_replays() {
        use std::os::unix::fs::{symlink, PermissionsExt as _};

        let state = test_state_with_verified_gitlink();
        let deleted_path = RepoPath::from_utf8("delete.me").unwrap();
        let gitlink_path = RepoPath::from_utf8("vendor/subrepo").unwrap();
        #[cfg(target_os = "macos")]
        let raw_path = RepoPath::from_bytes(b"assets/raw-\xff.bin".to_vec()).unwrap();

        #[cfg(target_os = "macos")]
        {
            let raw_body = b"\x00raw graph-only bytes\xff";
            let raw_hash = state.blobs.write(raw_body).unwrap();
            state
                .graph
                .apply_transaction_delta(&TransactionDelta {
                    tree_deltas: vec![kin_model::TreeDelta::Added {
                        artifact_id: kin_model::ArtifactId::new(),
                        new: kin_model::LocatedEntry::new(
                            raw_path.clone(),
                            TreeEntry::blob(Hash256::from_bytes(raw_hash.0), false),
                        ),
                    }],
                    ..TransactionDelta::default()
                })
                .unwrap();
            let install_plan = crate::repository_commit::plan_native_commit(
                &state.graph,
                &state.blobs,
                &crate::local_repository_authority::LocalRepositoryAuthorityContext::from_state(
                    &state,
                )
                .unwrap(),
                kin_model::OperationId::new(),
                Timestamp::now(),
                AuthorId::new("reconcile-api-test"),
                "install host-unrepresentable exact fixture".to_string(),
            )
            .unwrap();
            let installed = crate::repository_commit::commit_native_plan(
                &state.blobs,
                &crate::local_repository_authority::LocalRepositoryAuthorityContext::from_state(
                    &state,
                )
                .unwrap(),
                install_plan,
            )
            .unwrap();
            state
                .record_repository_authority_commit(installed.receipt.generation)
                .unwrap();
            state.blobs.delete(&raw_hash).unwrap();
            assert!(
                state.blobs.read(&raw_hash).is_err(),
                "the test must prove graph-only preservation from repository CAS, not an \
                 accidentally warm ingestion CAS"
            );
        }

        std::fs::create_dir_all(state.layout.working_dir().join("vendor/subrepo")).unwrap();
        std::fs::write(
            state
                .layout
                .working_dir()
                .join("vendor/subrepo/arbitrary-descendant"),
            b"nested checkout identity must be retained\n",
        )
        .unwrap();

        state
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);
        let app = router(Arc::clone(&state));
        let session_dir = state.layout.root().join("runs/session-reconcile-api");
        let materialize = app
            .clone()
            .oneshot(
                Request::post("/commands/session-workspace")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        json!({
                            "session_dir": session_dir.display().to_string(),
                            "strategy": null,
                            "scope": null
                        })
                        .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(materialize.status(), StatusCode::OK);
        assert!(
            !session_dir.join("vendor/subrepo").exists(),
            "a Gitlink is exact graph membership, not a fake session file"
        );
        let base: kin_cli::commands::session_workspace::SessionWorkspaceBase =
            serde_json::from_slice(
                &std::fs::read(session_dir.join(".kin-session/base.json")).unwrap(),
            )
            .unwrap();
        base.validate().unwrap();
        let base_gitlink_id = base
            .source_workspace
            .tree
            .artifact_at_path(&gitlink_path)
            .unwrap()
            .artifact_id;
        assert!(!base.materialized_artifact_ids.contains(&base_gitlink_id));
        #[cfg(target_os = "macos")]
        let base_raw_id = base
            .source_workspace
            .tree
            .artifact_at_path(&raw_path)
            .unwrap()
            .artifact_id;
        #[cfg(target_os = "macos")]
        assert!(!base.materialized_artifact_ids.contains(&base_raw_id));

        std::fs::write(
            session_dir.join("compose.yaml"),
            b"services:\n  api:\n    image: kin:desired\n",
        )
        .unwrap();
        std::fs::write(
            session_dir.join("assets/policy.unknown"),
            b"\x00\xfeopaque desired bytes\x00",
        )
        .unwrap();
        let mut executable_permissions = std::fs::metadata(session_dir.join("bin/verify"))
            .unwrap()
            .permissions();
        executable_permissions.set_mode(0o644);
        std::fs::set_permissions(session_dir.join("bin/verify"), executable_permissions).unwrap();
        std::fs::remove_file(session_dir.join("current-compose")).unwrap();
        symlink("assets/policy.unknown", session_dir.join("current-compose")).unwrap();
        std::fs::remove_file(session_dir.join("delete.me")).unwrap();
        std::fs::create_dir_all(session_dir.join("notes")).unwrap();
        std::fs::write(
            session_dir.join("notes/new.odd"),
            b"new arbitrary repository member\n",
        )
        .unwrap();
        std::fs::create_dir_all(session_dir.join("vendor/subrepo")).unwrap();
        std::fs::write(
            session_dir.join("vendor/subrepo/untrusted-descendant"),
            b"this must not become parent-repository membership\n",
        )
        .unwrap();

        let request_body = json!({
            "session_dir": session_dir,
            "confirm_mass_deletion": false
        })
        .to_string();
        let reconcile = app
            .clone()
            .oneshot(
                Request::post("/reconcile")
                    .header("content-type", "application/json")
                    .body(Body::from(request_body.clone()))
                    .unwrap(),
            )
            .await
            .unwrap();
        let status = reconcile.status();
        let body = axum::body::to_bytes(reconcile.into_body(), 128 * 1024)
            .await
            .unwrap();
        assert_eq!(status, StatusCode::OK, "{}", String::from_utf8_lossy(&body));
        let summary: kin_cli::commands::reconcile::ReconcileSummary =
            serde_json::from_slice(&body).unwrap();
        assert!(summary.changed);
        assert!(!summary.idempotent_replay);
        assert_eq!(summary.added, 1);
        assert_eq!(summary.modified, 4);
        assert_eq!(summary.removed, 1);
        assert_eq!(summary.observed_materialized_artifacts, 6);
        #[cfg(target_os = "macos")]
        assert_eq!(summary.preserved_graph_only_artifacts, 2);
        #[cfg(not(target_os = "macos"))]
        assert_eq!(summary.preserved_graph_only_artifacts, 1);
        // Four of the five paths this observation moved carry a body the
        // publication can re-index: `compose.yaml`, `assets/policy.unknown`,
        // `bin/verify` and `notes/new.odd`. The symlink and the removal are
        // skipped, because neither is source owned by its path. The zero this
        // assertion used to carry was a literal in the handler rather than a
        // measurement, and it read as "nothing needed parsing" over files that
        // had just changed.
        assert_eq!(summary.semantic_files_enriched, 4);
        assert_eq!(summary.semantic_enrichment_failures, 0);

        let authority = ActiveApiRepositoryAuthority::open(&state).unwrap();
        let lease = authority.manager.read_authority();
        let workspace = lease
            .metadata()
            .workspaces
            .iter()
            .find(|workspace| workspace.workspace_id == authority.workspace_id)
            .unwrap()
            .clone();
        drop(lease);
        assert_eq!(workspace.tree_hash, summary.desired_tree_hash);
        assert_eq!(workspace.tree, state.graph.resolved_tree());
        assert_eq!(
            workspace
                .tree
                .artifact_at_path(&gitlink_path)
                .unwrap()
                .artifact_id,
            base_gitlink_id,
            "graph-only Gitlink identity must remain stable"
        );
        assert_eq!(
            workspace
                .tree
                .artifact_at_path(&gitlink_path)
                .unwrap()
                .entry,
            TreeEntry::gitlink(kin_model::GitObjectId::sha1([0x44; 20]))
        );
        #[cfg(target_os = "macos")]
        assert_eq!(
            workspace
                .tree
                .artifact_at_path(&raw_path)
                .unwrap()
                .artifact_id,
            base_raw_id,
            "host-unrepresentable exact membership and identity must survive reconciliation"
        );
        assert!(
            workspace.tree.artifact_at_path(&deleted_path).is_none(),
            "a missing materialized session member is an exact deletion"
        );
        assert!(workspace
            .tree
            .artifact_at_path(&RepoPath::from_utf8("notes/new.odd").unwrap())
            .is_some());

        assert_eq!(
            std::fs::read(state.layout.working_dir().join("compose.yaml")).unwrap(),
            b"services:\n  api:\n    image: kin:desired\n"
        );
        assert_eq!(
            std::fs::read(state.layout.working_dir().join("assets/policy.unknown")).unwrap(),
            b"\x00\xfeopaque desired bytes\x00"
        );
        assert_eq!(
            std::fs::metadata(state.layout.working_dir().join("bin/verify"))
                .unwrap()
                .permissions()
                .mode()
                & 0o111,
            0
        );
        assert_eq!(
            std::fs::read_link(state.layout.working_dir().join("current-compose")).unwrap(),
            PathBuf::from("assets/policy.unknown")
        );
        assert!(!state.layout.working_dir().join("delete.me").exists());
        assert_eq!(
            std::fs::read(state.layout.working_dir().join("notes/new.odd")).unwrap(),
            b"new arbitrary repository member\n"
        );
        assert_eq!(
            std::fs::read(
                state
                    .layout
                    .working_dir()
                    .join("vendor/subrepo/arbitrary-descendant")
            )
            .unwrap(),
            b"nested checkout identity must be retained\n",
            "Gitlink descendants are outside parent-repository traversal and mutation"
        );

        let replay = app
            .oneshot(
                Request::post("/reconcile")
                    .header("content-type", "application/json")
                    .body(Body::from(request_body.clone()))
                    .unwrap(),
            )
            .await
            .unwrap();
        let status = replay.status();
        let body = axum::body::to_bytes(replay.into_body(), 128 * 1024)
            .await
            .unwrap();
        assert_eq!(status, StatusCode::OK, "{}", String::from_utf8_lossy(&body));
        let replay: kin_cli::commands::reconcile::ReconcileSummary =
            serde_json::from_slice(&body).unwrap();
        assert!(replay.idempotent_replay);
        assert_eq!(replay.operation_id, summary.operation_id);
        assert_eq!(replay.desired_tree_hash, summary.desired_tree_hash);
        assert_eq!(replay.authority_generation, summary.authority_generation);

        let restarted = Arc::new(DaemonState::open(state.layout.clone()).unwrap());
        assert_eq!(
            restarted.graph.resolved_tree(),
            workspace.tree,
            "repository-v6 restart must retain the complete exact reconciled tree"
        );
        restarted
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);
        let restarted_replay = router(restarted)
            .oneshot(
                Request::post("/reconcile")
                    .header("content-type", "application/json")
                    .body(Body::from(request_body))
                    .unwrap(),
            )
            .await
            .unwrap();
        let status = restarted_replay.status();
        let body = axum::body::to_bytes(restarted_replay.into_body(), 128 * 1024)
            .await
            .unwrap();
        assert_eq!(status, StatusCode::OK, "{}", String::from_utf8_lossy(&body));
        let restarted_replay: kin_cli::commands::reconcile::ReconcileSummary =
            serde_json::from_slice(&body).unwrap();
        assert!(restarted_replay.idempotent_replay);
        assert_eq!(
            restarted_replay.desired_tree_hash,
            summary.desired_tree_hash
        );
    }

    #[cfg(unix)]
    #[tokio::test]
    async fn reconcile_rejects_control_aliases_special_members_and_stale_bases() {
        use std::os::unix::fs::{symlink, PermissionsExt as _};
        use std::os::unix::net::UnixListener;

        async fn materialize(state: &Arc<DaemonState>, session_dir: &FsPath) {
            let response = router(Arc::clone(state))
                .oneshot(
                    Request::post("/commands/session-workspace")
                        .header("content-type", "application/json")
                        .body(Body::from(
                            json!({
                                "session_dir": session_dir.display().to_string(),
                                "strategy": null,
                                "scope": null
                            })
                            .to_string(),
                        ))
                        .unwrap(),
                )
                .await
                .unwrap();
            assert_eq!(response.status(), StatusCode::OK);
        }

        async fn reconcile_status(state: &Arc<DaemonState>, session_dir: &FsPath) -> StatusCode {
            router(Arc::clone(state))
                .oneshot(
                    Request::post("/reconcile")
                        .header("content-type", "application/json")
                        .body(Body::from(
                            json!({
                                "session_dir": session_dir.display().to_string(),
                                "confirm_mass_deletion": false
                            })
                            .to_string(),
                        ))
                        .unwrap(),
                )
                .await
                .unwrap()
                .status()
        }

        let state = test_state();
        install_repository_file(&state, "README.md", b"exact base\n");
        state
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);

        let symlink_session = state.layout.root().join("runs/session-control-symlink");
        materialize(&state, &symlink_session).await;
        let base_path = symlink_session.join(".kin-session/base.json");
        let aliased_base = symlink_session.join("aliased-base.json");
        std::fs::write(&aliased_base, std::fs::read(&base_path).unwrap()).unwrap();
        std::fs::remove_file(&base_path).unwrap();
        symlink("../aliased-base.json", &base_path).unwrap();
        assert_eq!(
            reconcile_status(&state, &symlink_session).await,
            StatusCode::BAD_REQUEST,
            "control metadata must never be read through a symlink"
        );

        let hardlink_session = state.layout.root().join("runs/session-control-hardlink");
        materialize(&state, &hardlink_session).await;
        let base_path = hardlink_session.join(".kin-session/base.json");
        let aliased_base = hardlink_session.join("aliased-base.json");
        std::fs::write(&aliased_base, std::fs::read(&base_path).unwrap()).unwrap();
        let mut aliased_permissions = std::fs::metadata(&aliased_base).unwrap().permissions();
        aliased_permissions.set_mode(0o600);
        std::fs::set_permissions(&aliased_base, aliased_permissions).unwrap();
        std::fs::remove_file(&base_path).unwrap();
        std::fs::hard_link(&aliased_base, &base_path).unwrap();
        assert_eq!(
            reconcile_status(&state, &hardlink_session).await,
            StatusCode::BAD_REQUEST,
            "control metadata must be one unaliased regular file"
        );

        let special_session = state.layout.root().join("runs/session-special-member");
        materialize(&state, &special_session).await;
        let short_socket =
            PathBuf::from("/tmp").join(format!("kin-reconcile-{}.sock", Uuid::new_v4().simple()));
        let _listener = UnixListener::bind(&short_socket).unwrap();
        std::fs::rename(&short_socket, special_session.join("member.sock")).unwrap();
        assert_eq!(
            reconcile_status(&state, &special_session).await,
            StatusCode::BAD_REQUEST,
            "special filesystem members cannot enter exact repository authority"
        );

        let stale_session = state.layout.root().join("runs/session-stale-base");
        materialize(&state, &stale_session).await;
        install_repository_file(&state, "new-authority.txt", b"authority moved\n");
        let authority = ActiveApiRepositoryAuthority::open(&state).unwrap();
        let generation = authority.manager.read_authority().roots().generation;
        assert_eq!(
            reconcile_status(&state, &stale_session).await,
            StatusCode::CONFLICT,
            "a stale session must never silently rebase"
        );
        assert_eq!(
            authority.manager.read_authority().roots().generation,
            generation,
            "rejected stale reconciliation must not mutate authority"
        );
    }

