    /// A session that declares nothing must be reported able to do what this
    /// store lets it do.
    ///
    /// The report echoed the request straight back, and the MCP layer
    /// materialized a read-only declaration for a client that sent none, so a
    /// session that went on to stage and commit entity edits was told
    /// can_write false and can_commit false. An agent that honors its declared
    /// capabilities refuses the write it is permitted to make, which disables
    /// the write path for exactly the well-behaved callers.
    #[tokio::test]
    async fn an_undeclared_session_is_reported_able_to_write_and_commit() {
        let state = test_state();
        let app = router(state);

        let response = app
            .oneshot(
                Request::post("/session")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        serde_json::json!({
                            "vendor": "claude-code",
                            "client_name": "undeclared",
                            "transport": "mcp",
                            "cwd": "/project"
                        })
                        .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = axum::body::to_bytes(response.into_body(), 4096)
            .await
            .unwrap();
        let started: SessionStartResponse = serde_json::from_slice(&body).unwrap();

        assert!(
            started.capabilities.can_write,
            "this store accepts commits, so the session may write"
        );
        assert!(started.capabilities.can_commit);
        assert_eq!(started.capability_policy.can_write, CapabilitySource::Store);
        assert_eq!(
            started.capability_policy.can_commit,
            CapabilitySource::Store
        );
        assert_eq!(
            started.capability_policy.can_execute,
            CapabilitySource::Ungated,
            "Kin gates nothing on can_execute, and the report must not dress it as a grant"
        );
    }

    /// A client that restricts itself keeps that restriction, and the report
    /// says the client is what produced it.
    ///
    /// Without this the fix would be indistinguishable from hardcoding the bits
    /// true, which is the same defect facing the other way.
    #[tokio::test]
    async fn a_self_declared_read_only_session_keeps_its_restriction() {
        let state = test_state();
        let app = router(state);

        let response = app
            .oneshot(
                Request::post("/session")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        serde_json::json!({
                            "vendor": "claude-code",
                            "client_name": "reader",
                            "transport": "mcp",
                            "cwd": "/project",
                            "capabilities": {
                                "can_read": true,
                                "can_write": false,
                                "can_execute": false,
                                "can_branch": false,
                                "can_commit": false,
                                "max_concurrent_intents": 1
                            }
                        })
                        .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = axum::body::to_bytes(response.into_body(), 4096)
            .await
            .unwrap();
        let started: SessionStartResponse = serde_json::from_slice(&body).unwrap();

        assert!(!started.capabilities.can_write);
        assert!(!started.capabilities.can_commit);
        assert_eq!(
            started.capability_policy.can_write,
            CapabilitySource::ClientDeclared,
            "the store permits writes here, so the client is what made this false"
        );
    }

    /// A store that refuses commits reports it, and names itself as the cause.
    ///
    /// Exact repository commits are refused while a hosted snapshot backend is
    /// attached, so a session there genuinely cannot write however it declared
    /// itself.
    #[test]
    fn a_store_that_refuses_commits_reports_no_write_capability() {
        let declared = SessionCapabilities {
            can_read: true,
            can_write: true,
            can_execute: false,
            can_branch: false,
            can_commit: true,
            max_concurrent_intents: 1,
        };

        let (permitted, permitted_policy) = resolve_session_capabilities(true, Some(&declared));
        assert!(permitted.can_write);
        assert!(permitted.can_commit);
        assert_eq!(permitted_policy.can_write, CapabilitySource::Store);

        let (refused, refused_policy) = resolve_session_capabilities(false, Some(&declared));
        assert!(
            !refused.can_write,
            "a declaration cannot grant what the store refuses"
        );
        assert!(!refused.can_commit);
        assert_eq!(refused_policy.can_write, CapabilitySource::Store);
        assert_eq!(refused_policy.can_commit, CapabilitySource::Store);
    }

    #[tokio::test]
    async fn create_heartbeat_and_end_session() {
        let state = test_state();
        let app = router(state);
        let requested_session_id = SessionId::new();

        let start_response = app
            .clone()
            .oneshot(
                Request::post("/session")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        serde_json::json!({
                            "session_id": requested_session_id.to_string(),
                            "vendor": "claude-code",
                            "client_name": "daemon-test",
                            "transport": "mcp",
                            "cwd": "/project",
                            "capabilities": {
                                "can_read": true,
                                "can_write": false,
                                "can_execute": false,
                                "can_branch": false,
                                "can_commit": false,
                                "max_concurrent_intents": 1
                            }
                        })
                        .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(start_response.status(), StatusCode::OK);
        let start_body = axum::body::to_bytes(start_response.into_body(), 4096)
            .await
            .unwrap();
        let start_json: SessionStartResponse = serde_json::from_slice(&start_body).unwrap();
        assert_eq!(start_json.vendor, "claude-code");
        assert_eq!(start_json.status, "active");
        assert_eq!(start_json.client_name, "daemon-test");
        assert_eq!(start_json.session_id, requested_session_id.to_string());

        let duplicate_response = app
            .clone()
            .oneshot(
                Request::post("/session")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        serde_json::json!({
                            "session_id": requested_session_id.to_string(),
                            "vendor": "claude-code",
                            "client_name": "duplicate",
                            "transport": "mcp",
                            "cwd": "/project"
                        })
                        .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(duplicate_response.status(), StatusCode::CONFLICT);

        let heartbeat_response = app
            .clone()
            .oneshot(
                Request::post(format!("/session/{}/heartbeat", start_json.session_id))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(heartbeat_response.status(), StatusCode::OK);
        let heartbeat_body = axum::body::to_bytes(heartbeat_response.into_body(), 4096)
            .await
            .unwrap();
        let heartbeat_json: SessionHeartbeatResponse =
            serde_json::from_slice(&heartbeat_body).unwrap();
        assert_eq!(heartbeat_json.status, "active");

        let end_response = app
            .clone()
            .oneshot(
                Request::delete(format!("/session/{}", start_json.session_id))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(end_response.status(), StatusCode::OK);
        let end_body = axum::body::to_bytes(end_response.into_body(), 4096)
            .await
            .unwrap();
        let end_json: SessionEndResponse = serde_json::from_slice(&end_body).unwrap();
        assert_eq!(end_json.status, "ended");
    }

    /// Session start and heartbeat must both expose the next idle-reaping
    /// eligibility boundary, and a call on a dead session must say it expired
    /// and name the restart.
    ///
    /// An agent cannot decide to heartbeat before a deadline it cannot see, and
    /// a bare "not found" reads like a bad argument rather than an expiry, so a
    /// thinking pause silently stranded the whole session.
    #[tokio::test]
    async fn session_responses_carry_their_expiry_and_a_dead_session_says_so() {
        let state = test_state();
        let idle_ttl = state.coordinator.session_idle_ttl();
        let app = router(state);

        let start_response = app
            .clone()
            .oneshot(
                Request::post("/session")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        serde_json::json!({
                            "vendor": "claude-code",
                            "client_name": "expiry-test",
                            "transport": "mcp",
                            "cwd": "/project"
                        })
                        .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(start_response.status(), StatusCode::OK);
        let start_body = axum::body::to_bytes(start_response.into_body(), 4096)
            .await
            .unwrap();
        let start_json: SessionStartResponse = serde_json::from_slice(&start_body).unwrap();
        assert_eq!(start_json.idle_timeout_secs, idle_ttl.as_secs());
        assert!(
            start_json.idle_reap_eligible_at.0 > start_json.started_at.0,
            "the idle-reaping boundary must be ahead of the session it belongs to: {:?} vs {:?}",
            start_json.idle_reap_eligible_at,
            start_json.started_at
        );

        let heartbeat_response = app
            .clone()
            .oneshot(
                Request::post(format!("/session/{}/heartbeat", start_json.session_id))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(heartbeat_response.status(), StatusCode::OK);
        let heartbeat_body = axum::body::to_bytes(heartbeat_response.into_body(), 4096)
            .await
            .unwrap();
        let heartbeat_json: SessionHeartbeatResponse =
            serde_json::from_slice(&heartbeat_body).unwrap();
        assert_eq!(heartbeat_json.idle_timeout_secs, idle_ttl.as_secs());
        assert!(
            heartbeat_json.idle_reap_eligible_at.0 >= start_json.idle_reap_eligible_at.0,
            "a heartbeat must not move the idle-reaping boundary backwards"
        );

        // End the session, then heartbeat it: the shape an agent hits after the
        // sweeper reaps an idle session.
        let end_response = app
            .clone()
            .oneshot(
                Request::delete(format!("/session/{}", start_json.session_id))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(end_response.status(), StatusCode::OK);

        let dead_response = app
            .oneshot(
                Request::post(format!("/session/{}/heartbeat", start_json.session_id))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(dead_response.status(), StatusCode::NOT_FOUND);
        let dead_body = axum::body::to_bytes(dead_response.into_body(), 4096)
            .await
            .unwrap();
        let message = String::from_utf8(dead_body.to_vec()).unwrap();
        assert!(
            message.contains("expired") && message.contains("kin_session_start"),
            "an expired session must be named as expired and name its recovery: {message}"
        );
    }

