    #[test]
    fn the_mutation_disclosure_survives_the_route_budget() {
        // `mcp_tools_call` bounds every retrieval response after
        // `mcp_tools_call_inner` has built it, so the budget runs downstream of
        // this disclosure and could drop it without anything failing: the
        // answer would still be served, still carry rows, and simply no longer
        // say it was read under a write. The over-budget arm is the one that
        // touches this array, appending its own entry and withdrawing a
        // residual one, so an oversized payload is what has to be checked.
        let oversized = json!({
            "focal_entity": { "name": "resolve_redirects" },
            "total_upstream": 400,
            "references": (0..400).map(|index| json!({
                "name": format!("caller_{index}"),
                "file_path": format!("requests/module_{index}/handler.py"),
                "line": index,
                "relation_kind": "calls",
                "snippet": "def send(self, request, **kwargs):\n    return self.adapter.send(request)\n".repeat(6),
            })).collect::<Vec<_>>(),
        });
        let state = test_state();
        let built = kin_mcp::ToolCallResult::text(
            serde_json::to_string_pretty(&oversized).expect("fixture serializes"),
        );
        assert!(
            mcp_result_text(&built).len() > kin_mcp::budget::RESPONSE_DEFAULT_MAX_CHARS,
            "the fixture must overflow, or the arm that edits degradations never runs"
        );
        let disclosed =
            disclose_mutation_in_flight(built, &state).expect("an object payload discloses");
        let budget = kin_mcp::budget::ResponseBudget::default().less_envelope_reserve();
        let bounded = bound_mcp_tool_result(disclosed, "find_references", &budget);
        let body: serde_json::Value = serde_json::from_str(&mcp_result_text(&bounded)).unwrap();
        let labels = degradation_labels(&body);
        assert!(
            labels.contains(&"graph_authority:mutation_in_flight".to_string()),
            "the budget must not take the write disclosure with the bytes it cut: {}",
            body["degradations"]
        );
        assert!(
            labels.len() > 1,
            "the budget's own cut must also be disclosed here, or this fixture did not reach the \
             arm under test: {}",
            body["degradations"]
        );
    }

    #[tokio::test]
    async fn a_reference_read_that_never_detaches_a_snapshot_refuses_naming_the_write() {
        // A writer holding authority for the whole call means no attempt ever
        // detaches a snapshot, so there is no answer to serve. The refusal is
        // correct here; what it may never do is read as an absence.
        let (state, target) = reference_fixture();
        let arguments = find_references_arguments(&target);
        let held = state.begin_graph_authority_mutation();

        let error = mcp_find_references_with_stable_authority(
            &state,
            None,
            Arc::clone(&state.graph),
            RequestGraphAuthority::Head,
            &arguments,
            |_| {},
        )
        .await
        .expect_err("no snapshot was ever detached, so nothing may be served");
        let message = error.to_string();
        assert!(
            message.contains("not an absent or unresolved symbol"),
            "the refusal must separate a write window from an absence: {message}"
        );
        assert!(
            message.contains("a graph-authority writer was mutating the graph"),
            "the refusal must name the writer: {message}"
        );
        assert_names_what_would_change_it(&message);

        // With the sweep flag set, the same refusal names the sweep instead,
        // because that is the one writer identity the daemon holds at read time.
        state
            .lsp_sweep_running
            .store(true, std::sync::atomic::Ordering::SeqCst);
        let swept = mcp_find_references_with_stable_authority(
            &state,
            None,
            Arc::clone(&state.graph),
            RequestGraphAuthority::Head,
            &arguments,
            |_| {},
        )
        .await
        .expect_err("no snapshot was ever detached, so nothing may be served")
        .to_string();
        assert!(
            swept.contains("a language-server enrichment sweep was installing relations"),
            "the refusal must name the sweep when a sweep is what is running: {swept}"
        );
        assert_names_what_would_change_it(&swept);
        drop(held);
    }

    #[tokio::test]
    async fn a_superseded_focal_miss_refuses_rather_than_publishing_entity_not_found() {
        // The ticket's sharpest clause. An unresolved focal and a symbol with no
        // references are different facts, and a focal miss taken while a writer
        // was moving is neither: it is a read that could not be certified.
        // Serving it would put "Entity not found" in front of an agent for an
        // entity the same store may resolve a moment later.
        //
        // Addressed by `entity_id` deliberately: the name-index early-out ahead
        // of the loop answers a ruled-out NAME before any attempt runs, so an
        // absent id is the only way to reach exhaustion holding a focal miss.
        let (state, _target) = reference_fixture();
        let arguments = serde_json::from_value::<HashMap<String, serde_json::Value>>(json!({
            "entity_id": EntityId::new().to_string(),
        }))
        .unwrap();

        let message = mcp_find_references_with_stable_authority(
            &state,
            None,
            Arc::clone(&state.graph),
            RequestGraphAuthority::Head,
            &arguments,
            supersede_every_attempt(&state),
        )
        .await
        .expect_err("a superseded focal miss is never published as settled")
        .to_string();
        assert!(
            !message.contains(kin_mcp::handlers::entities::FIND_REFERENCES_FOCAL_MISS),
            "a write window must never be reported as an unresolved symbol: {message}"
        );
        assert!(
            message.contains("not an absent or unresolved symbol"),
            "the refusal must say what it is not: {message}"
        );
        assert_names_what_would_change_it(&message);
    }

    #[tokio::test]
    async fn contended_reference_reads_spread_their_attempts_across_real_time() {
        // The retry budget was three attempts inside one instant. `yield_now`
        // would not have fixed it either: it reorders ready tasks without the
        // clock advancing, and the sweep's writers do filesystem and
        // content-address work on blocking threads that no async yield waits
        // for. So the wait has to be a real sleep, and the floor is what proves
        // it happened.
        //
        // Three attempts, and the last one does not nap because nothing reads
        // its result. That leaves 50 ms then 100 ms.
        let expected = GRAPH_STATUS_WRITER_SETTLE_FLOOR + GRAPH_STATUS_WRITER_SETTLE_FLOOR * 2;
        let (state, target) = reference_fixture();
        let started = std::time::Instant::now();
        mcp_find_references_with_stable_authority(
            &state,
            None,
            Arc::clone(&state.graph),
            RequestGraphAuthority::Head,
            &find_references_arguments(&target),
            supersede_every_attempt(&state),
        )
        .await
        .expect("a superseded reference read is served");
        let elapsed = started.elapsed();
        assert!(
            elapsed >= expected,
            "a fully contended read must outlast a brief writer, not spend its budget in one \
             instant: {elapsed:?} elapsed, {expected:?} required"
        );
    }

    /// Fail-loud contract: when a spine endpoint IS configured but the daemon
    /// answers non-2xx (e.g. `503` because the spine is disabled), every client
    /// surface must report the gap as `SpineQuery::Unavailable` — never collapse
    /// it into a silent empty result (the old `Ok(None)` swallow) nor a quiet
    /// `NotConfigured`. This is the cross-repo analogue of the graph-first
    /// "fail loud or report the gap" rule, enforced across CLI and MCP.
    #[tokio::test]
    #[serial_test::serial]
    async fn spine_clients_surface_unavailable_on_non_success_status() {
        use kin_cli::backend::{get_spine_impact, get_spine_xref};
        use kin_mcp::handlers::common::{fetch_spine_impact_typed, fetch_spine_xref};

        // A stand-in daemon that answers every route 503. No real graph and no
        // autostart — the clients reach it purely through KIN_DAEMON_URL.
        async fn always_unavailable() -> StatusCode {
            StatusCode::SERVICE_UNAVAILABLE
        }
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let addr = listener.local_addr().unwrap();
        let server = tokio::spawn(async move {
            let _ = axum::serve(listener, Router::new().fallback(always_unavailable)).await;
        });
        let _daemon_url =
            kin_core::test_env::EnvVarGuard::set("KIN_DAEMON_URL", format!("http://{addr}"));

        let layout = test_state().layout.clone();
        let repo = "consumer";
        let entity = EntityId::new();

        // ── CLI xref: configured-but-failing must be Unavailable, naming 503. ──
        match get_spine_xref(&layout, repo, &entity)
            .await
            .expect("CLI get_spine_xref call")
        {
            kin_spine::SpineQuery::Unavailable(reason) => {
                assert!(
                    reason.contains("503"),
                    "reason must name the status: {reason}"
                );
            }
            other => panic!("CLI xref must be Unavailable on 503, got {other:?}"),
        }

        // ── CLI impact: the surface migrated off the Ok(None) swallow. ──
        match get_spine_impact(&layout, repo, &entity, 5)
            .await
            .expect("CLI get_spine_impact call")
        {
            kin_spine::SpineQuery::Unavailable(reason) => {
                assert!(
                    reason.contains("503"),
                    "reason must name the status: {reason}"
                );
            }
            other => panic!("CLI impact must be Unavailable on 503, got {other:?}"),
        }

        // ── MCP xref + impact: same fail-loud contract. ──
        match fetch_spine_xref(repo, &entity).await {
            kin_spine::SpineQuery::Unavailable(_) => {}
            other => panic!("MCP xref must be Unavailable on 503, got {other:?}"),
        }
        match fetch_spine_impact_typed(repo, &entity, 5).await {
            kin_spine::SpineQuery::Unavailable(_) => {}
            other => panic!("MCP impact must be Unavailable on 503, got {other:?}"),
        }

        server.abort();
    }

    /// Names its repository and spine endpoint by argument on purpose. An
    /// earlier version set `KIN_REPO_ID` and `KIN_DAEMON_URL`, which are
    /// process-global, and under `cargo test` this binary's ~600 tests are
    /// threads in one process, so every test that opened a daemon state while
    /// this one held `KIN_REPO_ID=provider` was refused against its own
    /// manifest authority. `#[serial]` cannot prevent that: it orders a test
    /// only against other serial tests. Under nextest, which gives each test
    /// its own process, the defect is structurally invisible.
    #[tokio::test]
    async fn mcp_find_references_reports_legacy_xref_payload_as_unavailable() {
        async fn legacy_xref() -> Json<serde_json::Value> {
            Json(serde_json::json!({
                "version": kin_spine::SPINE_PAYLOAD_VERSION,
                "edges": [{
                    "repo_id": "consumer",
                    "from_name": "run_task",
                    "to_repo_id": "provider",
                    "kind": "calls",
                }],
            }))
        }

        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let addr = listener.local_addr().unwrap();
        let server = tokio::spawn(async move {
            let _ = axum::serve(listener, Router::new().fallback(legacy_xref)).await;
        });
        let binding = kin_mcp::handlers::entities::AmbientCrossRepoBinding::new(
            Some("provider"),
            Some(&format!("http://{addr}")),
        );

        let target = test_entity("do_work", "src/lib.rs");
        let graph = kin_db::InMemoryGraph::new();
        graph.upsert_entity(&target).unwrap();
        let args = HashMap::from([(
            "entity_id".to_string(),
            serde_json::json!(target.id.to_string()),
        )]);
        let result = kin_mcp::handlers::entities::handle_find_references_with_ambient_binding(
            &args, &graph, binding, None,
        )
        .await
        .unwrap();
        let kin_mcp::types::ContentBlock::Text { text } = result
            .content
            .first()
            .expect("find_references text response");
        let body: serde_json::Value = serde_json::from_str(text).unwrap();
        assert_eq!(body["cross_repo"]["status"], "unavailable");
        assert!(body["cross_repo"]["reason"]
            .as_str()
            .is_some_and(|reason| reason.contains("malformed spine xref response")));
        assert_eq!(body["total_upstream"], 0);

        server.abort();
    }

    /// Names its binding by argument for the reason given on
